+<?php
+
+namespace Tests\Unit\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use App\Http\Requests\PengawasanPerizinanBerusaha\Penjadwalan\UploadSuratTugasRequest;
+use Illuminate\Support\Facades\Validator;
+use Illuminate\Http\UploadedFile;
+use Tests\TestCase;
+
+class UploadSuratTugasRequestTest extends TestCase
+{
+    private UploadSuratTugasRequest $request;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        $this->request = new UploadSuratTugasRequest();
+    }
+
+    public function test_it_allows_valid_pdf_file_within_size_limit()
+    {
+        $file = UploadedFile::fake()->create('surat_tugas.pdf', 1024, 'application/pdf');
+
+        $validator = Validator::make(
+            ['file' => $file],
+            $this->request->rules(),
+            $this->request->messages()
+        );
+
+        $this->assertTrue($validator->passes());
+    }
+
+    public function test_it_fails_if_file_is_not_provided()
+    {
+        $validator = Validator::make(
+            [],
+            $this->request->rules(),
+            $this->request->messages()
+        );
+
+        $this->assertFalse($validator->passes());
+        $this->assertEquals('File Surat Tugas wajib diupload', $validator->errors()->first('file'));
+    }
+
+    public function test_it_fails_if_file_is_not_pdf()
+    {
+        $file = UploadedFile::fake()->create('surat_tugas.jpg', 1024, 'image/jpeg');
+
+        $validator = Validator::make(
+            ['file' => $file],
+            $this->request->rules(),
+            $this->request->messages()
+        );
+
+        $this->assertFalse($validator->passes());
+        $this->assertEquals('File Surat Tugas harus berupa PDF', $validator->errors()->first('file'));
+    }
+
+    public function test_it_fails_if_file_exceeds_max_size()
+    {
+        // size > 5120 KB
+        $file = UploadedFile::fake()->create('surat_tugas_large.pdf', 6000, 'application/pdf');
+
+        $validator = Validator::make(
+            ['file' => $file],
+            $this->request->rules(),
+            $this->request->messages()
+        );
+
+        $this->assertFalse($validator->passes());
+        $this->assertEquals('File Surat Tugas maksimal 5 MB', $validator->errors()->first('file'));
+    }
+}

