@@ -926,4 +926,27 @@ public static function normalizeNoTandaDaftar(?string $nomor): ?string

         return $nomor;
     }
+
+    /**
+     * Memotong angka desimal tanpa melakukan pembulatan (truncate).
+     * Cocok digunakan untuk persentase atau nilai riil di mana pembulatan ke atas tidak diinginkan.
+     * Contoh: 61.458 -> "61.45"
+     */
+    public static function truncateDecimal($value, int $decimals = 2): ?string
+    {
+        if ($value === null || $value === '') {
+            return null;
+        }
+
+        $valueStr = (string) $value;
+        $dotPos = strpos($valueStr, '.');
+
+        if ($dotPos !== false) {
+            $truncated = substr($valueStr, 0, $dotPos + $decimals + 1);
+        } else {
+            $truncated = $valueStr;
+        }
+
+        return number_format((float)$truncated, $decimals, '.', '');
+    }
 }
