+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'doctor';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Perform pre-production checks for the application';
+
+    /**
+     * Execute the console command.
+     */
+    public function handle()
+    {
+        $this->components->info('Starting Pre-Production Checks (Laravel Doctor)...');
+
+        $this->checkEnvironment();
+        $this->checkOptimization();
+        $this->checkStorage();
+        $this->checkDatabase();
+        $this->checkRedis();
+        $this->checkExternalServices();
+
+        $this->components->info('Pre-Production checks completed.');
+        
+        return self::SUCCESS;
+    }
+
+    protected function checkEnvironment(): void
+    {
+        $this->components->twoColumnDetail('<fg=gray>Environment</> APP_ENV', env('APP_ENV') === 'production' ? '<fg=green>production</>' : '<fg=yellow>' . env('APP_ENV') . '</>');
+        $this->components->twoColumnDetail('<fg=gray>Environment</> APP_DEBUG', env('APP_DEBUG') == false ? '<fg=green>false</>' : '<fg=yellow>true</>');
+        
+        $appKey = env('APP_KEY');
+        $this->components->twoColumnDetail('<fg=gray>Environment</> APP_KEY', !empty($appKey) ? '<fg=green>SET</>' : '<fg=red>MISSING</>');
+        
+        $jwtSecret = env('JWT_SECRET');
+        $this->components->twoColumnDetail('<fg=gray>Environment</> JWT_SECRET', !empty($jwtSecret) ? '<fg=green>SET</>' : '<fg=red>MISSING</>');
+    }
+
+    protected function checkOptimization(): void
+    {
+        $this->components->twoColumnDetail('<fg=gray>Optimization</> Config Cached', app()->configurationIsCached() ? '<fg=green>YES</>' : '<fg=yellow>NO</>');
+        $this->components->twoColumnDetail('<fg=gray>Optimization</> Routes Cached', app()->routesAreCached() ? '<fg=green>YES</>' : '<fg=yellow>NO</>');
+    }
+
+    protected function checkStorage(): void
+    {
+        $storageLink = public_path('storage');
+        $this->components->twoColumnDetail('<fg=gray>Storage</> Public Symlink', file_exists($storageLink) ? '<fg=green>EXISTS</>' : '<fg=red>MISSING</>');
+        
+        $storagePath = storage_path();
+        $this->components->twoColumnDetail('<fg=gray>Storage</> Storage Writable', is_writable($storagePath) ? '<fg=green>YES</>' : '<fg=red>NO</>');
+        
+        $cachePath = app()->bootstrapPath('cache');
+        $this->components->twoColumnDetail('<fg=gray>Storage</> Bootstrap Cache Writable', is_writable($cachePath) ? '<fg=green>YES</>' : '<fg=red>NO</>');
+    }
+
+    protected function checkDatabase(): void
+    {
+        $connections = [
+            'MDI (Default)' => config('database.default'),
+            'ESLO Master' => env('ESLO_MASTER_DB_CONNECTION'),
+            'ESLO Transaksi' => env('ESLO_TRANSAKSI_DB_CONNECTION'),
+            'E-Logbook' => env('ELOGBOOK_DB_CONNECTION'),
+        ];
+
+        foreach ($connections as $name => $connection) {
+            if (empty($connection)) {
+                $this->components->twoColumnDetail("<fg=gray>Database</> {$name}", '<fg=yellow>SKIPPED (Not Configured)</>');
+                continue;
+            }
+
+            try {
+                DB::connection($connection)->getPdo();
+                $this->components->twoColumnDetail("<fg=gray>Database</> {$name}", '<fg=green>CONNECTED</>');
+            } catch (\Exception $e) {
+                $this->components->twoColumnDetail("<fg=gray>Database</> {$name}", '<fg=red>FAILED</>');
+                $this->error("DB {$name} Error: " . $e->getMessage());
+            }
+        }
+    }
+
+    protected function checkRedis(): void
+    {
+        try {
+            Redis::connection()->ping();
+            $this->components->twoColumnDetail('<fg=gray>Redis</> Connection', '<fg=green>CONNECTED</>');
+            
+            // Also test cache
+            Cache::store('redis')->put('doctor_test', '1', 10);
+            $this->components->twoColumnDetail('<fg=gray>Cache</> Redis Writable', '<fg=green>YES</>');
+        } catch (\Exception $e) {
+            $this->components->twoColumnDetail('<fg=gray>Redis</> Connection', '<fg=red>FAILED</>');
+            $this->error('Redis Error: ' . $e->getMessage());
+        }
+    }
