+            'E-Cuti (Pegawai)' => env('ENDPOINT_PEGAWAI'),
+            'SILAT' => env('API_SILAT'),
+            'ESLO' => env('API_ESLO'),
+            'OSS' => env('API_OSS_HOST'),
+            'Kemendagri' => env('API_KEMENDAGRI_HOST'),
+            'Portal Korespondensi' => env('API_PORTAL_KRSP_HOST'),
+            'TPKP Nasional' => env('API_TPKP_HOST'),
+            'CC (VMS)' => env('API_CC_HOST'),
+        ];
+
+        foreach ($services as $name => $url) {
+            if (empty($url)) {
+                $this->components->twoColumnDetail("<fg=gray>Gateway</> {$name}", '<fg=yellow>SKIPPED</>');
+                continue;
+            }
+
+            try {
+                // Just doing a simple HEAD or GET request might fail due to auth, 
+                // but checking the DNS/ping is safer or checking if host is reachable.
+                // We'll use Http::timeout(3)->get() and check if it throws connection error.
+                // If it returns 401/403/404, it means the server is reachable.
+                $response = Http::timeout(3)->get($url);
+                $this->components->twoColumnDetail("<fg=gray>Gateway</> {$name}", '<fg=green>REACHABLE</>');
+            } catch (\Exception $e) {
+                $this->components->twoColumnDetail("<fg=gray>Gateway</> {$name}", '<fg=red>UNREACHABLE</>');
+            }
+        }
+    }
+}
