+<?php
+
+namespace App\Console\Commands;
+
+use Illuminate\Console\Command;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use Illuminate\Support\Facades\DB;
+
+class MigrateLegacyPenjadwalanCommand extends Command
+{
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'ppbbr:migrate-legacy-penjadwalan';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Memigrasikan file path dari kolom legacy (ST, SP, STKL) ke tabel ppbbr_dokumen_penjadwalan';
+
+    /**
+     * Execute the console command.
+     */
+    public function handle()
+    {
+        $this->info('Memulai migrasi data legacy penjadwalan...');
+
+        $objeks = ObjekPengawasan::whereNotNull('surat_tugas')
+            ->orWhereNotNull('surat_pemberitahuan')
+            ->orWhereNotNull('stkl')
+            ->get();
+
+        $this->info('Ditemukan ' . $objeks->count() . ' objek pengawasan yang memiliki data legacy.');
+
+        $bar = $this->output->createProgressBar($objeks->count());
+
+        DB::beginTransaction();
+        try {
+            foreach ($objeks as $objek) {
+                // Migrasi Surat Tugas
+                if ($objek->surat_tugas && $objek->surat_tugas !== 'korespondensi' && $objek->surat_tugas !== 'manual') {
+                    DokumenPenjadwalan::firstOrCreate([
+                        'objek_pengawasan_id' => $objek->id,
+                        'jenis_dokumen' => 'surat_tugas',
+                        'file_path' => $objek->surat_tugas,
+                    ], [
+                        'is_active' => true,
+                    ]);
+                }
+
+                // Migrasi Surat Pemberitahuan
+                if ($objek->surat_pemberitahuan && $objek->surat_pemberitahuan !== 'ada') {
+                    // TODO: Refactor ketika pola penentuan UPT/OSS sudah jelas
+                    // Saat ini di-assign secara random
+                    $jenisSp = (rand(0, 1) === 0) ? 'surat_pemberitahuan_oss' : 'surat_pemberitahuan_upt';
+
+                    DokumenPenjadwalan::firstOrCreate([
+                        'objek_pengawasan_id' => $objek->id,
+                        'jenis_dokumen' => $jenisSp,
+                        'file_path' => $objek->surat_pemberitahuan,
+                    ], [
+                        'is_active' => true,
+                    ]);
+                }
+
+                // Migrasi STKL
+                if ($objek->stkl && $objek->stkl !== 'ada') {
+                    DokumenPenjadwalan::firstOrCreate([
+                        'objek_pengawasan_id' => $objek->id,
+                        'jenis_dokumen' => 'stkl',
+                        'file_path' => $objek->stkl,
+                    ], [
+                        'is_active' => true,
+                    ]);
+                }
+
+                $bar->advance();
+            }
+
+            DB::commit();
+            $bar->finish();
+            $this->newLine();
+            $this->info('Migrasi selesai!');
+
+        } catch (\Exception $e) {
+            DB::rollBack();
+            $this->error('Terjadi kesalahan: ' . $e->getMessage());
+        }
+    }
+}
