+<?php
+
+namespace App\Console\Commands\PengawasanPerizinanBerusaha;
+
+use Illuminate\Console\Command;
+use PhpOffice\PhpSpreadsheet\IOFactory;
+use App\Jobs\Wasrisk\SyncSingleWasriskJob;
+use Illuminate\Support\Facades\Artisan;
+use Modules\Gateway\Services\PORTAL\KorespondensiService;
+
+class SyncDummyWasriskCommand extends Command
+{
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'wasrisk:sync-dummy {--ref_number= : Nomor Referensi spesifik untuk di-sync} {--download_file=false : Unduh fisik PDF aslinya}';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Sinkronisasi data dummy WASRISK dari Excel ke portal_dokumen CSRS';
+
+    /**
+     * Execute the console command.
+     *
+     * @return int
+     */
+    public function handle()
+    {
+        $this->info('Memulai sinkronisasi data dummy WASRISK...');
+
+        // 1. UPDATE DOKUMEN_ID DARI JSON PRODUCTION (Agar tidak 404 saat unduh)
+        $jsonPath = base_path('docs/review/dummySurat/portal_202609041036.json');
+        if (file_exists($jsonPath)) {
+            $this->info('Membaca file JSON Production untuk injeksi dokumen_id...');
+            $jsonContent = file_get_contents($jsonPath);
+            $data = json_decode($jsonContent, true);
+            if ($data) {
+                $records = reset($data); // Mengambil value array pertama
+                $injectedCount = 0;
+                foreach ($records as $record) {
+                    $updateData = [
+                        'dokumen_id' => $record['dokumen_id'],
+                        'letter_date' => $record['letter_date'] ?? date('Y-m-d')
+                    ];
+                    if (isset($record['km'])) {
+                        $updateData['km'] = $record['km'];
+                    }
+                    \Modules\Gateway\Entities\PortalDokumen::updateOrCreate(
+                        ['ref_number' => $record['ref_number']],
+                        $updateData
+                    );
+                    $injectedCount++;
+                }
+                $this->info("Berhasil menginjeksi {$injectedCount} dokumen_id dari JSON.");
+            }
+        }
+
+        $filePath = base_path('docs/review/dummySurat/20260902_datasampel_dokumentasi untuk WASRISK.xlsx');
+        
+        if (!file_exists($filePath)) {
+            $this->error("File Excel tidak ditemukan: {$filePath}");
+            return Command::FAILURE;
+        }
+
+        try {
+            $this->info('Membaca file Excel...');
+            $spreadsheet = IOFactory::load($filePath);
+            $worksheet = $spreadsheet->getActiveSheet();
+            $rows = $worksheet->toArray();
+            
+            // Hapus baris header (index 0)
+            $headers = array_shift($rows);
+            
+            $korespondensiService = new KorespondensiService();
+            
+            if ($korespondensiService->isGatewayDown()) {
+                $this->error('Gateway CSRS sedang down atau tidak dapat diakses.');
+                return Command::FAILURE;
+            }
+
+            $successCount = 0;
+            $failedCount = 0;
+            $notFoundCount = 0;
+
+            $this->output->progressStart(count($rows));
+
+            foreach ($rows as $index => $row) {
+                // Berdasarkan index kolom dari Python: 
+                // 0: kategori, 1: KM, 2: Nomor Referensi, 3: Tanggal Surat, 4: Pengirim, 5: Subject/Perihal
+                
+                $refNumber = $row[2] ?? null;
+                
+                if (empty($refNumber)) {
+                    $this->output->progressAdvance();
+                    continue;
+                }
+
+                $targetRefNumber = $this->option('ref_number');
+                if ($targetRefNumber && $refNumber !== $targetRefNumber) {
+                    $this->output->progressAdvance();
+                    continue;
+                }
+
+                $shouldDownload = $this->option('download_file') === 'true' || $this->option('download_file') === true;
+                
+                $foundItemData = [
+                    'date' => $row[3] ?? null,
+                    'km' => $row[1] ?? null,
+                    'subject' => $row[5] ?? null,
+                    'sender' => $row[4] ?? null,
+                ];
+
+                // Dispatch ke antrean agar dieksekusi oleh worker secara background (tidak memberatkan command)
+                SyncSingleWasriskJob::dispatch($refNumber, $shouldDownload, $foundItemData)->onQueue('default');
+                
+                $successCount++;
+                $this->output->progressAdvance();
+            }
+
+            $this->output->progressFinish();
+            
+            $this->info("Sinkronisasi Selesai!");
