+<?php
+
+namespace App\Http\Requests\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use Illuminate\Foundation\Http\FormRequest;
+use App\Http\Library\EnkripsiHelper;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use Closure;
+
+class PencarianDokumenCsrsRequest extends FormRequest
+{
+    use EnkripsiHelper;
+
+    public function authorize(): bool
+    {
+        return true;
+    }
+
+    public function rules(): array
+    {
+        return [
+            /**
+             * ID Objek Pengawasan yang sedang aktif (encrypted)
+             * @example eyJpdiI6I...
+             */
+            'objek_pengawasan_id' => ['required', 'string', function (string $attribute, mixed $value, Closure $fail) {
+                $objekPengawasanId = $this->dekrip($value);
+                if (!$objekPengawasanId) {
+                    $fail($attribute.' tidak valid.');
+                }
+                $objekPengawasan = ObjekPengawasan::find($objekPengawasanId);
+                if (!$objekPengawasan) {
+                    $fail('Objek Pengawasan tidak ditemukan');
+                }
+            }],
+
+            /**
+             * Jenis Dokumen yang dicari
+             * @example surat_tugas
+             */
+            'jenis_dokumen' => 'required|string|in:notula,surat_pemberitahuan_oss,surat_pemberitahuan_upt,stkl,surat_tugas',
+
+            /**
+             * Mode pencarian (pilih atau cari). Default: pilih
+             * @example pilih
+             */
+            'mode' => 'nullable|string|in:pilih,cari',
+
+            /**
+             * Kata kunci pencarian dokumen di CSRS (berdasarkan Nomor Surat / Perihal). Wajib jika mode = cari
+             * @example B.123/PSDKP
+             */
+            'keyword' => 'required_if:mode,cari|nullable|string|min:3',
+        ];
+    }
+}
