@@ -0,0 +1,90 @@
+<?php
+
+namespace App\Http\Requests\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use Illuminate\Foundation\Http\FormRequest;
+use App\Http\Library\EnkripsiHelper;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use Closure;
+
+class SimpanDokumenRequest extends FormRequest
+{
+    use EnkripsiHelper;
+
+    public function authorize(): bool
+    {
+        return true;
+    }
+
+    public function rules(): array
+    {
+        return [
+            /**
+             * ID Dokumen dari CSRS (wajib jika tidak upload file manual).
+             * @example 10293
+             */
+            'portal_dokumen_id' => ['required_without:file', 'nullable', 'string', function (string $attribute, mixed $value, Closure $fail) {
+                if ($value) {
+                    $portalDokumenId = $this->dekrip($value);
+                    if (!$portalDokumenId) {
+                        $fail($attribute.' tidak valid.');
+                    }
+                }
+            }],
+
+            /**
+             * File PDF manual (wajib jika tidak memilih dari CSRS). Maks 5MB.
+             */
+            'file' => 'required_without:portal_dokumen_id|nullable|file|mimes:pdf|max:5120',
+
+            /**
+             * Jenis Dokumen yang disimpan.
+             * @example surat_tugas
+             */
+            'jenis_dokumen' => 'required|string|in:notula,surat_pemberitahuan_oss,surat_pemberitahuan_upt,stkl,surat_tugas',
+
+            /**
+             * Array ID Objek Pengawasan yang akan di-assign dokumen ini (mendukung Bulk Save).
+             * @example [1, 2, 3]
+             */
+            'objek_pengawasan_ids' => 'required|array|min:1',
+            'objek_pengawasan_ids.*' => ['string', function (string $attribute, mixed $value, Closure $fail) {
+                $objekPengawasanId = $this->dekrip($value);
+                if (!$objekPengawasanId) {
+                    $fail($attribute.' tidak valid.');
+                }
+                $objekPengawasan = ObjekPengawasan::find($objekPengawasanId);
+                if (!$objekPengawasan) {
+                    $fail('Objek Pengawasan tidak ditemukan');
+                }
+            }],
+            
+            /**
+             * ID Sesi Redis jika dokumen ini merupakan hasil ekstraksi otomatis (Opsional).
+             * @example sess_5f2c3a
+             */
+            'session_id' => 'nullable|string',
+
+            /**
+             * Data identitas dokumen untuk upload manual.
+             */
+            'manual_nomor_surat' => 'nullable|string|max:255',
+            'manual_tanggal_surat' => 'nullable|date',
+            'manual_perihal' => 'nullable|string|max:255',
+            'penerbit_nip' => 'nullable|string|max:255',
+        ];
+    }
+
+    public function withValidator($validator)
+    {
+        $validator->after(function ($validator) {
+            $jenisManualSaja = ['notula', 'surat_pemberitahuan_oss', 'stkl'];
+            
+            if (in_array($this->jenis_dokumen, $jenisManualSaja)) {
+                if (!$this->hasFile('file')) {
+                    $validator->errors()->add('file', "Dokumen {$this->jenis_dokumen} hanya mendukung metode Unggah Surat (Manual Upload PDF).");
+                }
+            }
+        });
+    }
+}
