+<?php
+
+namespace App\Jobs\Wasrisk;
+
+use Illuminate\Bus\Queueable;
+use Illuminate\Contracts\Queue\ShouldQueue;
+use Illuminate\Foundation\Bus\Dispatchable;
+use Illuminate\Queue\InteractsWithQueue;
+use Illuminate\Queue\SerializesModels;
+use Illuminate\Support\Facades\Log;
+use Modules\Gateway\Services\PORTAL\KorespondensiService;
+use Modules\Gateway\Entities\PortalDokumen;
+use Modules\Gateway\Entities\PortalPenerimaDokumen;
+use Carbon\Carbon;
+
+class SyncSingleWasriskJob implements ShouldQueue
+{
+    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
+
+    public $timeout = 600; // 10 menit
+    public $tries = 1;
+
+    protected $refNumber;
+    protected $shouldDownload;
+    protected $foundItemData; // data fallback dari excel
+
+    protected const UNIT = [
+        ["id" => 830, "name" => "DIREKTORAT JENDERAL PENGAWASAN SUMBER DAYA KELAUTAN DAN PERIKANAN"],
+        ["id" => 831, "name" => "SEKRETARIAT DITJEN PENGAWASAN SUMBER DAYA KELAUTAN DAN PERIKANAN"],
+        ["id" => 1739, "name" => "DIREKTORAT PRASARANA DAN SARANA PENGAWASAN"],
+        ["id" => 849, "name" => "DIREKTORAT PENGENDALIAN OPERASI ARMADA"],
+        ["id" => 934, "name" => "DIREKTORAT PENGAWASAN SUMBER DAYA KELAUTAN"],
+        ["id" => 949, "name" => "DIREKTORAT PENGAWASAN SUMBER DAYA PERIKANAN"],
+        ["id" => 964, "name" => "DIREKTORAT PENANGANAN PELANGGARAN"],
+        ["id" => 864, "name" => "PANGKALAN PSDKP LAMPULO"],
+        ["id" => 869, "name" => "PANGKALAN PSDKP BATAM"],
+        ["id" => 874, "name" => "PANGKALAN PSDKP JAKARTA"],
+        ["id" => 879, "name" => "PANGKALAN PSDKP BENOA"],
+        ["id" => 884, "name" => "PANGKALAN PSDKP BITUNG"],
+        ["id" => 889, "name" => "PANGKALAN PSDKP TUAL"],
+        ["id" => 894, "name" => "STASIUN PSDKP CILACAP"],
+        ["id" => 899, "name" => "STASIUN PSDKP BELAWAN"],
+        ["id" => 904, "name" => "STASIUN PSDKP KUPANG"],
+        ["id" => 909, "name" => "STASIUN PSDKP PONTIANAK"],
+        ["id" => 914, "name" => "STASIUN PSDKP TARAKAN"],
+        ["id" => 919, "name" => "STASIUN PSDKP TAHUNA"],
+        ["id" => 924, "name" => "STASIUN PSDKP AMBON"],
+        ["id" => 929, "name" => "STASIUN PSDKP BIAK"]
+    ];
+
+    /**
+     * Create a new job instance.
+     *
+     * @return void
+     */
+    public function __construct(string $refNumber, bool $shouldDownload, array $foundItemData = [])
+    {
+        $this->refNumber = $refNumber;
+        $this->shouldDownload = $shouldDownload;
+        $this->foundItemData = $foundItemData;
+    }
+
+    /**
+     * Execute the job.
+     *
+     * @return void
+     */
+    public function handle()
+    {
+        Log::info("[WASRISK JOB] Memulai pencarian untuk Ref: {$this->refNumber}");
+        $korespondensiService = new KorespondensiService();
+
+        // Cek apakah data sudah ada di DB
+        $existingDoc = PortalDokumen::where('ref_number', $this->refNumber)->first();
+        if ($existingDoc) {
+            if ($this->shouldDownload) {
+                try {
+                    $encryptedId = $korespondensiService->enkrip((string) $existingDoc->dokumen_id);
+                    $korespondensiService->downloadDokumenSurat($encryptedId);
+                    $this->copyDownloadedFile($this->refNumber, $encryptedId, (string) $existingDoc->dokumen_id);
+                    Log::info("[WASRISK JOB] File PDF diunduh untuk Ref {$this->refNumber} (Data sudah ada di DB)");
+                } catch (\Exception $e) {
+                    Log::error("[WASRISK JOB] Gagal download PDF {$this->refNumber}: " . $e->getMessage());
+                }
+            }
+            return; // Berhenti karena data sudah ada, hanya proses unduh
+        }
+
+        $foundItem = null;
+        $foundUnitName = '';
+
+        // Loop ke semua unit untuk mencari surat ini
+        foreach (self::UNIT as $unit) {
+            try {
+                $searchResult = $korespondensiService->daftarDokumenSurat($this->refNumber, 1, 1000, null, null, null, $unit['id'], false);
+
+                if ($searchResult && !empty($searchResult->results)) {
+                    foreach ($searchResult->results as $item) {
+                        if ($item->ref_number === $this->refNumber) {
+                            $foundItem = (object) $item;
+                            $foundUnitName = $unit['name'];
+                            break 2; // Ketemu, keluar dari loop unit
+                        }
+                    }
+                }
+            } catch (\Exception $e) {
+                if (str_contains($e->getMessage(), 'tidak dapat diakses')) {
+                    Log::error("[WASRISK JOB] Gateway Down saat mengecek Unit {$unit['name']}");
+                    break;
+                }
+            }
+        }
+
+        if (!$foundItem) {
+            Log::warning("[WASRISK JOB] Tidak ditemukan di Gateway: {$this->refNumber}");
+            return;
+        }
+
+        $dokumenId = $foundItem->id;
+        // 1. Download PDF-nya
+        if ($this->shouldDownload) {
+            try {
+                $encryptedId = $korespondensiService->enkrip((string) $dokumenId);
+                $korespondensiService->downloadDokumenSurat($encryptedId);
+                $this->copyDownloadedFile($this->refNumber, $encryptedId, (string) $dokumenId);
+                Log::info("[WASRISK JOB] File PDF diunduh untuk Ref {$this->refNumber}");
+            } catch (\Exception $e) {
+                Log::error("[WASRISK JOB] Gagal download PDF {$this->refNumber}: " . $e->getMessage());
+            }
+        }
+
+        // 2. Simpan DB Langsung
+        try {
+            $detailDokumen = $korespondensiService->detailDokumenSurat($dokumenId);
+
+            $excelDate = $this->foundItemData['date'] ?? null;
+            $formatDate = null;
+            if ($excelDate) {
+                try {
+                    $formatDate = Carbon::createFromFormat('d M Y', $excelDate)->format('Y-m-d');
+                } catch (\Exception $e) {
+                    $formatDate = date('Y-m-d', strtotime($excelDate));
+                }
+            }
+
+            PortalDokumen::updateOrCreate(
+                ['ref_number' => $this->refNumber],
+                [
+                    'dokumen_id' => $dokumenId,
+                    'km' => $this->foundItemData['km'] ?? ($foundItem->km ?? null),
+                    'subject' => $this->foundItemData['subject'] ?? ($foundItem->subject ?? null),
+                    'sender' => $this->foundItemData['sender'] ?? ($foundItem->sender ?? null),
+                    'date' => $formatDate,
+                    'time' => $foundItem->time ?? null,
+                    'letter_date' => $detailDokumen->letter_date ?? null,
+                    'create_date' => $detailDokumen->create_date ?? null,
+                    'category' => $detailDokumen->category ?? null,
+                    'type' => $detailDokumen->type ?? null,
+                    'priority' => $detailDokumen->priority ?? null,
+                    'security' => $detailDokumen->security ?? null,
+                    'dokumen' => $detailDokumen->dokumen ?? ('/api/v1/korespondensi/file/' . $dokumenId),
+                    'additional_data' => isset($detailDokumen->additional_data) ? json_encode($detailDokumen->additional_data) : null,
+                    'status' => 1,
+                    'has_used' => 0,
+                    'has_related_subjek_hukum' => 0,
+                    'is_manual' => 1
+                ]
+            );
+
+            PortalPenerimaDokumen::updateOrCreate(
+                ['dokumen_id' => $dokumenId, 'jenis' => 'internal'],
+                [
+                    'nip' => '123456789',
+                    'name' => 'SYSTEM SYNC WASRISK',
+                    'unit' => 'PSDKP PUSAT'
+                ]
+            );
+
+            Log::info("[WASRISK JOB] Berhasil disimpan ke DB untuk {$this->refNumber} dari Unit {$foundUnitName}");
+        } catch (\Exception $e) {
+            Log::error("[WASRISK JOB] Gagal menyimpan DB untuk {$this->refNumber}: " . $e->getMessage());
+        }
+    }
+
+    protected function copyDownloadedFile(string $refNumber, string $encryptedId, string $dokumenId)
+    {
+        $baseDir = public_path('bucket/s3_default/file/korespondensi/' . $encryptedId);
+        if (!is_dir($baseDir)) return;
+
+        $files = glob($baseDir . DIRECTORY_SEPARATOR . '*');
+        if (empty($files)) return;
+
+        $sourceFile = $files[0];
+        $destBase = base_path('docs/review/dummySurat');
+
+        // Ambil data km dari PortalDokumen untuk penentuan folder
+        $doc = \Modules\Gateway\Entities\PortalDokumen::where('ref_number', $refNumber)->first();
+        $km = $doc ? $doc->km : '';
+
+        $folderName = null;
+        if (str_contains($km, 'KP')) {
+            $folderName = 'ST';
+        } elseif (str_contains($km, 'PW') || str_contains($km, 'TU')) {
+            $folderName = 'Laporan';
+        }
+
+        if ($folderName) {
+            $destDir = $destBase . DIRECTORY_SEPARATOR . $folderName . DIRECTORY_SEPARATOR . $dokumenId;
+            if (!is_dir($destDir)) {
+                mkdir($destDir, 0755, true);
+            }
+
+            $fileName = basename($sourceFile);
+            copy($sourceFile, $destDir . DIRECTORY_SEPARATOR . $fileName);
+            Log::info("[WASRISK JOB] File disalin ke {$folderName}/{$dokumenId}/{$fileName} (KM: {$km})");
+        }
+    }
+}
