+<?php
+
+namespace App\Services\PengawasanPerizinanBerusaha;
+
+use Exception;
+use Illuminate\Support\Facades\Log;
+use Illuminate\Support\Facades\Cache;
+use App\Models\Penjadwalan\DokumenMetadata;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+
+class EkstrakDokumenService
+{
+    /**
+     * Memanggil script python untuk ekstraksi dokumen.
+     *
+     * @param string $pdfPath
+     * @return array
+     * @throws Exception
+     */
+    public function ekstrakViaPython(string $pdfPath): array
+    {
+        $pythonScript = base_path('scripts/PPBBR/extract_dokumen.py');
+        $command = escapeshellcmd("python \"$pythonScript\" \"$pdfPath\"");
+        $output = shell_exec($command);
+        
+        if (!$output) {
+            throw new Exception("Gagal mengeksekusi script ekstraksi dokumen.");
+        }
+        
+        $result = json_decode($output, true);
+        
+        if (isset($result['error'])) {
+            throw new Exception("Error Ekstraksi: " . $result['error']);
+        }
+        
+        return $result;
+    }
+
+    /**
+     * Simpan hasil parse ke Redis untuk dipakai frontend.
+     * 
+     * @param string $sessionId
+     * @param array $data
+     * @param int $ttl (dalam detik)
+     */
+    public function simpanKeCache(string $sessionId, array $data, int $ttl = 3600): void
+    {
+        // Cache facade otomatis menghandle CACHE_PREFIX sesuai octane/redis standards
+        Cache::store('redis')->put("ekstrak_dokumen:{$sessionId}", $data, $ttl);
+    }
+
+    /**
+     * Mengambil data dari cache.
+     * 
+     * @param string $sessionId
+     * @return array|null
+     */
+    public function ambilDariCache(string $sessionId): ?array
+    {
+        return Cache::store('redis')->get("ekstrak_dokumen:{$sessionId}");
+    }
+    
+    /**
+     * Hapus cache.
+     * 
+     * @param string $sessionId
+     */
+    public function hapusCache(string $sessionId): void
+    {
+        Cache::store('redis')->forget("ekstrak_dokumen:{$sessionId}");
+    }
+
+    /**
+     * Menyimpan hasil ekstraksi secara permanen (Upsert) ke ppbbr_dokumen_metadata.
+     * 
+     * @param array $items
+     * @param int|null $portalDokumenId
+     * @param string|null $filePath
+     */
+    public function simpanPermanen(array $items, ?int $portalDokumenId, ?string $filePath): void
+    {
+        foreach ($items as $item) {
+            DokumenMetadata::updateOrCreate(
+                [
+                    'portal_dokumen_id' => $portalDokumenId,
+                    'file_path' => $filePath,
+                    'nilai' => $item['nilai'],
+                ],
+                [
+                    'jenis_item' => $item['jenis_item'],
+                    'created_at' => now(),
+                    'updated_at' => now(),
+                ]
+            );
+        }
+    }
+    
+    /**
+     * Mencocokkan NKU/Nomor ST ke ObjekPengawasan.
+     * 
+     * @param array $items
+     * @return array
+     */
+    public function cocokkanKeObjek(array $items): array
+    {
+        $valid = [];
+        $invalid = [];
+        
+        foreach ($items as $item) {
+            $nilai = $item['nilai'];
+            $jenis = $item['jenis_item'];
+            
+            $objek = null;
+            
+            if ($jenis === 'nku') {
+                $objek = ObjekPengawasan::where('nku', $nilai)->first();
+            } else if ($jenis === 'nomor_st') {
+                // Relasi dokumenPenjadwalan
+                $objek = ObjekPengawasan::whereHas('dokumenPenjadwalan', function($q) use ($nilai) {
+                    $q->where('nomor_dokumen', $nilai)->where('jenis_dokumen', 'surat_tugas');
+                })->first();
+            }
+            
+            if ($objek) {
+                $item['is_valid'] = true;
+                $item['objek_pengawasan_id'] = $objek->id;
+                $item['nama_perusahaan'] = $objek->nama_perusahaan;
+                $valid[] = $item;
+            } else {
+                $item['is_valid'] = false;
+                $invalid[] = $item;
+            }
+        }
+        
+        return [
+            'valid' => $valid,
+            'invalid' => $invalid
+        ];
+    }
+}
