+    /**
+     * Pilih Dokumen dari CSRS
+     */
+    public function pilihDokumenCsrs($request, $id): JsonResponse
+    {
+        try {
+            $objekId = is_numeric($id) ? $id : $this->dekrip($id);
+            $objek = $this->objekPengawasan->with('unitKerja')->find($objekId);
+
+            if (!$objek) {
+                return $this->onError('Objek Pengawasan tidak ditemukan', 404);
+            }
+
+            $portalId = $objek->unitKerja->portal_id ?? null;
+
+            $query = \Modules\Gateway\Entities\PortalDokumen::query();
+
+            if ($portalId) {
+                $query->where('portal_id', $portalId);
+            }
+
+            if ($request->jenis_dokumen === 'surat_tugas') {
+                $query->where('ref_number', 'LIKE', '%SPDRUT%');
+            }
+
+            $dokumen = $query->orderBy('date', 'desc')
+                ->limit(20)
+                ->get()
+                ->map(function ($doc) {
+                    return [
+                        'dokumen_id' => $doc->id,
+                        'ref_number' => $doc->ref_number,
+                        'subject' => $doc->subject,
+                        'sender' => $doc->sender,
+                        'date' => $doc->date,
+                        'file_url' => $doc->dokumen ? url(str_replace($doc->dokumen_id, $this->enkrip($doc->dokumen_id), $doc->dokumen)) : null
+                    ];
+                });
+
+            return $this->onSuccess('Daftar dokumen pilih dari CSRS', $dokumen);
+        } catch (Exception $e) {
+            return $this->onError($e->getMessage());
+        }
+    }
