+    /**
+     * Pencarian Dokumen dari CSRS
+     */
+    public function pencarianDokumenCsrs($request): JsonResponse
+    {
+        try {
+            // Implementasi Session Limit Counter (Max 2x pencarian)
+            $userId = Auth::id() ?? session()->getId();
+            $limitKey = "ppbbr:search_attempt:{$userId}:" . session()->getId();
+            $count = \Illuminate\Support\Facades\Cache::store('redis')->get($limitKey, 0);
+
+            if ($count >= 2) {
+                return $this->onError('Batas maksimal pencarian CSRS (2x) telah tercapai untuk sesi ini.');
+            }
+
+            \Illuminate\Support\Facades\Cache::store('redis')->put($limitKey, $count + 1, 3600); // Reset tiap 1 jam
+
+            $keyword = $request->keyword;
+            $dokumen = \Modules\Gateway\Entities\PortalDokumen::where('ref_number', 'LIKE', "%{$keyword}%")
+                ->orWhere('subject', 'LIKE', "%{$keyword}%")
+                ->limit(20)
+                ->get()
+                ->map(function ($doc) {
+                    return [
+                        'dokumen_id' => $doc->id,
+                        'ref_number' => $doc->ref_number,
+                        'subject' => $doc->subject,
+                        'sender' => $doc->sender,
+                        'date' => $doc->date,
+                        'file_url' => $doc->dokumen ? url(str_replace($doc->dokumen_id, $this->enkrip($doc->dokumen_id), $doc->dokumen)) : null
+                    ];
+                });
+
+            return $this->onSuccess('Daftar dokumen CSRS', $dokumen);
+        } catch (Exception $e) {
+            return $this->onError($e->getMessage());
+        }
+    }
