+                    $allEkstrak = array_merge($cacheData['valid'] ?? [], $cacheData['invalid'] ?? []);
+                    $ekstrakService->simpanPermanen($allEkstrak, $portalDokumenId, $filePath);
+                    // Hapus cache
+                    $ekstrakService->hapusCache($request->session_id);
+                }
+            }
+
+            foreach ($objekIds as $idStr) {
+                $objekId = is_numeric($idStr) ? $idStr : $this->dekrip($idStr);
+                $objek = $this->objekPengawasan->find($objekId);
+
+                if (!$objek) continue;
+
+                // Validasi urutan upload perdana
+                $dokumenAda = \App\Models\Penjadwalan\DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
