+
+                if (!$dokumenAda) {
+                    $dokumenLain = \App\Models\Penjadwalan\DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+                        ->pluck('jenis_dokumen')->toArray();
+
+                    if (in_array($jenisDokumen, ['surat_pemberitahuan_oss', 'surat_pemberitahuan_upt'])) {
