+                    } else if ($jenisDokumen === 'stkl') {
+                        if (!in_array('notula', $dokumenLain)) {
+                            DB::rollBack();
+                            return $this->onError("Tidak dapat menyimpan STKL. Silakan unggah Notula terlebih dahulu untuk proyek {$objek->no_kode_proyek}.");
+                        }
+                        if (!in_array('surat_pemberitahuan_oss', $dokumenLain) && !in_array('surat_pemberitahuan_upt', $dokumenLain)) {
+                            DB::rollBack();
+                            return $this->onError("Tidak dapat menyimpan STKL. Silakan unggah SP terlebih dahulu untuk proyek {$objek->no_kode_proyek}.");
+                        }
+                    } else if ($jenisDokumen === 'surat_tugas') {
