+                            DB::rollBack();
+                            return $this->onError("Tidak dapat menyimpan Surat Tugas. Silakan unggah Notula terlebih dahulu untuk proyek {$objek->no_kode_proyek}.");
+                        }
+                        if (!in_array('surat_pemberitahuan_oss', $dokumenLain) && !in_array('surat_pemberitahuan_upt', $dokumenLain)) {
