+    public function dokumenExisting(string $id): JsonResponse
+    {
+        try {
+            $objekPengawasanId = $this->dekrip($id);
+            $objekPengawasan = $this->objekPengawasan->find($objekPengawasanId);
+            if (!$objekPengawasan) {
+                return $this->onError('Objek Pengawasan tidak ditemukan');
+            }
+
+            $dokumen = \App\Models\Penjadwalan\DokumenPenjadwalan::with('portalDokumen')
+                ->where('objek_pengawasan_id', $objekPengawasanId)
+                ->get();
+
+            $result = [
+                'notula' => null,
+                'surat_pemberitahuan_oss' => null,
+                'surat_pemberitahuan_upt' => null,
+                'stkl' => null,
+                'surat_tugas' => null
+            ];
+
+            foreach ($dokumen as $doc) {
+                $docUrl = null;
+                if ($doc->portal_dokumen_id && $doc->portalDokumen) {
+                    $portalDok = $doc->portalDokumen;
+                    $docUrl = $portalDok->dokumen ? url(str_replace($portalDok->dokumen_id, $this->enkrip($portalDok->dokumen_id), $portalDok->dokumen)) : null;
+                } else {
+                    $docUrl = \App\Services\FileService::getUrl($doc->file_path);
+                }
+
+                $result[$doc->jenis_dokumen] = [
+                    'id' => $this->enkrip($doc->id),
+                    'portal_dokumen_id' => $doc->portal_dokumen_id ? $this->enkrip($doc->portal_dokumen_id) : null,
+                    'file_path' => $doc->file_path,
+                    'file_url' => $docUrl,
+                    'nomor_surat' => $doc->manual_nomor_surat ?? ($doc->portalDokumen->ref_number ?? null),
+                    'tanggal_surat' => $doc->manual_tanggal_surat ?? ($doc->portalDokumen->tanggal ?? null),
+                    'is_manual' => $doc->portal_dokumen_id ? false : true,
+                ];
+            }
+
+            return $this->onSuccess('Berhasil memuat dokumen existing', $result);
+        } catch (Exception $e) {
+            return $this->onError($e->getMessage());
+        }
+    }
