+    public function pencarianDokumen($request): JsonResponse
+    {
+        try {
+            $objekPengawasanId = $this->dekrip($request->objek_pengawasan_id);
+            $jenisDokumen = $request->jenis_dokumen;
+            $mode = $request->mode ?? 'pilih';
+            $keyword = $request->keyword;
+
+            $objekPengawasan = $this->objekPengawasan->find($objekPengawasanId);
+            if (!$objekPengawasan) {
+                return $this->onError('Objek Pengawasan tidak ditemukan');
+            }
+
+            // Batasan Session untuk mode cari
+            if ($mode === 'cari') {
+                $userId = Auth::id() ?? 0;
+                $cacheKey = "ppbbr:cari_surat:{$userId}";
+                $currentCount = \Illuminate\Support\Facades\Cache::get($cacheKey, 0);
+
+                if ($currentCount >= 2) {
+                    return $this->onSuccess('Dokumen Tidak Ditemukan. Silahkan Unggah Manual Surat Disini.', [
+                        'is_manual' => true,
+                        'objek_pengawasan' => [
+                            'id' => $this->enkrip($objekPengawasan->id),
+                            'nib' => $objekPengawasan->nib,
+                            'nama_perusahaan' => $objekPengawasan->nama_perusahaan,
+                            'kbli' => $objekPengawasan->kbli,
+                            'nku' => $objekPengawasan->nku,
+                        ],
+                        'dokumen_aktif' => null,
+                        'daftar_dokumen_csrs' => [],
+                        'dokumen_tersimpan_relevan' => []
+                    ]);
+                }
+
+                // Increment counter with TTL until end of day or session
+                \Illuminate\Support\Facades\Cache::put($cacheKey, $currentCount + 1, now()->endOfDay());
+            }
+
+            // Default bypass untuk Notula, SP OSS, STKL
+            if (in_array($jenisDokumen, ['notula', 'surat_pemberitahuan_oss', 'stkl'])) {
+                return $this->onSuccess('Silahkan Unggah Manual', [
+                    'is_manual' => true,
+                    'objek_pengawasan' => [
+                        'id' => $this->enkrip($objekPengawasan->id),
+                        'nib' => $objekPengawasan->nib,
+                        'nama_perusahaan' => $objekPengawasan->nama_perusahaan,
+                        'kbli' => $objekPengawasan->kbli,
+                        'nku' => $objekPengawasan->nku,
+                    ],
+                    'dokumen_aktif' => null,
+                    'daftar_dokumen_csrs' => [],
+                    'dokumen_tersimpan_relevan' => []
+                ]);
+            }
+
+            // Logic untuk SP UPT dan Surat Tugas
+            $query = \Modules\Gateway\Entities\PortalDokumen::query();
+
+            $unitKerjaId = $objekPengawasan->unit_kerja;
+            $unitKerja = \App\Models\UnitKerja::find($unitKerjaId);
+
+            if ($jenisDokumen === 'surat_tugas' && $mode === 'pilih') {
+                $query->where('subject', 'LIKE', "%SDPRUT%");
+                if ($unitKerja && $unitKerja->kode_unit) {
+                    $query->where('ref_number', 'LIKE', "%/{$unitKerja->kode_unit}/%");
+                }
+            } else if ($jenisDokumen === 'surat_tugas' && $mode === 'cari') {
+                // tanpa filter SDPRUT
+                if ($keyword) {
+                    $query->where(function ($q) use ($keyword) {
+                        $q->where('ref_number', 'LIKE', "%{$keyword}%")
+                            ->orWhere('subject', 'LIKE', "%{$keyword}%");
+                    });
+                }
+            } else if ($jenisDokumen === 'surat_pemberitahuan_upt') {
+                if ($unitKerja && $unitKerja->kode_unit) {
+                    $query->where('ref_number', 'LIKE', "%/{$unitKerja->kode_unit}/%");
+                }
+                if ($mode === 'cari' && $keyword) {
+                    $query->where(function ($q) use ($keyword) {
+                        $q->where('ref_number', 'LIKE', "%{$keyword}%")
+                            ->orWhere('subject', 'LIKE', "%{$keyword}%");
+                    });
+                }
+            }
+
+            // Limit data lokal
+            $dokumenLokal = $query->orderBy('tanggal', 'desc')->limit(50)->get();
+
+            $isManual = false;
+            $korespondensiService = new \Modules\Gateway\Services\PORTAL\KorespondensiService();
+            $gatewayDown = $korespondensiService->isGatewayDown();
+
+            if ($dokumenLokal->isEmpty()) {
+                if ($gatewayDown) {
+                    $isManual = true;
+                } else {
+                    // Fallback to Gateway
+                    $type = null;
+                    $search = $keyword; // if any
+                    $idUnitKerja = $unitKerjaId; // Maybe we need portal mapping if different
+                    $responseGateway = $korespondensiService->daftarDokumenSurat($search, 1, 50, null, null, $type, $idUnitKerja);
+
+                    if (isset($responseGateway->status) && $responseGateway->status == 500) {
+                        $isManual = true;
+                    } else if (is_array($responseGateway) || (isset($responseGateway->data) && is_array($responseGateway->data))) {
+                        $dataGateway = is_array($responseGateway) ? $responseGateway : $responseGateway->data;
+                        if (empty($dataGateway)) {
+                            $isManual = true;
+                        } else {
+                            // Dispatch job to sync
+                            dispatch(new \Modules\Gateway\Jobs\Korespondensi\SimpanDataKorespondensiJob());
+                            // mapping data from gateway to standard format
+                            $dokumenLokal = collect($dataGateway)->map(function ($item) {
+                                return (object) [
+                                    'id' => $item->id ?? null,
+                                    'portal_dokumen_id' => $item->id ?? null,
+                                    'subject' => $item->perihal ?? $item->subject ?? null,
+                                    'ref_number' => $item->nomor_surat ?? $item->ref_number ?? null,
+                                    'sender' => $item->pengirim ?? $item->sender ?? null,
+                                    'tanggal' => $item->tanggal_surat ?? $item->tanggal ?? null,
+                                    'dokumen' => $item->dokumen ?? null
+                                ];
+                            });
+                        }
+                    } else {
+                        $isManual = true;
+                    }
+                }
+            }
+
+            // Active document calculation
+            $dokumenAktif = null;
+            $activeDocRecord = \App\Models\Penjadwalan\DokumenPenjadwalan::where('objek_pengawasan_id', $objekPengawasanId)
+                ->where('jenis_dokumen', $jenisDokumen)
+                ->first();
+
+            if ($activeDocRecord) {
+                $dokumenAktif = [
+                    'portal_dokumen_id' => $activeDocRecord->portal_dokumen_id ? $this->enkrip($activeDocRecord->portal_dokumen_id) : null,
+                    'file_path' => $activeDocRecord->file_path,
+                    'nomor_surat' => $activeDocRecord->manual_nomor_surat,
+                    'tanggal_surat' => $activeDocRecord->manual_tanggal_surat,
+                    'is_manual' => $activeDocRecord->portal_dokumen_id ? false : true,
+                ];
+            }
+
+            // Format output list
+            $daftarDokumenCsrs = [];
+            if (!$isManual && !$dokumenLokal->isEmpty()) {
+                foreach ($dokumenLokal as $doc) {
+                    $isSelected = ($activeDocRecord && $activeDocRecord->portal_dokumen_id == $doc->id);
+                    $daftarDokumenCsrs[] = [
+                        'id' => $doc->id,
+                        'portal_dokumen_id' => $doc->id,
+                        'perihal' => $doc->subject,
+                        'nomor_surat' => $doc->ref_number,
+                        'pengirim' => $doc->sender,
+                        'tanggal_surat' => $doc->tanggal ? Carbon::parse($doc->tanggal)->format('d-F-Y') : null,
+                        'is_selected' => $isSelected,
+                        'dokumen' => $doc->dokumen ?? null,
+                    ];
+                }
+            }
+
+            // Relevan Documents (Auto-Suggest) from ppbbr_dokumen_metadata
+            $dokumenRelevan = [];
+            $nkuString = $objekPengawasan->nku; // It might be array or JSON or comma-separated string depending on DB setup
+
+            // Assume it can be array if casted, or string if not
+            $nkuList = [];
+            if (is_array($nkuString)) {
+                $nkuList = $nkuString;
+            } elseif (is_string($nkuString) && !empty($nkuString)) {
+                // If it's a JSON array string
+                $decoded = json_decode($nkuString, true);
+                if (is_array($decoded)) {
+                    $nkuList = $decoded;
+                } else {
+                    $nkuList = explode(',', $nkuString);
+                }
+            }
+
+            if (!empty($nkuList)) {
+                $relevanMetadata = \App\Models\Penjadwalan\DokumenMetadata::whereIn('nilai', $nkuList)
+                    ->where('jenis_dokumen', $jenisDokumen)
+                    ->whereNull('objek_pengawasan_id')
+                    ->get();
+
+                foreach ($relevanMetadata as $meta) {
+                    $dokumenRelevan[] = [
+                        'portal_dokumen_id' => $meta->portal_dokumen_id ? $this->enkrip($meta->portal_dokumen_id) : null,
+                        'file_path' => $meta->file_path,
+                        'nku' => $meta->nilai
+                    ];
+                }
+            }
+
+            return $this->onSuccess('Berhasil memuat pencarian dokumen', [
+                'is_manual' => empty($daftarDokumenCsrs) && $mode === 'cari' ? true : $isManual,
+                'objek_pengawasan' => [
+                    'id' => $this->enkrip($objekPengawasan->id),
+                    'nib' => $objekPengawasan->nib,
+                    'nama_perusahaan' => $objekPengawasan->nama_perusahaan,
+                    'kbli' => $objekPengawasan->kbli,
+                    'nku' => $objekPengawasan->nku,
+                ],
+                'dokumen_aktif' => $dokumenAktif,
+                'daftar_dokumen_csrs' => $daftarDokumenCsrs,
+                'dokumen_tersimpan_relevan' => $dokumenRelevan
+            ]);
+        } catch (Exception $e) {
+            return $this->onError($e->getMessage());
+        }
+    }
 }
