--- /dev/null
+++ b/docs/review/dummySurat/read_nku.py
@@ -0,0 +1,138 @@
+import os
+import re
+from rapidocr_onnxruntime import RapidOCR
+import pypdfium2 as pdfium
+import sys
+import time
+import csv
+
+# Inisialisasi OCR
+ocr = RapidOCR()
+
+# Regex untuk NKU: gunakan word boundary (\b) agar tidak menyambung dengan nomor lain (seperti NIB)
+# Kita izinkan adanya spasi atau enter di antara blok angka.
+nku_pattern = re.compile(r'\b\d{6}\s*-?\s*\d{4}\s*-?\s*\d{4}\s*-?\s*\d{4}\s*-?\s*\d{3}\b')
+
+def format_nku(nku_str):
+    """Memastikan NKU memiliki format standar XXXXXX-XXXX-XXXX-XXXX-XXX"""
+    # Hapus semua karakter selain angka (menghapus spasi, strip, enter)
+    clean = re.sub(r'\D', '', nku_str)
+    if len(clean) == 21:
+        return f"{clean[0:6]}-{clean[6:10]}-{clean[10:14]}-{clean[14:18]}-{clean[18:21]}"
+    return nku_str
+
+def extract_nku_from_pdf(pdf_path):
+    nku_found = set()
+    
+    try:
+        # Buka PDF menggunakan pypdfium2
+        pdf = pdfium.PdfDocument(pdf_path)
+        
+        # Ekstrak per halaman
+        for page_index in range(len(pdf)):
+            page = pdf[page_index]
+            
+            # 1. COBA BACA TEKS NATIVE TERLEBIH DAHULU (SANGAT CEPAT 0.01 detik)
+            textpage = page.get_textpage()
+            native_text = textpage.get_text_bounded()
+            
+            # Ekstrak dari teks native jika ada
