+                continue
+                
+            # 2. JIKA NATIVE TEXT KOSONG (Berarti dokumen hasil scan gambar), BARU JALANKAN OCR
+            bitmap = page.render(scale=2)
+            image_np = bitmap.to_numpy()
+            result, _ = ocr(image_np)
+            
+            if result:
+                page_text = " ".join([box[1] for box in result])
+                matches = nku_pattern.findall(page_text)
+                for match in matches:
+                    nku_found.add(format_nku(match))
+                    
+    except Exception as e:
+        pass
+        
+    return list(nku_found)
+
+if __name__ == "__main__":
