+        writer = csv.writer(f)
+        writer.writerow(["dokumen_id", "file_name", "nku"])
+        
+        # JIKA ADA PARAMETER (1 FILE SAJA)
+        if len(sys.argv) > 1:
+            pdf_path = sys.argv[1]
