+import os
+import re
+from rapidocr_onnxruntime import RapidOCR
+import pypdfium2 as pdfium
+import sys
+
+# Inisialisasi OCR
+ocr = RapidOCR()
+
+# Regex untuk Nomor Surat Tugas: Dibuat tangguh dengan \s* dan /? untuk mengantisipasi typo (hilang garis miring)
+st_pattern = re.compile(r'(?:B\.)?\s*\d+\s*/?\s*[A-Za-z0-9.-]+\s*/\s*[A-Za-z0-9.-]+\s*/\s*[IVX]+\s*/\s*\d{4}', re.IGNORECASE)
+
+def format_st(st_str):
+    """Menstandarisasi format ST (Huruf besar semua, kecuali singkatan khusus PSDKPLan / PSDKPSta)"""
+    # 1. Hapus semua spasi & enter
+    clean = re.sub(r'\s+', '', st_str)
+    
+    # 2. Uppercase (mengubah b. jadi B., kp.440 jadi KP.440, viii jadi VIII)
+    clean = clean.upper()
+    
+    # 3. AUTO-FIX TYPO: Jika tidak ada garis miring antara Angka dan PSDKP (Contoh: B.1487PSDKP...), sisipkan garis miring
+    clean = re.sub(r'(\d)(PSDKP)', r'\1/\2', clean)
+    
+    # 4. Kembalikan casing khusus standar PSDKP
+    clean = clean.replace('PSDKPLAN', 'PSDKPLan')
+    clean = clean.replace('PSDKPSTA', 'PSDKPSta')
+    
+    return clean
+
+def extract_st_from_pdf(pdf_path):
+    st_found = set()
+    
+    try:
+        # Buka PDF menggunakan pypdfium2
+        pdf = pdfium.PdfDocument(pdf_path)
+        
+        # Ekstrak per halaman (Biasanya Nomor ST ada di Halaman 1 atau 2)
+        max_pages = min(3, len(pdf))
+        for page_index in range(max_pages):
+            page = pdf[page_index]
+            
+            # 1. COBA BACA TEKS NATIVE TERLEBIH DAHULU
+            textpage = page.get_textpage()
+            native_text = textpage.get_text_bounded()
+            
+            # Ekstrak langsung dari teks asli (tidak perlu merusak spasi seluruh dokumen)
+            matches = st_pattern.findall(native_text)
+            if matches:
+                for match in matches:
+                    clean_match = format_st(match)
+                    if re.search(r'KP\.?440', clean_match, re.IGNORECASE):
+                        st_found.add(clean_match)
+            
+            # CEK APAKAH PERLU OCR?
+            if len(native_text.strip()) > 50:
+                continue
+                
+            # 2. JIKA NATIVE TEXT KOSONG, BARU JALANKAN OCR
+            bitmap = page.render(scale=2)
+            image_np = bitmap.to_numpy()
+            result, _ = ocr(image_np)
+            
+            if result:
+                # Gabung OCR dengan spasi natural
+                page_text = " ".join([box[1] for box in result])
+                
+                matches = st_pattern.findall(page_text)
+                for match in matches:
+                    clean_match = format_st(match)
+                    if re.search(r'KP\.?440', clean_match, re.IGNORECASE):
+                        st_found.add(clean_match)
+                    
+    except Exception as e:
+        pass
+        
+    return list(st_found)
+
+if __name__ == "__main__":
+    import sys
+    import csv
+    import time
+    
+    # Siapkan folder output
+    output_dir = os.path.join(os.path.dirname(__file__), "output")
+    if not os.path.exists(output_dir):
+        os.makedirs(output_dir)
+        
+    output_file = os.path.join(output_dir, "hasil_st.csv")
+    
+    total_start_time = time.time()
+    
+    # Buka file CSV untuk menulis
+    with open(output_file, mode='w', newline='', encoding='utf-8') as f:
+        writer = csv.writer(f)
+        writer.writerow(["dokumen_id", "file_name", "st_number"])
+        
+        # JIKA ADA PARAMETER (1 FILE SAJA)
+        if len(sys.argv) > 1:
+            pdf_path = sys.argv[1]
+            file_name = os.path.basename(pdf_path)
+            parent_dir = os.path.basename(os.path.dirname(os.path.abspath(pdf_path)))
+            dokumen_id = parent_dir if parent_dir.isdigit() else ""
+            
+            t0 = time.time()
+            if not os.path.exists(pdf_path) or not pdf_path.lower().endswith('.pdf'):
+                writer.writerow([dokumen_id, file_name, "INVALID_FILE"])
+                elapsed = time.time() - t0
+                print(f"[{elapsed:.3f}s] {file_name} -> INVALID_FILE")
+            else:
+                sts = extract_st_from_pdf(pdf_path)
+                elapsed = time.time() - t0
+                
+                if sts:
+                    writer.writerow([dokumen_id, file_name, ", ".join(sts)])
+                    print(f"[{elapsed:.3f}s] {file_name} -> FOUND {len(sts)} ST")
+                else:
+                    writer.writerow([dokumen_id, file_name, ""])
+                    print(f"[{elapsed:.3f}s] {file_name} -> NOT_FOUND")
+                    
+        # JIKA TANPA PARAMETER (SEMUA FILE DI FOLDER Laporan)
+        else:
+            laporan_dir = os.path.join(os.path.dirname(__file__), "Laporan")
+            if os.path.exists(laporan_dir):
+                for root, dirs, files in os.walk(laporan_dir):
+                    for file in files:
+                        if file.lower().endswith('.pdf'):
+                            pdf_path = os.path.join(root, file)
+                            
+                            parent_dir = os.path.basename(root)
+                            dokumen_id = parent_dir if parent_dir.isdigit() else ""
+                            
+                            t0 = time.time()
+                            sts = extract_st_from_pdf(pdf_path)
+                            elapsed = time.time() - t0
+                            
+                            if sts:
+                                writer.writerow([dokumen_id, file, ", ".join(sts)])
+                                print(f"[{elapsed:.3f}s] [{dokumen_id}] {file} -> FOUND {len(sts)} ST")
+                            else:
+                                writer.writerow([dokumen_id, file, ""])
+                                print(f"[{elapsed:.3f}s] [{dokumen_id}] {file} -> NOT_FOUND")
+            else:
+                print("Folder Laporan tidak ditemukan!")
+                
+    total_elapsed = time.time() - total_start_time
+    print(f"\n=========================================")
+    print(f"Selesai! Hasil Nomor ST telah disimpan ke: {output_file}")
+    print(f"Total Waktu Eksekusi: {total_elapsed:.3f} detik")
+    print(f"=========================================")
