diff --git a/scripts/PPBBR/extract_dokumen.py b/scripts/PPBBR/extract_dokumen.py
new file mode 100644
index 0000000000..1e4d63511f
--- /dev/null
+++ b/scripts/PPBBR/extract_dokumen.py
@@ -0,0 +1,117 @@
+import os
+import re
+import sys
+import json
+import logging
+from rapidocr_onnxruntime import RapidOCR
+import pypdfium2 as pdfium
+
+# Suppress warnings
+logging.getLogger('pdfminer').setLevel(logging.ERROR)
+
+# Initialize OCR
+try:
+    ocr = RapidOCR()
+except Exception:
+    ocr = None
+
+# Regex Patterns
+nku_pattern = re.compile(r'\b\d{6}\s*-?\s*\d{4}\s*-?\s*\d{4}\s*-?\s*\d{4}\s*-?\s*\d{3}\b')
+st_pattern = re.compile(r'(?:B\.)?\s*\d+\s*/?\s*[A-Za-z0-9.-]+\s*/\s*[A-Za-z0-9.-]+\s*/\s*[IVX]+\s*/\s*\d{4}', re.IGNORECASE)
+
+def format_nku(nku_str):
+    clean = re.sub(r'\D', '', nku_str)
+    if len(clean) == 21:
+        return f"{clean[0:6]}-{clean[6:10]}-{clean[10:14]}-{clean[14:18]}-{clean[18:21]}"
+    return nku_str
+
+def format_st(st_str):
+    clean = re.sub(r'\s+', '', st_str)
+    clean = clean.upper()
+    clean = re.sub(r'(\d)(PSDKP)', r'\1/\2', clean)
+    clean = clean.replace('PSDKPLAN', 'PSDKPLan')
+    clean = clean.replace('PSDKPSTA', 'PSDKPSta')
+    return clean
+
+def extract_data(pdf_path):
+    nku_found = set()
+    st_found = set()
+    
+    try:
+        pdf = pdfium.PdfDocument(pdf_path)
+        
+        # Extract max 3 pages (usually info is on first few pages)
+        max_pages = min(3, len(pdf))
+        for page_index in range(max_pages):
+            page = pdf[page_index]
+            
+            # 1. Native Text Extraction
+            textpage = page.get_textpage()
+            native_text = textpage.get_text_bounded()
+            
+            # Find NKU
+            matches_nku = nku_pattern.findall(native_text)
+            for match in matches_nku:
+                nku_found.add(format_nku(match))
+                
+            # Find ST
+            matches_st = st_pattern.findall(native_text)
+            for match in matches_st:
+                clean_match = format_st(match)
+                if re.search(r'KP\.?440', clean_match, re.IGNORECASE):
+                    st_found.add(clean_match)
+                    
+            if len(native_text.strip()) > 50:
+                continue
+                
+            # 2. OCR Fallback for scanned PDFs
+            if ocr:
+                bitmap = page.render(scale=2)
+                image_np = bitmap.to_numpy()
+                result, _ = ocr(image_np)
+                
+                if result:
+                    page_text = " ".join([box[1] for box in result])
+                    
+                    # Find NKU
+                    matches_nku = nku_pattern.findall(page_text)
+                    for match in matches_nku:
+                        nku_found.add(format_nku(match))
+                        
+                    # Find ST
+                    matches_st = st_pattern.findall(page_text)
+                    for match in matches_st:
+                        clean_match = format_st(match)
+                        if re.search(r'KP\.?440', clean_match, re.IGNORECASE):
+                            st_found.add(clean_match)
+                            
+    except Exception as e:
+        pass
+        
+    results = []
+    for nku in nku_found:
+        results.append({
+            "jenis_item": "nku",
+            "nilai": nku
+        })
+        
+    for st in st_found:
+        results.append({
+            "jenis_item": "nomor_st",
+            "nilai": st
+        })
+        
+    return results
+
+if __name__ == "__main__":
+    if len(sys.argv) < 2:
+        print(json.dumps({"error": "Usage: python extract_dokumen.py <path_to_pdf>"}))
+        sys.exit(1)
+
+    pdf_file = sys.argv[1]
+    if not os.path.exists(pdf_file):
+        print(json.dumps({"error": f"File not found: {pdf_file}"}))
+        sys.exit(1)
+        
+    data = extract_data(pdf_file)
+    print(json.dumps(data, indent=4, ensure_ascii=False))

