diff --git a/app/Docs/ScrambleResponseExampleExtension.php b/app/Docs/ScrambleResponseExampleExtension.php
new file mode 100644
index 0000000000..7171534947
--- /dev/null
+++ b/app/Docs/ScrambleResponseExampleExtension.php
@@ -0,0 +1,58 @@
+<?php
+
+namespace App\Docs;
+
+use Dedoc\Scramble\Extensions\OperationExtension;
+use Dedoc\Scramble\Support\Generator\Operation;
+use Dedoc\Scramble\Support\Generator\Reference;
+use Dedoc\Scramble\Support\Generator\Response;
+use Dedoc\Scramble\Support\Generator\Types\Type;
+use Dedoc\Scramble\Support\RouteInfo;
+
+class ScrambleResponseExampleExtension extends OperationExtension
+{
+    /**
+     * Menyisipkan `examples` eksplisit pada response (200) yang memakai stub
+     * `@response`. Tujuannya agar UI Scalar menampilkan contoh JSON lengkap apa
+     * adanya, alih-alih meng-generate dari schema array bertipe tuple
+     * (`prefixItems`) yang sering tampil kosong / tidak lengkap.
+     */
+    public function handle(Operation $operation, RouteInfo $routeInfo): void
+    {
+        $docComment = $routeInfo->reflectionAction()?->getDocComment() ?: '';
+
+        if (! preg_match('/@response\s+\\\\?([A-Za-z0-9_\\\\]+)/', $docComment, $matches)) {
+            return;
+        }
+
+        $class = ltrim($matches[1], '\\');
+
+        if (! class_exists($class) || ! method_exists($class, 'toArray')) {
+            return;
+        }
+
+        try {
+            $example = (new $class([]))->toArray(request());
+        } catch (\Throwable) {
+            return;
+        }
+
+        foreach ($operation->responses as $response) {
+            if (! $response instanceof Response || (int) $response->code !== 200) {
+                continue;
+            }
+
+            foreach ($response->content as $schema) {
+                $type = $schema instanceof Reference ? $schema : ($schema->type ?? null);
+
+                if ($type instanceof Reference) {
+                    $type = $type->resolve()->type;
+                }
+
+                if ($type instanceof Type) {
+                    $type->examples([$example]);
+                }
+            }
+        }
+    }
+}
