@@ -0,0 +1,36 @@
+<?php
+
+namespace App\Docs;
+
+use Dedoc\Scramble\Extensions\OperationExtension;
+use Dedoc\Scramble\Support\Generator\Operation;
+use Dedoc\Scramble\Support\RouteInfo;
+
+class ScrambleTagsOverrideExtension extends OperationExtension
+{
+    /**
+     * Menjadikan anotasi `@tags` pada Controller sebagai penentu tunggal tag
+     * endpoint. Tanpa ini, Scramble menggabungkan `@tags` dengan nama Controller
+     * (mis. `Dashboard`) sehingga endpoint SDK ikut muncul di grup modul asal.
+     */
+    public function handle(Operation $operation, RouteInfo $routeInfo): void
+    {
+        $className = $routeInfo->className();
+
+        if (! $className || ! class_exists($className)) {
+            return;
+        }
+
+        $docComment = (new \ReflectionClass($className))->getDocComment() ?: '';
+
+        if (! preg_match('/@tags\s+([^\r\n*]+)/', $docComment, $matches)) {
+            return;
+        }
+
+        $tags = array_values(array_filter(array_map('trim', explode(',', $matches[1]))));
+
+        if (! empty($tags)) {
+            $operation->setTags($tags);
+        }
+    }
+}
