+    private function resetJawabanDanHasil(ObjekPengawasan $objek): array
+    {
+        $jumlahJawaban = JawabanKepatuhanTeknis::where('objek_pengawasan_id', $objek->id)->delete();
+        $jumlahHasil = HasilKepatuhanTeknis::where('objek_pengawasan_id', $objek->id)->delete();
+        $jumlahPbumku = JawabanPBUMKU::where('objek_pengawasan_id', $objek->id)->delete();
+        $jumlahSelfDeclare = JawabanSelfDeclare::where('objek_pengawasan_id', $objek->id)->delete();
+
+        // Reset nilai kepatuhan pada objek agar tidak menyisakan skor lama
+        $objek->nilai_kepatuhan = null;
+        $objek->keterangan_kepatuhan = null;
+        $objek->save();
+
+        return [
+            'jawaban' => $jumlahJawaban,
+            'hasil' => $jumlahHasil,
+            'pbumku' => $jumlahPbumku,
+            'self_declare' => $jumlahSelfDeclare,
+        ];
+    }
 }
