+<?php
+
+namespace Tests\Feature\PengawasanPerizinanBerusaha;
+
+use App\Http\Library\EnkripsiHelper;
+use App\Models\PegawaiInternal;
+use App\Models\PengawasanPerizinanBerusaha\InspeksiLapangan\JawabanKepatuhanTeknis;
+use App\Models\PengawasanPerizinanBerusaha\InspeksiLapangan\PertanyaanKepatuhanTeknis;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\UnitKerja;
+use App\Models\User;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use PHPOpenSourceSaver\JWTAuth\Facades\JWTAuth;
+use Spatie\Permission\Models\Role;
+use Tests\TestCase;
+
+class PertanyaanKepatuhanTeknisTest extends TestCase
+{
+    use DatabaseTransactions, EnkripsiHelper;
+
+    protected $pengawas;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+
+        // Ensure role exists (it might already exist from seeder, so firstOrCreate)
+        Role::firstOrCreate(['name' => 'Pengawas Perikanan JF', 'guard_name' => 'api']);
+
+        // Create pengawas
+        $this->pengawas = User::factory()->create(['pegint_id' => 'PGW001']);
+        $this->pengawas->assignRole('Pengawas Perikanan JF');
+        UnitKerja::factory()->create(['kode_unit' => 'UK001']);
+        PegawaiInternal::factory()->create(['nip' => 'PGW001', 'unit_kerja_id' => 'UK001']);
+    }
+
+    /**
+     * @test
+     */
+    public function skenario_parent_ya_child_wajib_dijawab()
+    {
+        $objek = ObjekPengawasan::factory()->create([
+            'kbli' => '03111',
+            'skala_usaha_proyek' => 'Kecil',
+            'status' => ObjekPengawasan::Inspeksi,
+        ]);
+
+        $objek->pengawas()->create(['nip' => $this->pengawas->pegint_id]);
+
+        $token = JWTAuth::fromUser($this->pengawas);
+
+        // Find a parent with logic_action = 'auto_yes_on_no'
+        $parentPertanyaan = PertanyaanKepatuhanTeknis::where('kbli', '03111')
+            ->where('logic_action', 'auto_yes_on_no')
+            ->where('skala_kecil', true)
+            ->first();
+
+        $this->assertNotNull($parentPertanyaan, 'Parent auto_yes_on_no untuk KBLI 03111 tidak ditemukan.');
+
+        $childPertanyaan = PertanyaanKepatuhanTeknis::where('parent_id', $parentPertanyaan->id)->first();
+        $this->assertNotNull($childPertanyaan, 'Child dari parent tersebut tidak ditemukan.');
+
+        // Jika parent dijawab Ya (true), maka child WAJIB dijawab (harus disertakan).
+        // Mari kita kirim parent = true, TAPI child TIDAK disertakan.
+        $payload = [
+            'jenis_usaha' => ['Kapal Penangkap Ikan dengan berat 6 GT s/d 30 GT'],
+            'jawaban' => [
+                [
+                    'id' => $parentPertanyaan->id,
+                    'jawaban' => '1',
+                ],
+            ],
+        ];
+
+        $objekIdEnkrip = $this->enkrip($objek->id);
+        $response = $this->withHeader('Authorization', "Bearer $token")
+            ->postJson("/api/v1/ppbbr/inspeksi/pertanyaan/{$objekIdEnkrip}/kepatuhan-teknis", $payload);
+
+        // Sebenarnya Service tidak memvalidasi leaf kalau tidak dikirim via FormRequest JIKA
+        // FormRequest JawabInspeksiLapanganRequest mewajibkannya?
+        // Mari kita pastikan API tidak error internal.
+        $response->assertStatus(200);
+
