+<?php
+
+namespace App\Console\Commands\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use App\Http\Library\ApiHelpers;
+use App\Jobs\ProcessSendWaLaporanSinkronisasi;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Services\PengawasanPerizinanBerusaha\LaporanHasilPengawasanService;
+use Carbon\Carbon;
+use Illuminate\Console\Command;
+
+class NotifikasiSinkronisasiLaporanCommand extends Command
+{
+    use ApiHelpers;
+
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'ppbbr:notifikasi-sinkronisasi-laporan';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Kirim reminder WA sinkronisasi Laporan Hasil Pengawasan yang jatuh tempo hari ini.';
+
+    /**
+     * Execute the console command.
+     */
+    public function handle(): int
+    {
+        $service = new LaporanHasilPengawasanService();
+        $today = now()->toDateString();
+        $serverCode = $this->generateServerCode();
+
+        $objeks = ObjekPengawasan::where('status', ObjekPengawasan::Selesai)
+            ->whereDoesntHave('laporanHasilPengawasan')
+            ->get();
+
+        $terkirim = 0;
+        foreach ($objeks as $objek) {
+            $deadline = $service->hitungDeadline($objek->id);
+            if ($deadline !== $today) {
+                continue;
+            }
+
+            dispatch(new ProcessSendWaLaporanSinkronisasi($objek, Carbon::parse($deadline)->format('d-m-Y'), $serverCode));
+            $terkirim++;
+        }
+
+        $this->info("Notifikasi sinkronisasi laporan dikirim: {$terkirim}");
+
+        return Command::SUCCESS;
+    }
+}
