@@ -0,0 +1,121 @@
+<?php
+
+namespace App\Console\Commands\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use App\Http\Library\EnkripsiHelper;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use Barryvdh\Snappy\Facades\SnappyPdf;
+use Illuminate\Console\Command;
+use Modules\Gateway\Entities\PortalDokumen;
+
+class UatGenerateLaporanCommand extends Command
+{
+    use EnkripsiHelper;
+
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'ppbbr:uat-generate-laporan {objek_pengawasan_id}';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Generate file PDF Laporan (Nota Dinas) Dummy (UAT) dan inject ke Portal Dokumen berdasarkan ID Objek Pengawasan.';
+
+    /**
+     * Execute the console command.
+     */
+    public function handle(): int
+    {
+        $id = $this->argument('objek_pengawasan_id');
+
+        $this->info("Sedang mencari Objek Pengawasan ID: {$id}...");
+
+        $objek = ObjekPengawasan::with('unitKerja')->find($id);
+
+        if (!$objek) {
+            $this->error("Objek Pengawasan dengan ID {$id} tidak ditemukan!");
+            return Command::FAILURE;
+        }
+
+        // Ambil Nomor ST objek (sumber target ekstraksi laporan)
+        $st = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+            ->where('jenis_dokumen', 'surat_tugas')
+            ->with('portalDokumen')
+            ->first();
+
+        $nomorSt = $st ? ($st->manual_nomor_surat ?: optional($st->portalDokumen)->ref_number) : null;
+
+        if (empty($nomorSt)) {
+            $this->error("Objek Pengawasan ID {$id} belum memiliki Surat Tugas (Nomor ST).");
+            $this->line("Jalankan dulu: php artisan ppbbr:uat-prepare-penjadwalan {$id}  (atau ppbbr:uat-generate-st {$id})");
+            return Command::FAILURE;
+        }
+
+        $this->info("Ditemukan! Perusahaan: {$objek->nama_perusahaan} | Nomor ST: {$nomorSt}");
+        $this->info("Sedang menggenerate PDF Laporan (Nota Dinas)...");
+
+        $pdf = SnappyPdf::loadView('ppbbr.uat.laporan', compact('objek', 'nomorSt'));
+
+        $filename = 'laporan_uat_' . $id . '_' . time() . '.pdf';
+
+        // Nomor surat Laporan (KM: PW 110 / PW 120 / PW 130 / PW 240)
+        $romans = ['01' => 'I', '02' => 'II', '03' => 'III', '04' => 'IV', '05' => 'V', '06' => 'VI', '07' => 'VII', '08' => 'VIII', '09' => 'IX', '10' => 'X', '11' => 'XI', '12' => 'XII'];
+        $romanMonth = $romans[date('m')];
+        $kmBase = 'PW 110';                                   // KM spasi untuk filter LIKE
+        $kmForSurat = str_replace(' ', '.', $kmBase);          // KM titik pada nomor surat
+
+        $kodeSurat = $objek->unitKerja ? $objek->unitKerja->kode_surat : 'PSDKPSta.1';
+        $nomorSurat = "B.{$id}/{$kodeSurat}/{$kmForSurat}/{$romanMonth}/" . date('Y');
+
+        $dokumenId = (int) (time() . rand(100, 999));
+        $encryptedId = $this->enkrip($dokumenId);
+
+        $publicPath = 'bucket/s3_default/file/korespondensi/' . $encryptedId;
+        $fullPath = public_path($publicPath);
+
+        if (!is_dir($fullPath)) {
+            mkdir($fullPath, 0755, true);
+        }
+
+        $filePath = $fullPath . DIRECTORY_SEPARATOR . $filename;
+        file_put_contents($filePath, $pdf->output());
+
+        $this->info("File PDF Laporan berhasil dibuat!");
+        $this->info("Mendaftarkan ke tabel portal_dokumen (Database Lokal)...");
+
+        $randomKm = $kmBase . '.' . rand(1, 9);
+
+        $portalDokumen = PortalDokumen::updateOrCreate(
+            ['ref_number' => $nomorSurat],
+            [
+                'dokumen_id' => $dokumenId,
+                'km' => $randomKm,
+                'subject' => 'SPDRUT_UAT - Laporan Hasil Pengawasan ' . $objek->nama_perusahaan,
+                'type' => 'Surat Keluar',
+                'category' => 'Laporan Hasil Pengawasan',
+                'sender' => 'KEPALA UPT (UAT)',
+                'dokumen' => '/api/v1/korespondensi/file/' . $dokumenId,
+                'status' => true,
+                'letter_date' => date('Y-m-d'),
+                'date' => date('Y-m-d'),
+                'time' => date('H:i:s'),
+            ]
+        );
+
+        $this->info("=========================================");
+        $this->info("Laporan Hasil Pengawasan UAT Siap Digunakan!");
+        $this->info("Nomor Laporan Dummy (Gunakan untuk Pencarian): " . $nomorSurat);
+        $this->info("Nomor ST (target ekstraksi): " . $nomorSt);
+        $this->info("Path Fisik: " . $fullPath);
+        $this->info("URL CSRS Mock: " . url($portalDokumen->dokumen));
+        $this->info("=========================================");
+
+        return Command::SUCCESS;
+    }
+}
