@@ -0,0 +1,150 @@
+<?php
+
+namespace App\Console\Commands\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use App\Http\Library\EnkripsiHelper;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenMetadata;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use App\Services\FileService;
+use Barryvdh\Snappy\Facades\SnappyPdf;
+use Illuminate\Console\Command;
+use Modules\Gateway\Entities\PortalDokumen;
+
+class UatPreparePenjadwalanCommand extends Command
+{
+    use EnkripsiHelper;
+
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'ppbbr:uat-prepare-penjadwalan {objek_pengawasan_id} {--reset : Hapus dulu dokumen penjadwalan & metadata lama}';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Menyiapkan Objek Pengawasan agar siap uji Laporan: isi otomatis 4 dokumen penjadwalan (Notula, SP, STKL, ST) + PDF + relasi NKU valid hingga status Menunggu Inspeksi.';
+
+    /**
+     * Execute the console command.
+     */
+    public function handle(): int
+    {
+        $id = $this->argument('objek_pengawasan_id');
+
+        $objek = ObjekPengawasan::with('unitKerja')->find($id);
+
+        if (!$objek) {
+            $this->error("Objek Pengawasan dengan ID {$id} tidak ditemukan!");
+            return Command::FAILURE;
+        }
+
+        if (empty($objek->no_kode_proyek)) {
+            $this->error("Objek Pengawasan ID {$id} tidak memiliki NKU (no_kode_proyek)!");
+            return Command::FAILURE;
+        }
+
+        $this->info("Menyiapkan Objek {$objek->id} - {$objek->nama_perusahaan} | NKU: {$objek->no_kode_proyek}");
+
+        if ($this->option('reset')) {
+            $this->info("Reset dokumen penjadwalan & metadata lama...");
+            foreach (DokumenPenjadwalan::withTrashed()->where('objek_pengawasan_id', $objek->id)->get() as $dok) {
+                if ($dok->file_path) {
+                    FileService::deleteOnStorage($dok->file_path);
+                }
+            }
+            DokumenPenjadwalan::withTrashed()->where('objek_pengawasan_id', $objek->id)->forceDelete();
+            DokumenMetadata::where('objek_pengawasan_id', $objek->id)->delete();
+        }
+
+        $romans = ['01' => 'I', '02' => 'II', '03' => 'III', '04' => 'IV', '05' => 'V', '06' => 'VI', '07' => 'VII', '08' => 'VIII', '09' => 'IX', '10' => 'X', '11' => 'XI', '12' => 'XII'];
+        $romanMonth = $romans[date('m')];
+        $kodeSurat = $objek->unitKerja ? $objek->unitKerja->kode_surat : 'PSDKPSta.1';
+        $nkuList = [$objek->no_kode_proyek];
+
+        // 1. NOTULA (manual)
+        $notulaNomor = "B.{$objek->id}/{$kodeSurat}/KP.440/{$romanMonth}/" . date('Y');
+        $this->simpanDokumen($objek, 'notula', $notulaNomor, $nkuList);
+
+        // 2. SURAT PEMBERITAHUAN (OSS) (manual)
+        $spNomor = "B.{$objek->id}/{$kodeSurat}/PW.150/{$romanMonth}/" . date('Y');
+        $this->simpanDokumen($objek, 'surat_pemberitahuan_oss', $spNomor, $nkuList);
+
+        // 3. STKL (manual)
+        $stklNomor = "B.{$objek->id}/{$kodeSurat}/KP.440/{$romanMonth}/" . date('Y');
+        $this->simpanDokumen($objek, 'stkl', $stklNomor, $nkuList);
+
+        // 4. SURAT TUGAS (mock portal_dokumen agar bisa dicari + jadi target laporan)
+        $stNomor = "B.{$objek->id}/{$kodeSurat}/KP.440/{$romanMonth}/" . date('Y');
+        $stDokumenId = (int) (time() . rand(100, 999));
+        $portalDokumen = PortalDokumen::updateOrCreate(
+            ['ref_number' => $stNomor],
+            [
+                'dokumen_id' => $stDokumenId,
+                'km' => 'KP 440.' . rand(1, 9),
+                'subject' => 'SPDRUT_Pemeriksaan Lapangan ' . $objek->nama_perusahaan,
+                'type' => 'Surat Keluar',
+                'category' => 'Surat Tugas',
+                'sender' => 'DIREKTUR JENDERAL PSDKP (UAT)',
+                'dokumen' => '/api/v1/korespondensi/file/' . $stDokumenId,
+                'status' => true,
+                'letter_date' => date('Y-m-d'),
+                'date' => date('Y-m-d'),
+                'time' => date('H:i:s'),
+            ]
+        );
+        $this->simpanDokumen($objek, 'surat_tugas', $stNomor, $nkuList, $portalDokumen->id);
+
+        // Dual-write legacy + status
+        $objek->stkl = 'ada';
+        $objek->surat_pemberitahuan = 'ada';
+        $objek->surat_tugas = 'korespondensi';
+        $objek->status = ObjekPengawasan::MenungguInspeksi;
+        $objek->save();
+
+        $this->info("=========================================");
+        $this->info("Objek siap uji LHP. Nomor ST: " . $stNomor);
+        $this->info("Status: " . $objek->status);
+        $this->line("Langkah berikutnya: php artisan ppbbr:uat-generate-laporan {$objek->id}");
+        $this->info("=========================================");
+
+        return Command::SUCCESS;
+    }
+
+    /**
+     * Generate PDF + simpan baris ppbbr_dokumen_penjadwalan (by system).
+     */
+    private function simpanDokumen(ObjekPengawasan $objek, string $jenis, string $nomorSurat, array $nkuList, ?int $portalDokumenId = null): string
+    {
+        $pdf = SnappyPdf::loadView('ppbbr.uat.surat_tugas', ['objek' => $objek, 'nkuList' => $nkuList]);
+
+        $filename = $jenis . '_uat_' . $objek->id . '_' . time() . '.pdf';
+        $relativeDir = 'pengawasan_perizinan_berusaha/penjadwalan/' . $jenis;
+        $absoluteDir = storage_path('app/public/' . $relativeDir);
+
+        if (!is_dir($absoluteDir)) {
+            mkdir($absoluteDir, 0755, true);
+        }
+
+        file_put_contents($absoluteDir . DIRECTORY_SEPARATOR . $filename, $pdf->output());
+        $filePath = 'storage/' . $relativeDir . '/' . $filename;
+
+        DokumenPenjadwalan::updateOrCreate(
+            ['objek_pengawasan_id' => $objek->id, 'jenis_dokumen' => $jenis],
+            [
+                'portal_dokumen_id' => $portalDokumenId,
+                'file_path' => $filePath,
+                'manual_nomor_surat' => $nomorSurat,
+                'manual_tanggal_surat' => date('Y-m-d'),
+                'is_dokumen_pendukung' => false,
+                'is_active' => true,
+            ]
+        );
+
+        return $filePath;
+    }
+}
