+<?php
+
+namespace App\Jobs;
+
+use App\Http\Library\WaNotifications;
+use App\Models\PegawaiInternal;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use Illuminate\Bus\Queueable;
+use Illuminate\Contracts\Queue\ShouldQueue;
+use Illuminate\Foundation\Bus\Dispatchable;
+use Illuminate\Queue\InteractsWithQueue;
+use Illuminate\Queue\SerializesModels;
+
+class ProcessSendWaLaporanSinkronisasi implements ShouldQueue
+{
+    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels, WaNotifications;
+
+    private $objekPengawasan;
+    private $tanggalDeadline;
+    private $serverCode;
+
+    public function __construct(ObjekPengawasan $objekPengawasan, string $tanggalDeadline, string $serverCode)
+    {
+        $this->objekPengawasan = $objekPengawasan;
+        $this->tanggalDeadline = $tanggalDeadline;
+        $this->serverCode = $serverCode;
+    }
+
+    public function handle()
+    {
+        $nipPengawas = $this->objekPengawasan->pengawas->pluck('nip');
+        $noHp = PegawaiInternal::whereIn('nip', $nipPengawas)->get()->pluck('no_telp')->filter()->implode(',');
+
+        if (empty($noHp)) {
+            return;
+        }
+
+        $this->laporanSinkronisasiReminderWaNotification(
+            $this->objekPengawasan,
+            $this->tanggalDeadline,
+            $noHp,
+            $this->serverCode
+        );
+    }
+}
