+<?php
+
+namespace App\Models\PengawasanPerizinanBerusaha\LaporanPengawasan;
+
+use Illuminate\Database\Eloquent\Model;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use Modules\Gateway\Entities\PortalDokumen;
+
+class LaporanHasilPengawasan extends Model
+{
+    protected $table = 'ppbbr_laporan_hasil_pengawasan';
+    protected $guarded = ['id'];
+
+    protected $casts = [
+        'is_revision' => 'boolean',
+        'is_synced' => 'boolean',
+        'waktu_laporan' => 'datetime',
+        'deadline_sinkronisasi' => 'date',
+        'url_dokumen' => 'array',
+    ];
+
+    public function objekPengawasan()
+    {
+        return $this->belongsTo(ObjekPengawasan::class, 'objek_pengawasan_id');
+    }
+
+    public function portalDokumen()
+    {
+        return $this->belongsTo(PortalDokumen::class, 'portal_dokumen_id');
+    }
+
+    public function riwayat()
+    {
+        return $this->hasMany(LaporanHasilPengawasanRiwayat::class, 'laporan_id');
+    }
+}
