@@ -0,0 +1,316 @@
+<?php
+
+namespace App\Services\PengawasanPerizinanBerusaha;
+
+use App\Http\Library\ApiHelpers;
+use App\Http\Library\AuthHelpers;
+use App\Http\Library\EnkripsiHelper;
+use App\Models\PengawasanPerizinanBerusaha\InspeksiLapangan\BeritaAcaraPemeriksaan;
+use App\Models\PengawasanPerizinanBerusaha\LaporanPengawasan\LaporanHasilPengawasan;
+use App\Models\PengawasanPerizinanBerusaha\LaporanPengawasan\LaporanHasilPengawasanRiwayat;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenMetadata;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use Carbon\Carbon;
+use Exception;
+use Illuminate\Http\JsonResponse;
+use Illuminate\Support\Facades\Auth;
+use Illuminate\Support\Facades\DB;
+use Modules\Gateway\Entities\PortalDokumen;
+
+class LaporanHasilPengawasanService
+{
+    use ApiHelpers, AuthHelpers, EnkripsiHelper;
+
+    const STATUS_MENUNGGU_VERIFIKASI = 'Menunggu Verifikasi';
+    const STATUS_TERVERIFIKASI = 'Terverifikasi';
+
+    private $objekPengawasan;
+    private $laporan;
+    private $riwayat;
+
+    public function __construct()
+    {
+        $this->objekPengawasan = new ObjekPengawasan();
+        $this->laporan = new LaporanHasilPengawasan();
+        $this->riwayat = new LaporanHasilPengawasanRiwayat();
+    }
+
+    /**
+     * Otorisasi melengkapi Laporan Hasil Pengawasan berdasarkan permission.
+     *
+     * Endpoint khusus LHP (`ppbbr.hasil-inspeksi.dokumen.*`); permission
+     * didaftarkan via AkunPenjadwalanLhpSeeder.
+     */
+    private function authorizeLengkapiLaporan(): void
+    {
+        $user = Auth::user();
+
+        if (!$user || !$user->can('ppbbr.hasil-inspeksi.dokumen.store')) {
+            throw new Exception('Anda tidak memiliki akses untuk melengkapi Laporan Hasil Pengawasan (membutuhkan permission ppbbr.hasil-inspeksi.dokumen.store). Hubungi admin untuk pemberian akses.');
+        }
+    }
+
+    /**
+     * Simpan / Bulk Save Laporan (Nota Dinas) ke satu/banyak Objek Pengawasan.
+     * Menangani sinkronisasi pertama maupun reupload (revisi) s/d H+14.
+     */
+    public function simpanLaporan($request): JsonResponse
+    {
+        DB::beginTransaction();
+        try {
+            $this->authorizeLengkapiLaporan();
+
+            $objekIds = $request->objek_pengawasan_ids ?? [];
+
+            // Resolve portal_dokumen_id (terenkripsi dari FE)
+            $portalDokumenId = null;
+            if ($request->portal_dokumen_id) {
+                $decryptedId = $this->dekrip($request->portal_dokumen_id);
+                $portalDokumen = PortalDokumen::where('id', $decryptedId)
+                    ->orWhere('dokumen_id', $decryptedId)
+                    ->first();
+                if ($portalDokumen) {
+                    $portalDokumenId = $portalDokumen->id;
+                }
+            }
+
+            // Normalisasi dokumen_pendukung (array link, bisa > 1)
+            $urlDokumen = $request->dokumen_pendukung;
+            if (is_string($urlDokumen)) {
+                $urlDokumen = array_map('trim', explode(',', $urlDokumen));
+            }
+            $urlDokumen = is_array($urlDokumen) ? array_values(array_filter($urlDokumen)) : null;
+
+            // Simpan permanen metadata ekstraksi (dari cache session_id) jika ada
+            if ($request->session_id) {
+                $ekstrakService = new EkstrakDokumenService();
+                $cacheData = $ekstrakService->ambilDariCache($request->session_id);
+                if ($cacheData && is_array($cacheData)) {
+                    $allEkstrak = array_filter($cacheData, function ($key) {
+                        return $key !== 'file_path';
+                    }, ARRAY_FILTER_USE_KEY);
+
+                    $ekstrakService->simpanPermanen($allEkstrak, $portalDokumenId, null, 'laporan');
+                    $ekstrakService->hapusCache($request->session_id);
+                }
+            }
+
+            $aktorNip = Auth::user()?->pegawaiInternal?->nip;
+            $hasil = [];
+
+            foreach ($objekIds as $idStr) {
+                $objekId = is_numeric($idStr) ? $idStr : $this->dekrip($idStr);
+                $objek = $this->objekPengawasan->find($objekId);
+
+                if (!$objek) continue;
+
+                $deadline = $this->hitungDeadline($objek->id);
+
+                $existing = $this->laporan->where('objek_pengawasan_id', $objek->id)->first();
+
+                if ($existing) {
+                    // REUPLOAD / REVISI: hanya boleh s/d H+14
+                    if ($existing->deadline_sinkronisasi
+                        && now()->startOfDay()->gt(Carbon::parse($existing->deadline_sinkronisasi)->startOfDay())) {
+                        throw new Exception("Batas waktu reupload laporan (H+14) sudah berakhir untuk proyek {$objek->no_kode_proyek}.");
+                    }
+
+                    // Simpan histori versi lama
+                    $this->riwayat->create([
+                        'laporan_id' => $existing->id,
+                        'version' => $existing->version,
+                        'file_url' => $existing->url_dokumen,
+                        'status' => $existing->status,
+                        'aktor_nip' => $aktorNip,
+                    ]);
+
+                    $existing->version = $existing->version + 1;
+                    $existing->is_revision = true;
+                    $existing->status = self::STATUS_MENUNGGU_VERIFIKASI;
+                    $existing->waktu_laporan = now();
+                    $existing->is_synced = true;
+                    $existing->uploaded_by = $aktorNip;
+                    if ($portalDokumenId) $existing->portal_dokumen_id = $portalDokumenId;
+                    if (!empty($urlDokumen)) $existing->url_dokumen = $urlDokumen;
+                    if (!$existing->deadline_sinkronisasi) $existing->deadline_sinkronisasi = $deadline;
+                    $existing->save();
+
+                    $hasil[] = [
+                        'objek_pengawasan_id' => $this->enkrip($objek->id),
+                        'laporan_id' => $this->enkrip($existing->id),
+                        'version' => $existing->version,
+                    ];
+                } else {
+                    // SINKRONISASI PERTAMA (1 tim = 1 sync)
+                    $created = $this->laporan->create([
+                        'objek_pengawasan_id' => $objek->id,
+                        'portal_dokumen_id' => $portalDokumenId,
+                        'status' => self::STATUS_MENUNGGU_VERIFIKASI,
+                        'version' => 1,
+                        'is_revision' => false,
+                        'waktu_laporan' => now(),
+                        'deadline_sinkronisasi' => $deadline,
+                        'is_synced' => true,
+                        'url_dokumen' => $urlDokumen,
+                        'uploaded_by' => $aktorNip,
+                    ]);
+
+                    $hasil[] = [
+                        'objek_pengawasan_id' => $this->enkrip($objek->id),
+                        'laporan_id' => $this->enkrip($created->id),
+                        'version' => 1,
+                    ];
+                }
+            }
+
+            DB::commit();
+
+            return $this->onSuccess('Laporan berhasil disimpan', $hasil);
+        } catch (Exception $e) {
+            DB::rollBack();
+
+            return $this->onError($e->getMessage());
+        }
+    }
+
+    /**
+     * Detail laporan untuk satu objek pengawasan (termasuk histori & sisa hari).
+     */
+    public function detailLaporan(string $objekId): ?array
+    {
+        $objekId = is_numeric($objekId) ? $objekId : $this->dekrip($objekId);
+
+        $laporan = $this->laporan->with('riwayat')
+            ->where('objek_pengawasan_id', $objekId)
+            ->first();
+
+        if (!$laporan) return null;
+
+        $sisaHari = null;
+        if ($laporan->deadline_sinkronisasi) {
+            $sisaHari = now()->startOfDay()->diffInDays(Carbon::parse($laporan->deadline_sinkronisasi)->startOfDay(), false);
+        }
+
+        return [
+            'id' => $this->enkrip($laporan->id),
+            'status' => $laporan->status,
+            'status_label' => $laporan->status,
+            'version' => $laporan->version,
+            'is_revision' => $laporan->is_revision,
+            'waktu_laporan' => $laporan->waktu_laporan?->toDateTimeString(),
+            'deadline_sinkronisasi' => $laporan->deadline_sinkronisasi?->toDateString(),
+            'sisa_hari' => $sisaHari,
+            'can_upload_laporan' => $this->canUploadLaporan($laporan),
+            'dokumen_pendukung' => $laporan->url_dokumen,
+            'histori' => $laporan->riwayat->map(function ($r) {
+                return [
+                    'version' => $r->version,
+                    'file_url' => $r->file_url,
+                    'status' => $r->status,
+                    'aktor_nip' => $r->aktor_nip,
+                    'created_at' => $r->created_at?->toDateTimeString(),
+                ];
+            })->values()->all(),
+        ];
+    }
+
+    /**
+     * Lookup dokumen Laporan tersimpan berdasarkan daftar NKU (array).
+     * Alur: NKU -> Objek Pengawasan -> Nomor ST -> Dokumen Laporan (metadata).
+     *
+     * @param array<int,string> $nkuList
+     * @return array<int,array>
+     */
+    public function cariDokumenRelevan(array $nkuList): array
+    {
+        $nkuList = array_values(array_filter($nkuList));
+        if (empty($nkuList)) return [];
+
+        // 1. NKU -> Objek Pengawasan
+        $objekIds = $this->objekPengawasan->whereIn('no_kode_proyek', $nkuList)->pluck('id');
+
+        // 2. Objek -> Nomor ST (surat_tugas)
+        $stNomors = DokumenPenjadwalan::whereIn('objek_pengawasan_id', $objekIds)
+            ->where('jenis_dokumen', 'surat_tugas')
+            ->with('portalDokumen')
+            ->get()
+            ->map(function ($d) {
+                return $d->manual_nomor_surat ?: optional($d->portalDokumen)->ref_number;
+            })
+            ->filter()
+            ->unique()
+            ->values()
+            ->all();
+
+        if (empty($stNomors)) return [];
+
+        // 3. Nomor ST -> Dokumen Laporan tersimpan
+        $metas = DokumenMetadata::where('jenis_dokumen', 'laporan')
+            ->whereIn('nilai', $stNomors)
+            ->whereNotNull('portal_dokumen_id')
+            ->with(['portalDokumen'])
+            ->get();
+
+        return $metas->map(function ($meta) {
+            $portal = $meta->portalDokumen;
+            return [
+                'portal_dokumen_id' => $meta->portal_dokumen_id ? $this->enkrip($meta->portal_dokumen_id) : null,
+                'nomor_surat' => $portal->ref_number ?? $meta->nilai,
+                'perihal' => $portal->subject ?? null,
+                'pengirim' => $portal->sender ?? null,
+                'nilai' => $meta->nilai,
+            ];
+        })->unique('portal_dokumen_id')->values()->all();
+    }
+
+    /**
+     * Cek apakah laporan masih boleh diunggah/di-reupload (belum lewat H+14).
+     */
+    public function canUploadLaporan(?LaporanHasilPengawasan $laporan): bool
+    {
+        if (!$laporan) return true;
+        if (!$laporan->deadline_sinkronisasi) return true;
+
+        return now()->startOfDay()->lte(Carbon::parse($laporan->deadline_sinkronisasi)->startOfDay());
+    }
+
+    /**
+     * Guard reupload: lempar exception bila sudah melewati H+14.
+     */
+    public function guardBatasReupload(?LaporanHasilPengawasan $laporan): void
+    {
+        if ($laporan && !$this->canUploadLaporan($laporan)) {
+            throw new Exception('Batas waktu reupload laporan (H+14) sudah berakhir.');
+        }
+    }
+
+    /**
+     * Hitung deadline sinkronisasi: (BAP + batas_hari_pelaporan) ATAU tanggal 2 Apr/Jul/Okt/Jan,
+     * dipilih yang lebih cepat.
+     */
+    public function hitungDeadline(int $objekId): ?string
+    {
+        $bap = BeritaAcaraPemeriksaan::where('objek_pengawasan_id', $objekId)->first();
+        $base = ($bap && $bap->tanggal_pemeriksaan) ? Carbon::parse($bap->tanggal_pemeriksaan) : now();
+
+        $days = (int) config('ppbbr.batas_hari_pelaporan', 14);
+        $hN = $base->copy()->addDays($days);
+
+        // Tanggal 2 di bulan Apr/Jul/Okt/Jan (terdekat setelah base)
+        $quarterDate = null;
+        foreach ([4, 7, 10, 1] as $month) {
+            $candidate = Carbon::create($base->year, $month, 2, 0, 0, 0);
+            if ($candidate->lt($base)) {
+                $candidate->addYear();
+            }
+            if ($quarterDate === null || $candidate->lt($quarterDate)) {
+                $quarterDate = $candidate;
+            }
+        }
+
+        $deadline = ($quarterDate && $quarterDate->lt($hN)) ? $quarterDate : $hN;
+
+        return $deadline->toDateString();
+    }
+}
