@@ -0,0 +1,179 @@
+<?php
+
+namespace Database\Seeders\PPBBR;
+
+use App\Models\User;
+use App\Models\PegawaiInternal;
+use App\Traits\HasRbacSeeder;
+use Illuminate\Database\Seeder;
+use Illuminate\Database\Eloquent\Model;
+use Illuminate\Support\Facades\Log;
+use Spatie\Permission\Models\Role;
+use Spatie\Permission\PermissionRegistrar;
+
+/**
+ * Akun & Permission khusus Penjadwalan dan Laporan Hasil Pengawasan (LHP).
+ *
+ * Mendaftarkan permission berdasarkan route name terbaru (ppbbr.penjadwalan.*,
+ * ppbbr.hasil-inspeksi.*), memberikannya ke role Operator WasRisk, lalu
+ * menetapkan role tersebut ke akun operator yang sudah ada
+ * (tidak membuat akun baru), mengikuti pola AkunSeeder.
+ *
+ * Service mengandalkan permission ini (hasPermissionTo), bukan hardcode role:
+ * - ppbbr.hasil-inspeksi.dokumen.store  -> Simpan LHP (endpoint khusus)
+ * - ppbbr.penjadwalan.dokumen.store  -> Simpan Dokumen Penjadwalan
+ * - ppbbr.penjadwalan.dokumen.unggah.store -> Unggah Dokumen Manual
+ */
+class AkunPenjadwalanLhpSeeder extends Seeder
+{
+    use HasRbacSeeder;
+
+    private const MODUL_NAME = 'Pengawasan Perizinan Berusaha';
+
+    private const PERMISSIONS = [
+        [
+            'feature' => 'Dokumen Penjadwalan',
+            'permissions' => [
+                'ppbbr.penjadwalan.index',
+                'ppbbr.penjadwalan.show',
+                'ppbbr.penjadwalan.ringkasan.index',
+                'ppbbr.penjadwalan.daftar-pengawas.index',
+                'ppbbr.penjadwalan.dokumen.existing.show',
+                'ppbbr.penjadwalan.dokumen.extract.store',
+                'ppbbr.penjadwalan.dokumen.store',
+                'ppbbr.penjadwalan.dokumen.unggah.store',
+            ],
+        ],
+        [
+            'feature' => 'Laporan Hasil Pengawasan',
+            'permissions' => [
+                'ppbbr.hasil-inspeksi.index',
+                'ppbbr.hasil-inspeksi.show',
+                'ppbbr.hasil-inspeksi.dokumen.extract.store',
+                'ppbbr.hasil-inspeksi.dokumen.store',
+            ],
+        ],
+    ];
+
+    // Permission tulis yang wajib dimiliki untuk melengkapi dokumen & LHP.
+    public const WRITE_PERMISSIONS = [
+        'ppbbr.penjadwalan.dokumen.store',
+        'ppbbr.penjadwalan.dokumen.unggah.store',
+        'ppbbr.hasil-inspeksi.dokumen.store',
+    ];
+
+    // Note: data operator pusat dan pengelola data berdasarkan hasil bimtek di pangkalan psdkp jakarta
+    // https://docs.google.com/spreadsheets/d/1mh3TJ7fYk-m16E2VSnyO2Il8mlGraSnSVcUm4AY8p9s
+
+    const OPERATOR_PUSAT = [
+        // WASKAPI
+        'RANIA FABIANI',
+        'RENATA RUTH IRENE SONDANG SIHOMBING',
+        'MEI PRIPTANINGRUM',
+        'ASEP SUPRIADI',
+        'SINGGIH PRIHADI AJI',
+        'AMRIH JOKO WASPADA',
+        'YUDHISTIRA RIZKY ABDILLAH',
+        // WASBUD
+        'EKO TONDO SUPRAPTO',
+        'YULIANUS DIGUL SUSETYO',
+        'AZMIL MUFARRICHA FAJARANI',
+        'ADHIE MEISYAPUTRA',
+        // WASOLAH
+        'DONNY MUHAMAD FAISAL',
+        'HERYATI SETYANINGSIH',
+        'OBDULIA PRATIWI NUGRAHANI',
+        'ARI WAWASTO',
+        'MOCHAMMAD INDRO BUWONO',
+        'WICAKSONO ADHI WARDOYO',
+        'PRASASTI BRAMANTYA',
+        'RINA FARIANI SARAGIH',
+        'RENI ASMARANY',
+    ];
+
+    const OPERATOR_UPT = [
+        'EKO PRASETYO RITANTO',
+        'MISDI',
+        'RAHMAN HAKIM PURNAMA',
+        'YUDI GUSWORO SAPUTRO',
+        'Herianus paskah',
+        'Fajar Surya Pratama',
+        'Josia Suarta Sembiring',
+        'NUR ILHAM',
+        'YOGI PUTRANTO',
+        'INDRA ARFIANDANI',
+        'Krisnawan Nindito',
+        'Rizqi Tatri Kusuma',
+        'Stevenly Alexsander Takapaha',
+        'ISMAIL',
+    ];
+
+    /**
+     * Run the database seeds.
+     *
+     * @return void
+     */
+    public function run()
+    {
+        Model::unguard();
+
+        // 1. Daftarkan permission berdasarkan route name terbaru
+        $this->seedModulePermissions([self::MODUL_NAME => self::PERMISSIONS]);
+
+        // 2. Sync seluruh permission modul ke Superuser & Superadmin
+        $this->syncToSuperRoles();
+
+        // 3. Berikan permission tulis ke role Operator WasRisk
+        $this->grantWritePermissionsToOperatorRoles();
+
+        // 4. Tetapkan role operator ke akun yang sudah ada
+        $this->operatorPusat();
+        $this->operatorUPT();
+
+        app(PermissionRegistrar::class)->forgetCachedPermissions();
+    }
+
+    private function grantWritePermissionsToOperatorRoles(): void
+    {
+        foreach (['Operator UPT WasRisk', 'Operator Pusat WasRisk'] as $roleName) {
+            $role = Role::findOrCreate($roleName, 'api');
+            $role->givePermissionTo(self::WRITE_PERMISSIONS);
+
+            if (property_exists($this, 'command') && $this->command) {
+                $this->command->info("Write permissions granted to role: {$roleName}");
+            }
+        }
+    }
+
+    private function operatorPusat(): void
+    {
+        $operatorPusat = self::OPERATOR_PUSAT;
+
+        foreach ($operatorPusat as $namaPegawai) {
+            $pegawaiInternal = PegawaiInternal::where('nama_pegawai', $namaPegawai)->orderBy('id', 'desc')->first();
+            $user = User::where('pegint_id', $pegawaiInternal?->nip)->first();
+
+            if ($pegawaiInternal && $user) {
+                $user->assignRole(['Operator Pusat WasRisk']);
+            } else if (!$pegawaiInternal) {
+                Log::error("Gagal Generate Akun Operator Pusat (PPBBR) \"{$namaPegawai}\". Alasan: Data/Akun Pegawai tidak ditemukan");
+            }
+        }
+    }
+
+    private function operatorUPT(): void
+    {
+        $operatorUPT = self::OPERATOR_UPT;
+
+        foreach ($operatorUPT as $namaPegawai) {
+            $pegawaiInternal = PegawaiInternal::where('nama_pegawai', $namaPegawai)->orderBy('id', 'desc')->first();
+            $user = User::where('pegint_id', $pegawaiInternal?->nip)->first();
+
+            if ($pegawaiInternal && $user) {
+                $user->assignRole(['Operator UPT WasRisk']);
+            } else if (!$pegawaiInternal) {
+                Log::error("Gagal Generate Akun Operator UPT WasRisk (PPBBR) \"{$namaPegawai}\". Alasan: Data/Akun Pegawai tidak ditemukan");
+            }
+        }
+    }
+}
