+## 6. Struktur Relasi Database
+
+```mermaid
+erDiagram
+    OBJEK_PENGAWASAN ||--o{ LAPORAN_HASIL_PENGAWASAN : "hasMany (1 laporan/objek)"
+    PORTAL_DOKUMEN ||--o{ LAPORAN_HASIL_PENGAWASAN : "hasMany (1 Nota Dinas : N objek)"
+    PORTAL_DOKUMEN ||--o{ DOKUMEN_METADATA : "hasMany"
+    LAPORAN_HASIL_PENGAWASAN ||--o{ LAPORAN_HASIL_PENGAWASAN_RIWAYAT : "hasMany (histori versi)"
+
+    OBJEK_PENGAWASAN {
+        int id PK
+        string nama_perusahaan
+        string unit_kerja
+    }
+
+    LAPORAN_HASIL_PENGAWASAN {
+        int id PK
+        int objek_pengawasan_id FK
+        int portal_dokumen_id FK "Nota Dinas CSRS"
+        string status "Enum: Menunggu Verifikasi, Terverifikasi"
+        int version "Versi terbaru"
+        boolean is_revision
+        datetime waktu_laporan
+        date deadline_sinkronisasi
+        boolean is_synced
+        json url_dokumen "Nullable (array link dokumen — dari CSRS/input)"
+    }
+
+    LAPORAN_HASIL_PENGAWASAN_RIWAYAT {
+        int id PK
+        int laporan_id FK
+        int version
+        string file_url "Nullable"
+        string status "Status saat versi tsb"
+        string notes "Nullable"
+        string aktor_nip "Nullable"
+        timestamp created_at
+    }
+
+    DOKUMEN_METADATA {
+        int id PK
+        int portal_dokumen_id FK "Nullable"
+        string file_path "Nullable"
+        string jenis_dokumen "Enum: notula, surat_tugas, laporan"
+        string jenis_item "Enum: nku, nomor_st"
+        string nilai "Nomor ST hasil ekstrak"
+        int objek_pengawasan_id FK "Nullable (invalid saat diekstrak)"
+    }
+
+    PORTAL_DOKUMEN {
+        int id PK
+        string ref_number
+        string sender
+        string subject
+    }
+```
+
