diff --git a/tests/Feature/Console/ScheduleLaporanTest.php b/tests/Feature/Console/ScheduleLaporanTest.php
new file mode 100644
index 0000000000..b38fcb42d9
--- /dev/null
+++ b/tests/Feature/Console/ScheduleLaporanTest.php
@@ -0,0 +1,66 @@
+<?php
+
+namespace Tests\Feature\Console;
+
+use Illuminate\Console\Scheduling\Schedule;
+use Tests\TestCase;
+
+/**
+ * Memverifikasi registrasi schedule di `routes/console.php` (blok production):
+ * - `ppbbr:notifikasi-sinkronisasi-laporan` (LHP) harian 08:00 Asia/Jakarta.
+ * - `ppbbr:penjadwalan-expired` harian 06:00 Asia/Jakarta.
+ * - Tidak terdaftar saat non-production.
+ */
+class ScheduleLaporanTest extends TestCase
+{
+    private function eventsInProduction(): \Illuminate\Support\Collection
+    {
+        $this->app['env'] = 'production';
+        require base_path('routes/console.php');
+
+        return collect($this->app->make(Schedule::class)->events());
+    }
+
+    private function findEvent(\Illuminate\Support\Collection $events, string $command)
+    {
+        return $events->first(fn ($event) => str_contains((string) $event->command, $command));
+    }
+
+    /** @test */
+    public function notifikasi_sinkronisasi_laporan_dijadwalkan_harian_jam_8()
+    {
+        $event = $this->findEvent(
+            $this->eventsInProduction(),
+            'ppbbr:notifikasi-sinkronisasi-laporan'
+        );
+
+        $this->assertNotNull($event, 'Schedule notifikasi sinkronisasi LHP tidak terdaftar.');
+        $this->assertEquals('0 8 * * *', $event->expression);
+        $this->assertEquals('Asia/Jakarta', $event->timezone);
+    }
+
+    /** @test */
+    public function penjadwalan_expired_dijadwalkan_harian_jam_6()
+    {
+        $event = $this->findEvent(
+            $this->eventsInProduction(),
+            'ppbbr:penjadwalan-expired'
+        );
+
+        $this->assertNotNull($event, 'Schedule penjadwalan-expired tidak terdaftar.');
+        $this->assertEquals('0 6 * * *', $event->expression);
+        $this->assertEquals('Asia/Jakarta', $event->timezone);
+    }
+
+    /** @test */
+    public function schedule_tidak_terdaftar_di_non_production()
+    {
+        $this->assertNotEquals('production', $this->app['env']);
+
+        require base_path('routes/console.php');
+        $events = collect($this->app->make(Schedule::class)->events());
+
+        $this->assertNull($this->findEvent($events, 'ppbbr:notifikasi-sinkronisasi-laporan'));
+        $this->assertNull($this->findEvent($events, 'ppbbr:penjadwalan-expired'));
+    }
