@@ -0,0 +1,102 @@
+<?php
+
+namespace Tests\Feature\PengawasanPerizinanBerusaha;
+
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Tests\TestCase;
+
+/**
+ * Menguji command terjadwal `ppbbr:penjadwalan-expired` (dailyAt 06:00 di production):
+ * - jadwal lewat X hari & belum selesai -> PenjadwalanTerlewat + hapus dokumen.
+ * - Hari H & dokumen lengkap (MenungguInspeksi) -> Inspeksi.
+ * - Hari H & dokumen tidak lengkap (LengkapiDokumen) -> PenjadwalanTerlewat (tanpa hapus dokumen).
+ */
+class CekJadwalPengawasanTerlewatTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    private function buatObjek(string $status, ?string $jadwal): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $kode = 'U-' . rand(100000, 999999);
+        \App\Models\UnitKerja::create([
+            'kode_unit' => $kode,
+            'nama_unit' => 'Unit Uji ' . uniqid(),
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        return ObjekPengawasanFactory::new()->create([
+            'status' => $status,
+            'unit_kerja' => $kode,
+            'jadwal' => $jadwal,
+        ]);
+    }
+
+    /** @test */
+    public function jadwal_lewat_menjadi_terlewat_dan_menghapus_dokumen()
+    {
+        config(['ppbbr.notifikasi.hari_penjadwalan_terlewat' => 3650]);
+
+        $objek = $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS, '2000-01-01');
+        DokumenPenjadwalan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'jenis_dokumen' => 'notula',
+        ]);
+
+        $selesai = $this->buatObjek(ObjekPengawasan::Selesai, '2000-01-01');
+
+        $this->artisan('ppbbr:penjadwalan-expired')->assertSuccessful();
+
+        $objek->refresh();
+        $this->assertEquals(ObjekPengawasan::PenjadwalanTerlewat, $objek->status);
+        $this->assertNull($objek->jadwal);
+        $this->assertEquals(0, DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)->count());
+
+        // Objek berstatus Selesai tidak boleh tersentuh
+        $this->assertEquals(ObjekPengawasan::Selesai, $selesai->fresh()->status);
+        $this->assertEquals('2000-01-01', $selesai->fresh()->jadwal);
+    }
+
+    /** @test */
+    public function hari_h_dokumen_lengkap_menjadi_inspeksi()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::MenungguInspeksi, now()->toDateString());
+
+        $this->artisan('ppbbr:penjadwalan-expired')->assertSuccessful();
+
+        $this->assertEquals(ObjekPengawasan::Inspeksi, $objek->fresh()->status);
+    }
+
+    /** @test */
+    public function hari_h_dokumen_tidak_lengkap_menjadi_terlewat_tanpa_hapus_dokumen()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::LengkapiDokumen, now()->toDateString());
+        DokumenPenjadwalan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'jenis_dokumen' => 'notula',
+        ]);
+
+        $this->artisan('ppbbr:penjadwalan-expired')->assertSuccessful();
+
+        $this->assertEquals(ObjekPengawasan::PenjadwalanTerlewat, $objek->fresh()->status);
+        $this->assertEquals(1, DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)->count());
+    }
+
+    /** @test */
+    public function jadwal_belum_hari_h_tidak_berubah()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::MenungguInspeksi, now()->addDays(3)->toDateString());
+
+        $this->artisan('ppbbr:penjadwalan-expired')->assertSuccessful();
+
+        $this->assertEquals(ObjekPengawasan::MenungguInspeksi, $objek->fresh()->status);
+    }
+}
