+<?php
+
+namespace Tests\Feature\PengawasanPerizinanBerusaha;
+
+use App\Http\Library\EnkripsiHelper;
+use App\Models\PegawaiInternal;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use App\Models\UnitKerja;
+use App\Models\User;
+use App\Services\PengawasanPerizinanBerusaha\DashboardPerizinanBerusahaService;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Illuminate\Http\Request;
+use Illuminate\Support\Facades\Auth;
+use Spatie\Permission\Models\Role;
+use Tests\TestCase;
+
+/**
+ * Menguji DashboardPerizinanBerusahaService setelah perubahan status penjadwalan:
+ * status LengkapiDokumen / MenungguInspeksi / BelumUploadST / PersetujuanDisetujuiOSS
+ * masuk kategori "Belum Dijadwalkan", dan pie penugasan (belum/sudah ditugaskan).
+ */
+class DashboardPenjadwalanPieTest extends TestCase
+{
+    use DatabaseTransactions;
+    use EnkripsiHelper;
+
+    private DashboardPerizinanBerusahaService $service;
+    private UnitKerja $unit;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        $this->service = new DashboardPerizinanBerusahaService();
+
+        $this->unit = UnitKerja::create([
+            'kode_unit' => 'U-' . rand(100000, 999999),
+            'nama_unit' => 'Unit Uji ' . uniqid(),
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        $this->loginUser();
+    }
+
+    private function loginUser(): void
+    {
+        $role = 'Operator UPT WasRisk';
+        Role::firstOrCreate(['name' => $role, 'guard_name' => 'api']);
+
+        $user = User::create([
+            'username' => 'test_' . uniqid(),
+            'password' => bcrypt('password'),
+        ]);
+        $user->assignRole($role);
+
+        $pegawai = PegawaiInternal::create([
+            'nip' => 'NIP' . rand(10000, 99999),
+            'nama_pegawai' => 'Pegawai Uji',
+            'unit_kerja_id' => $this->unit->kode_unit,
+            'user_id' => $user->id,
+        ]);
+
+        $user->pegint_id = $pegawai->nip;
+        $user->save();
+
+        Auth::login($user);
+    }
+
+    private function buatObjek(string $status): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        return ObjekPengawasanFactory::new()->create([
+            'status' => $status,
+            'unit_kerja' => $this->unit->kode_unit,
+        ]);
+    }
+
+    /** @test */
+    public function pie_penjadwalan_inspeksi_status_baru_masuk_belum_dijadwalkan()
+    {
+        $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS);
+        $this->buatObjek(ObjekPengawasan::BelumUploadST);
+        $this->buatObjek(ObjekPengawasan::LengkapiDokumen);
+        $this->buatObjek(ObjekPengawasan::MenungguInspeksi);
+        $this->buatObjek(ObjekPengawasan::SudahDijadwalkan);
+        $this->buatObjek(ObjekPengawasan::PersetujuanTanggalOSS);
+
+        $response = $this->service->piePenjadwalanInspeksi(new Request([]));
+        $data = $response->getData(true);
+        $buckets = collect($data['data'])->keyBy('key');
+
+        $this->assertTrue($data['status'], $data['message'] ?? '');
+        $this->assertEquals(4, $buckets['belum_dijadwalkan']['value']);
+        $this->assertEquals(2, $buckets['sudah_dijadwalkan']['value']);
+
+        $sebaranKeys = collect($buckets['belum_dijadwalkan']['sebaran'])->pluck('key')->all();
+        $this->assertContains('PersetujuanDisetujuiOSS', $sebaranKeys);
+        $this->assertContains('BelumUploadST', $sebaranKeys);
+        $this->assertContains('LengkapiDokumen', $sebaranKeys);
+        $this->assertContains('MenungguInspeksi', $sebaranKeys);
+    }
+
+    /** @test */
+    public function pie_penugasan_membedakan_belum_dan_sudah_ditugaskan()
+    {
+        $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS);
+
+        $sudahDitugaskan = $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS);
+        DokumenPenjadwalan::create([
+            'objek_pengawasan_id' => $sudahDitugaskan->id,
+            'jenis_dokumen' => 'stkl',
+            'file_path' => 'storage/uat/stkl.pdf',
+        ]);
+
+        $response = $this->service->piePenjadwalanPenugasanInspeksi(new Request([]));
+        $data = $response->getData(true);
+        $buckets = collect($data['data'])->keyBy('key');
+
+        $this->assertTrue($data['status'], $data['message'] ?? '');
+        $this->assertEquals(1, $buckets['belum_ditugaskan']['value']);
+        $this->assertEquals(1, $buckets['sudah_ditugaskan']['value']);
+    }
+}
