+use PHPOpenSourceSaver\JWTAuth\Facades\JWTAuth;
+use Spatie\Permission\Models\Role;
+use Tests\TestCase;
+
+/**
+ * Menguji key `status_tombol.laporan` pada list Hasil Inspeksi
+ * (mengikuti pola `status_tombol` di InspeksiLapanganResource):
+ * show = tahap hasil inspeksi, enable = masih boleh upload (H+14).
+ */
+class HasilInspeksiStatusTombolTest extends TestCase
+{
+    use DatabaseTransactions;
+    use EnkripsiHelper;
+
+    private UnitKerja $unit;
+    private string $token;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $this->unit = UnitKerja::create([
+            'kode_unit' => 'U-' . rand(100000, 999999),
+            'nama_unit' => 'Unit Uji ' . uniqid(),
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        Role::firstOrCreate(['name' => 'Operator UPT WasRisk', 'guard_name' => 'api']);
+        $user = User::create([
+            'username' => 'test_' . uniqid(),
+            'password' => bcrypt('password'),
+        ]);
+        $user->assignRole('Operator UPT WasRisk');
+
+        $pegawai = PegawaiInternal::create([
+            'nip' => 'NIP' . rand(10000, 99999),
+            'nama_pegawai' => 'Pegawai Uji',
+            'unit_kerja_id' => $this->unit->kode_unit,
+            'user_id' => $user->id,
+        ]);
+        $user->pegint_id = $pegawai->nip;
+        $user->save();
+
+        $this->token = JWTAuth::fromUser($user);
+    }
+
+    private function buatObjek(): ObjekPengawasan
+    {
+        return ObjekPengawasanFactory::new()->create([
+            'status' => ObjekPengawasan::Selesai,
+            'unit_kerja' => $this->unit->kode_unit,
+            'jadwal' => now()->toDateString(),
+        ]);
+    }
+
+    private function buatLaporan(ObjekPengawasan $objek, ?string $deadline): void
+    {
+        LaporanHasilPengawasan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'status' => 'Menunggu Verifikasi',
+            'version' => 1,
+            'is_revision' => false,
+            'waktu_laporan' => now(),
+            'deadline_sinkronisasi' => $deadline,
+            'is_synced' => true,
+        ]);
+    }
+
+    private function buatLaporanDenganMetadata(ObjekPengawasan $objek, ?string $deadline, string $stNomor): void
+    {
+        $this->buatLaporan($objek, $deadline);
+
+        $portal = PortalDokumen::create([
+            'dokumen_id' => (int) (time() . rand(100, 999)),
+            'ref_number' => 'SPDRUT/' . rand(100, 999),
+            'subject' => 'SPDRUT Nota Dinas',
+            'sender' => 'UPT',
+        ]);
+
+        DokumenPenjadwalan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'jenis_dokumen' => 'surat_tugas',
+            'manual_nomor_surat' => $stNomor,
+        ]);
+
+        DokumenMetadata::create([
+            'portal_dokumen_id' => $portal->id,
+            'jenis_dokumen' => 'laporan',
+            'jenis_item' => 'nomor_st',
+            'nilai' => $stNomor,
+        ]);
+
+        LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)
+            ->update(['portal_dokumen_id' => $portal->id]);
+    }
+
+    private function itemPertama(): array
+    {
+        $response = $this->withHeader('Authorization', "Bearer {$this->token}")
+            ->getJson('/api/v1/ppbbr/hasil-inspeksi');
+
+        $response->assertStatus(200);
+        $response->assertJsonPath('status', true);
+
+        return $response->json('data.0');
+    }
+
+    /** @test */
+    public function objek_belum_lapor_menampilkan_tombol_aktif()
+    {
+        $this->buatObjek();
+
+        $tombol = $this->itemPertama()['status_tombol']['laporan'];
+
+        $this->assertTrue($tombol['show']);
+        $this->assertTrue($tombol['enable']);
+    }
+
+    /** @test */
+    public function objek_sudah_lapor_sebelum_deadline_tombol_tetap_aktif()
+    {
+        $objek = $this->buatObjek();
+        $this->buatLaporan($objek, now()->addDays(5)->toDateString());
+
+        $item = $this->itemPertama();
+        $tombol = $item['status_tombol']['laporan'];
+
+        $this->assertTrue($tombol['show']);
+        $this->assertTrue($tombol['enable']);
+        $this->assertNull($item['laporan']);
+        // Key URL dokumen tak terpakai dihapus dari resource hasil inspeksi
+        $this->assertArrayNotHasKey('stkl', $item);
+        $this->assertArrayNotHasKey('surat_tugas', $item);
+        $this->assertArrayNotHasKey('surat_pemberitahuan', $item);
+        // Key berat/tak terpakai dikosongkan di list (penuh di detail)
+        $this->assertNull($item['jenis']);
+        $this->assertNull($item['status']);
+        // Dikecualikan (dipakai FE): detail_nilai untuk GradeModal
+        $this->assertIsArray($item['nilai']['detail_nilai']);
+    }
+
+    /** @test */
+    public function objek_lewat_deadline_tombol_nonaktif()
+    {
+        $objek = $this->buatObjek();
+        $this->buatLaporan($objek, now()->subDay()->toDateString());
+
+        $item = $this->itemPertama();
+        $tombol = $item['status_tombol']['laporan'];
+
+        $this->assertTrue($tombol['show']);
+        $this->assertFalse($tombol['enable']);
+        $this->assertNull($item['laporan']);
+    }
+
+    /** @test */
+    public function detail_menampilkan_objek_laporan_penuh()
+    {
+        $objek = $this->buatObjek();
+        $stNomor = 'B.18413/PSDKPLan.1/KP.440/IX/2026';
+        $this->buatLaporanDenganMetadata($objek, now()->addDays(5)->toDateString(), $stNomor);
+
+        $response = $this->withHeader('Authorization', "Bearer {$this->token}")
+            ->getJson('/api/v1/ppbbr/hasil-inspeksi/' . $this->enkrip($objek->id));
+
+        $response->assertStatus(200);
+        $response->assertJsonPath('status', true);
+
+        $laporan = $response->json('data.laporan');
+        $this->assertNotNull($laporan);
+        $this->assertEquals(1, $laporan['version']);
+        $this->assertArrayNotHasKey('can_upload_laporan', $laporan);
+        $this->assertArrayHasKey('dokumen_pendukung', $laporan);
+
+        $details = $laporan['details'];
+        $this->assertCount(1, $details);
+        $this->assertEquals('valid', $details[0]['status']);
+        $this->assertTrue($details[0]['is_checked']);
+        $this->assertTrue($details[0]['is_current']);
+        $this->assertEquals($stNomor, $details[0]['nilai']);
+
+        $tombol = $response->json('data.status_tombol.laporan');
+        $this->assertTrue($tombol['show']);
+        $this->assertTrue($tombol['enable']);
+    }
+}
