+use Spatie\Permission\Models\Role;
+use Spatie\Permission\PermissionRegistrar;
+use Tests\TestCase;
+
+/**
+ * Menguji endpoint khusus LHP (pengganti penjadwalan/dokumen + jenis_dokumen=laporan):
+ * - POST /api/v1/ppbbr/hasil-inspeksi/dokumen/{id}/simpan (tanpa jenis_dokumen).
+ */
+class LaporanDokumenEndpointTest extends TestCase
+{
+    use DatabaseTransactions;
+    use EnkripsiHelper;
+
+    private UnitKerja $unit;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $this->unit = UnitKerja::create([
+            'kode_unit' => 'U-' . rand(100000, 999999),
+            'nama_unit' => 'Unit Uji ' . uniqid(),
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+    }
+
+    private function buatUser(string $role, bool $beriPermission): User
+    {
+        $roleModel = Role::firstOrCreate(['name' => $role, 'guard_name' => 'api']);
+
+        if ($beriPermission) {
+            $perm = Permission::findOrCreate('ppbbr.hasil-inspeksi.dokumen.store', 'api');
+            $roleModel->givePermissionTo($perm);
+            app(PermissionRegistrar::class)->forgetCachedPermissions();
+        }
+
+        $user = User::create([
+            'username' => 'test_' . uniqid(),
+            'password' => bcrypt('password'),
+        ]);
+        $user->assignRole($role);
+
+        $pegawai = PegawaiInternal::create([
+            'nip' => 'NIP' . rand(10000, 99999),
+            'nama_pegawai' => 'Pegawai Uji',
+            'unit_kerja_id' => $this->unit->kode_unit,
+            'user_id' => $user->id,
+        ]);
+        $user->pegint_id = $pegawai->nip;
+        $user->save();
+
+        return $user;
+    }
+
+    /** @test */
+    public function simpan_laporan_via_endpoint_khusus_tanpa_jenis_dokumen()
+    {
+        $user = $this->buatUser('Operator UPT WasRisk', true);
+        $objek = ObjekPengawasanFactory::new()->create([
+            'status' => ObjekPengawasan::Selesai,
+            'unit_kerja' => $this->unit->kode_unit,
+        ]);
+
+        $response = $this->withHeader('Authorization', 'Bearer ' . JWTAuth::fromUser($user))
+            ->postJson('/api/v1/ppbbr/hasil-inspeksi/dokumen/' . $this->enkrip($objek->id) . '/simpan', [
+                'dokumen_pendukung' => ['https://contoh.test/nota.pdf'],
+                'objek_pengawasan_ids' => [$this->enkrip($objek->id)],
+            ]);
+
+        $response->assertStatus(200);
+        $response->assertJsonPath('status', true);
+        $response->assertJsonPath('data.0.version', 1);
+
+        $this->assertNotNull(
+            LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)->first()
+        );
+    }
+
+    /** @test */
+    public function simpan_laporan_ditolak_tanpa_permission()
+    {
+        $user = $this->buatUser('Pengawas Perikanan JF', false);
+        $objek = ObjekPengawasanFactory::new()->create([
+            'status' => ObjekPengawasan::Selesai,
+            'unit_kerja' => $this->unit->kode_unit,
+        ]);
+
+        $response = $this->withHeader('Authorization', 'Bearer ' . JWTAuth::fromUser($user))
+            ->postJson('/api/v1/ppbbr/hasil-inspeksi/dokumen/' . $this->enkrip($objek->id) . '/simpan', [
+                'objek_pengawasan_ids' => [$this->enkrip($objek->id)],
+            ]);
+
+        $response->assertStatus(400);
+        $response->assertJsonPath('status', false);
+        $this->assertStringContainsString(
+            'ppbbr.hasil-inspeksi.dokumen.store',
+            $response->json('message')
+        );
+    }
+}
