+<?php
+
+namespace Tests\Feature\PengawasanPerizinanBerusaha;
+
+use App\Jobs\ProcessSendWaLaporanSinkronisasi;
+use App\Models\PegawaiInternal;
+use App\Models\PengawasanPerizinanBerusaha\InspeksiLapangan\BeritaAcaraPemeriksaan;
+use App\Models\PengawasanPerizinanBerusaha\LaporanPengawasan\LaporanHasilPengawasan;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\PengawasanPerizinanBerusaha\Penjadwalan\PengawasInspeksiLapangan;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Illuminate\Support\Facades\Http;
+use Illuminate\Support\Facades\Queue;
+use Modules\Gateway\Entities\Notification\NotificationLog;
+use Tests\TestCase;
+
+/**
+ * Menguji reminder WA sinkronisasi LHP: Command pemilih objek jatuh tempo
+ * dan Job pengiriman WA ke pengawas.
+ */
+class LaporanSinkronisasiNotifikasiTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    private function buatObjek(string $status = ObjekPengawasan::Selesai): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $kode = 'U-' . rand(100000, 999999);
+        \App\Models\UnitKerja::create([
+            'kode_unit' => $kode,
+            'nama_unit' => 'Test Unit ' . $kode,
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        return ObjekPengawasanFactory::new()->create([
+            'status' => $status,
+            'unit_kerja' => $kode,
+        ]);
+    }
+
+    private function buatBap(ObjekPengawasan $objek, string $tanggal): void
+    {
+        BeritaAcaraPemeriksaan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'nomor_surat' => 'BAP-' . rand(1000, 9999) . '/2026',
+            'tanggal_pemeriksaan' => $tanggal,
+            'nama_pj' => 'PJ Uji',
+            'kontak_pj' => '08123456789',
+        ]);
+    }
+
+    private function buatPegawai(string $nip, ?string $noTelp): void
+    {
+        PegawaiInternal::create([
+            'nama_pegawai' => 'Pengawas ' . $nip,
+            'nip' => $nip,
+            'jenis_kelamin' => 1,
+            'tgl_lahir' => '1990-01-01',
+            'no_telp' => $noTelp,
+            'jenis_pegawai' => 'PNS',
+            'tgl_masuk' => '2015-01-01',
+        ]);
+    }
+
+    private function jobObjekId(ProcessSendWaLaporanSinkronisasi $job): ?int
+    {
+        $prop = new \ReflectionProperty($job, 'objekPengawasan');
+        $prop->setAccessible(true);
+
+        return $prop->getValue($job)->id;
+    }
+
+    /** @test */
+    public function command_mengirim_job_hanya_untuk_objek_jatuh_tempo_hari_ini()
+    {
+        $this->travelTo(\Carbon\Carbon::parse('2026-06-15 08:00:00'));
+        Queue::fake();
+
+        $objekJatuhTempo = $this->buatObjek();
+        $this->buatBap($objekJatuhTempo, '2026-06-01'); // H+14 = 2026-06-15
+
+        $objekBelumJatuhTempo = $this->buatObjek();
+        $this->buatBap($objekBelumJatuhTempo, '2026-06-05'); // H+14 = 2026-06-19
+
+        $objekSudahLapor = $this->buatObjek();
+        $this->buatBap($objekSudahLapor, '2026-06-01');
+        LaporanHasilPengawasan::create([
+            'objek_pengawasan_id' => $objekSudahLapor->id,
+            'status' => 'Menunggu Verifikasi',
+            'version' => 1,
+            'is_revision' => false,
+            'waktu_laporan' => now(),
+            'is_synced' => true,
+        ]);
+
+        $this->artisan('ppbbr:notifikasi-sinkronisasi-laporan')->assertSuccessful();
+
+        Queue::assertPushed(ProcessSendWaLaporanSinkronisasi::class, function (ProcessSendWaLaporanSinkronisasi $job) use ($objekJatuhTempo) {
+            return $this->jobObjekId($job) === $objekJatuhTempo->id;
+        });
+        Queue::assertNotPushed(function (ProcessSendWaLaporanSinkronisasi $job) use ($objekBelumJatuhTempo) {
+            return $this->jobObjekId($job) === $objekBelumJatuhTempo->id;
+        });
+        Queue::assertNotPushed(function (ProcessSendWaLaporanSinkronisasi $job) use ($objekSudahLapor) {
+            return $this->jobObjekId($job) === $objekSudahLapor->id;
+        });
+    }
+
+    /** @test */
+    public function job_tidak_mengirim_wa_bila_pengawas_tanpa_no_telp()
+    {
+        Http::fake();
+        $objek = $this->buatObjek();
+
+        $nip = 'NIP-' . rand(1000, 9999);
+        $this->buatPegawai($nip, null);
+        PengawasInspeksiLapangan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'nip' => $nip,
+        ]);
+
+        (new ProcessSendWaLaporanSinkronisasi($objek, '15-06-2026', 'SRV-1'))->handle();
+
+        Http::assertNothingSent();
+    }
+
+    /** @test */
+    public function job_mengirim_wa_ke_pengawas_dan_mencatat_log()
+    {
+        Http::fake([
+            '*' => Http::response(['status' => true, 'registered' => ['08123456789'], 'reason' => 'ok'], 200),
+        ]);
+
+        $objek = $this->buatObjek();
+        $nip = 'NIP-' . rand(1000, 9999);
+        $this->buatPegawai($nip, '08123456789');
+        PengawasInspeksiLapangan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'nip' => $nip,
+        ]);
+
+        (new ProcessSendWaLaporanSinkronisasi($objek, '15-06-2026', 'SRV-1'))->handle();
+
+        Http::assertSent(function ($request) {
+            return str_ends_with($request->url(), 'send');
+        });
+
+        $this->assertDatabaseHas('notification_logs', [
+            'channel' => 'whatsapp',
+            'status' => 'sent',
+        ]);
+    }
+}
