+<?php
+
+namespace Tests\Feature\Penjadwalan;
+
+use App\Http\Library\EnkripsiHelper;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Illuminate\Http\Request;
+use Illuminate\Support\Facades\Bus;
+use Illuminate\Support\Facades\Cache;
+use Illuminate\Support\Facades\Http;
+use Modules\Gateway\Entities\PortalDokumen;
+use Modules\Userman\Services\Master\KorespondensiCSRS\KorespondensiCRSService;
+use Tests\TestCase;
+
+/**
+ * Menguji KorespondensiCRSService::pencarianDokumen untuk jenis dokumen 'laporan':
+ * filter KM lokal, fallback gateway (filter KM), dan pesan saat gateway down.
+ */
+class LaporanPencarianDokumenCRSTest extends TestCase
+{
+    use DatabaseTransactions;
+    use EnkripsiHelper;
+
+    private KorespondensiCRSService $service;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        Cache::flush();
+        Bus::fake();
+        $this->service = new KorespondensiCRSService();
+    }
+
+    private function buatObjek(): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $kode = 'U-' . rand(100000, 999999);
+        \App\Models\UnitKerja::create([
+            'kode_unit' => $kode,
+            'nama_unit' => 'Test Unit ' . $kode,
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        return ObjekPengawasanFactory::new()->create([
+            'status' => ObjekPengawasan::LengkapiDokumen,
+            'unit_kerja' => $kode,
+        ]);
+    }
+
+    private function buatPortalDokumen(string $km, string $subject, string $refNumber): PortalDokumen
+    {
+        return PortalDokumen::create([
+            'dokumen_id' => (int) (time() . rand(100, 999)),
+            'ref_number' => $refNumber,
+            'km' => $km,
+            'subject' => $subject,
+            'type' => 'OUT',
+            'category' => null,
+            'priority' => null,
+            'security' => null,
+            'sender' => 'UPT',
+            'dokumen' => 'http://contoh.test/dokumen.pdf',
+            'letter_date' => now()->toDateString(),
+            'create_date' => now(),
+        ]);
+    }
+
+    private function cari(ObjekPengawasan $objek, array $extra = []): array
+    {
+        $request = new Request(array_merge([
+            'referensi_type' => 'objek_pengawasan',
+            'referensi_id' => $this->enkrip($objek->id),
+            'jenis_dokumen' => 'laporan',
+        ], $extra));
+
+        return $this->service->pencarianDokumen($request)->getData(true);
+    }
+
+    /** @test */
+    public function pencarian_laporan_lokal_hanya_menampilkan_km_laporan()
+    {
+        $objek = $this->buatObjek();
+
+        $pw110 = $this->buatPortalDokumen('PW 110.1', 'SPDRUT Laporan PW110', 'B.1/PSDKPLan/PW.110/IX/2026');
+        $pw120 = $this->buatPortalDokumen('PW 120.2', 'SPDRUT Laporan PW120', 'B.2/PSDKPLan/PW.120/IX/2026');
+        $this->buatPortalDokumen('KP 440.9', 'SPDRUT Bukan Laporan', 'B.3/PSDKPLan/KP.440/IX/2026');
+        $this->buatPortalDokumen('PW 110.3', 'Dokumen Biasa', 'B.4/PSDKPLan/PW.110/IX/2026');
+
+        $hasil = $this->cari($objek);
+
+        $this->assertTrue($hasil['status'], $hasil['message'] ?? '');
+        $refNumbers = array_column($hasil['data']['daftar_dokumen_csrs'], 'nomor_surat');
+        $this->assertContains($pw110->ref_number, $refNumbers);
+        $this->assertContains($pw120->ref_number, $refNumbers);
+        $this->assertCount(2, $refNumbers);
+    }
+
+    /** @test */
+    public function pencarian_laporan_saat_gateway_down_memberi_pesan_gangguan()
+    {
+        $objek = $this->buatObjek();
+        Cache::put('gateway-portal', false, 600);
+
+        $hasil = $this->cari($objek);
+
+        $this->assertTrue($hasil['data']['is_manual']);
+        $this->assertStringContainsString('Gateway CSRS gangguan', $hasil['message']);
+        $this->assertEquals([], $hasil['data']['daftar_dokumen_csrs']);
+    }
+
+    /** @test */
+    public function pencarian_laporan_fallback_gateway_menyaring_km_laporan()
+    {
+        $objek = $this->buatObjek();
+        Cache::put('gateway-portal', true, 600);
+
+        Http::fake([
+            '*' => Http::response([
+                'data' => [
+                    [
+                        'id' => 111,
+                        'km' => 'PW.110.1',
+                        'perihal' => 'Laporan PW110',
+                        'nomor_surat' => 'B.111/PSDKPLan/PW.110/IX/2026',
+                        'pengirim' => 'UPT',
+                        'tanggal_surat' => now()->toDateString(),
+                        'dokumen' => 'http://contoh.test/111.pdf',
+                    ],
+                    [
+                        'id' => 222,
+                        'km' => 'KP.440.2',
+                        'perihal' => 'Bukan Laporan',
+                        'nomor_surat' => 'B.222/PSDKPLan/KP.440/IX/2026',
+                        'pengirim' => 'UPT',
+                        'tanggal_surat' => now()->toDateString(),
+                        'dokumen' => 'http://contoh.test/222.pdf',
+                    ],
+                ],
+            ], 200),
+        ]);
+
+        $hasil = $this->cari($objek, ['keyword' => 'B.111/PSDKPLan/PW.110/IX/2026']);
+
+        $this->assertTrue($hasil['status'], $hasil['message'] ?? '');
+        $daftar = $hasil['data']['daftar_dokumen_csrs'];
+        $this->assertCount(1, $daftar);
+        $this->assertEquals('B.111/PSDKPLan/PW.110/IX/2026', $daftar[0]['nomor_surat']);
+    }
+
+    /** @test */
+    public function pencarian_laporan_berulang_kena_limit_cooldown()
+    {
+        $objek = $this->buatObjek();
+        Cache::put('gateway-portal', true, 600);
+        Http::fake(['*' => Http::response(['data' => []], 200)]);
+
+        $keyword = 'B.111/PSDKPLan/PW.110/IX/2026';
+
+        $pertama = $this->cari($objek, ['keyword' => $keyword]);
+        $this->assertEquals(1, $pertama['data']['sisa_kesempatan']);
+
+        $kedua = $this->cari($objek, ['keyword' => $keyword]);
+        $this->assertEquals(0, $kedua['data']['sisa_kesempatan']);
+
+        $ketiga = $this->cari($objek, ['keyword' => $keyword]);
+        $this->assertTrue($ketiga['data']['is_manual']);
+        $this->assertEquals(0, $ketiga['data']['sisa_kesempatan']);
+        $this->assertNotNull($ketiga['data']['cooldown_until']);
+    }
+}
