+<?php
+
+namespace Tests\Unit\PengawasanPerizinanBerusaha;
+
+use App\Http\Library\EnkripsiHelper;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenMetadata;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use App\Services\PengawasanPerizinanBerusaha\EkstrakDokumenService;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Modules\Gateway\Entities\PortalDokumen;
+use Tests\TestCase;
+
+/**
+ * Menguji EkstrakDokumenService: penyimpanan permanen metadata laporan (upsert)
+ * dan pencocokan hasil ekstraksi (NKU / Nomor ST) ke ObjekPengawasan.
+ */
+class EkstrakDokumenServiceTest extends TestCase
+{
+    use DatabaseTransactions;
+    use EnkripsiHelper;
+
+    private EkstrakDokumenService $service;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        $this->service = new EkstrakDokumenService();
+    }
+
+    private function buatObjek(): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $kode = 'U-' . rand(100000, 999999);
+        \App\Models\UnitKerja::create([
+            'kode_unit' => $kode,
+            'nama_unit' => 'Test Unit ' . $kode,
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        return ObjekPengawasanFactory::new()->create([
+            'status' => ObjekPengawasan::Selesai,
+            'unit_kerja' => $kode,
+        ]);
+    }
+
+    private function buatPortalDokumen(string $refNumber): PortalDokumen
+    {
+        return PortalDokumen::create([
+            'dokumen_id' => (int) (time() . rand(100, 999)),
+            'ref_number' => $refNumber,
+            'km' => 'KP 440.1',
+            'subject' => 'SPDRUT Surat Tugas',
+            'type' => 'OUT',
+            'category' => null,
+            'priority' => null,
+            'security' => null,
+            'sender' => 'UPT',
+            'dokumen' => 'http://contoh.test/dokumen.pdf',
+            'letter_date' => now()->toDateString(),
+            'create_date' => now(),
+        ]);
+    }
+
+    /** @test */
+    public function simpan_permanen_menyimpan_metadata_jenis_laporan()
+    {
+        $objek = $this->buatObjek();
+        $portal = $this->buatPortalDokumen('B.1/PSDKPLan/PW.110/IX/2026');
+
+        $this->service->simpanPermanen([
+            [
+                'jenis_item' => 'nomor_st',
+                'nilai' => 'B.1/PSDKPLan/KP.440/IX/2026',
+                'objek_pengawasan_id' => $this->enkrip($objek->id),
+            ],
+        ], $portal->id, 'storage/ekstrak/laporan.pdf', 'laporan');
+
+        $meta = DokumenMetadata::where('portal_dokumen_id', $portal->id)->first();
+
+        $this->assertNotNull($meta);
+        $this->assertEquals('laporan', $meta->jenis_dokumen);
+        $this->assertEquals('nomor_st', $meta->jenis_item);
+        $this->assertEquals($objek->id, $meta->objek_pengawasan_id);
+    }
+
+    /** @test */
+    public function simpan_permanen_melakukan_upsert_tanpa_duplikasi()
+    {
+        $portal = $this->buatPortalDokumen('B.2/PSDKPLan/PW.110/IX/2026');
+        $item = ['jenis_item' => 'nomor_st', 'nilai' => 'B.2/PSDKPLan/KP.440/IX/2026'];
+
+        $this->service->simpanPermanen([$item], $portal->id, 'storage/ekstrak/laporan.pdf', 'laporan');
+        $this->service->simpanPermanen([$item], $portal->id, 'storage/ekstrak/laporan.pdf', 'laporan');
+
+        $this->assertEquals(1, DokumenMetadata::where('portal_dokumen_id', $portal->id)->count());
+    }
+
+    /** @test */
+    public function cocokkan_ke_objek_mencocokkan_nku()
+    {
+        $objek = $this->buatObjek();
+
+        $hasil = $this->service->cocokkanKeObjek([
+            ['jenis_item' => 'nku', 'nilai' => $objek->no_kode_proyek],
+        ], null, $objek->id);
+
+        $this->assertCount(1, $hasil);
+        $this->assertTrue($hasil[0]['is_checked']);
+        $this->assertTrue($hasil[0]['is_current']);
+        $this->assertEquals('valid', $hasil[0]['status']);
+        $this->assertEquals($this->enkrip($objek->id), $hasil[0]['objek_pengawasan_id']);
+    }
+
+    /** @test */
+    public function cocokkan_ke_objek_mencocokkan_nomor_st_dari_manual_nomor_surat()
+    {
+        $objek = $this->buatObjek();
+        $nomorSt = 'B.3/PSDKPLan/KP.440/IX/2026';
+
+        DokumenPenjadwalan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'jenis_dokumen' => 'surat_tugas',
+            'manual_nomor_surat' => $nomorSt,
+        ]);
+
+        $hasil = $this->service->cocokkanKeObjek([
+            ['jenis_item' => 'nomor_st', 'nilai' => $nomorSt],
+        ]);
+
+        $this->assertCount(1, $hasil);
+        $this->assertEquals('valid', $hasil[0]['status']);
+        $this->assertEquals($objek->id, $this->dekrip($hasil[0]['objek_pengawasan_id']));
+        $this->assertStringContainsString('Nomor ST', $hasil[0]['keterangan']);
+    }
+
+    /** @test */
+    public function cocokkan_ke_objek_mencocokkan_nomor_st_dari_ref_number_portal_dokumen()
+    {
+        $objek = $this->buatObjek();
+        $nomorSt = 'B.4/PSDKPLan/KP.440/IX/2026';
+        $portal = $this->buatPortalDokumen($nomorSt);
+
+        DokumenPenjadwalan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'jenis_dokumen' => 'surat_tugas',
+            'portal_dokumen_id' => $portal->id,
+        ]);
+
+        $hasil = $this->service->cocokkanKeObjek([
+            ['jenis_item' => 'nomor_st', 'nilai' => $nomorSt],
+        ]);
+
+        $this->assertCount(1, $hasil);
+        $this->assertEquals('valid', $hasil[0]['status']);
+        $this->assertEquals($objek->id, $this->dekrip($hasil[0]['objek_pengawasan_id']));
+    }
+
+    /** @test */
+    public function cocokkan_ke_objek_mengembalikan_invalid_bila_tidak_ditemukan()
+    {
+        $hasil = $this->service->cocokkanKeObjek([
+            ['jenis_item' => 'nomor_st', 'nilai' => 'B.999/PSDKPLan/KP.440/IX/2026'],
+        ]);
+
+        $this->assertCount(1, $hasil);
+        $this->assertFalse($hasil[0]['is_checked']);
+        $this->assertEquals('invalid', $hasil[0]['status']);
+        $this->assertNull($hasil[0]['objek_pengawasan_id']);
+    }
+}
