+use Spatie\Permission\Models\Role;
+use Spatie\Permission\PermissionRegistrar;
+use Tests\TestCase;
+
+class LaporanHasilPengawasanServiceTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    private LaporanHasilPengawasanService $service;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        $this->service = new LaporanHasilPengawasanService();
+        $this->loginOperator();
+    }
+
+    private function loginOperator(string $role = 'Operator UPT WasRisk'): void
+    {
+        $roleModel = Role::firstOrCreate(['name' => $role, 'guard_name' => 'api']);
+
+        // Cerminkan seeder: permission tulis hanya untuk role Operator WasRisk
+        if (in_array($role, ['Operator UPT WasRisk', 'Operator Pusat WasRisk'])) {
+            $perms = [];
+            foreach (AkunPenjadwalanLhpSeeder::WRITE_PERMISSIONS as $name) {
+                $perms[] = Permission::findOrCreate($name, 'api');
+            }
+            $roleModel->givePermissionTo($perms);
+            app(PermissionRegistrar::class)->forgetCachedPermissions();
+        }
+
+        $user = User::create([
+            'username' => 'test_' . uniqid(),
+            'password' => bcrypt('password'),
+        ]);
+        $user->assignRole($role);
+
+        $pegawai = PegawaiInternal::create([
+            'nip' => 'NIP' . rand(10000, 99999),
+            'nama_pegawai' => 'Pegawai Uji',
+            'user_id' => $user->id,
+        ]);
+
+        $user->pegint_id = $pegawai->nip;
+        $user->save();
+
+        Auth::login($user);
+    }
+
+    private function buatUnitKerja(): string
+    {
+        $kode = 'U-' . rand(100000, 999999);
+
+        \App\Models\UnitKerja::create([
+            'kode_unit' => $kode,
+            'nama_unit' => 'Test Unit ' . $kode,
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        return $kode;
+    }
+
+    private function buatObjek(array $attrs = []): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        return ObjekPengawasanFactory::new()->create(array_merge([
+            'status' => ObjekPengawasan::Selesai,
+            'unit_kerja' => $this->buatUnitKerja(),
+        ], $attrs));
+    }
+
+    private function requestSimpan(ObjekPengawasan $objek, array $extra = []): Request
+    {
+        return new Request(array_merge([
+            'jenis_dokumen' => 'laporan',
+            'objek_pengawasan_ids' => [$this->service->enkrip($objek->id)],
+            'dokumen_pendukung' => ['https://contoh.test/nota.pdf'],
+        ], $extra));
+    }
+
+    private function buatBap(ObjekPengawasan $objek, string $tanggal): void
+    {
+        BeritaAcaraPemeriksaan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'nomor_surat' => 'BAP-' . rand(1000, 9999) . '/2026',
+            'tanggal_pemeriksaan' => $tanggal,
+            'nama_pj' => 'PJ Uji',
+            'kontak_pj' => '08123456789',
+        ]);
+    }
+
+    /** @test */
+    public function simpan_laporan_pertama_membuat_version_1_dan_status_menunggu_verifikasi()
+    {
+        $objek = $this->buatObjek();
+
+        $response = $this->service->simpanLaporan($this->requestSimpan($objek));
+        $data = $response->getData(true);
+
+        $this->assertTrue($data['status'], $data['message'] ?? '');
+
+        $laporan = LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)->first();
+        $this->assertNotNull($laporan);
+        $this->assertEquals(1, $laporan->version);
+        $this->assertFalse($laporan->is_revision);
+        $this->assertTrue((bool) $laporan->is_synced);
+        $this->assertEquals('Menunggu Verifikasi', $laporan->status);
+        $this->assertNotNull($laporan->deadline_sinkronisasi);
+        $this->assertEquals(['https://contoh.test/nota.pdf'], $laporan->url_dokumen);
+    }
+
+    /** @test */
+    public function reupload_menaikkan_version_dan_menyimpan_histori()
+    {
+        $objek = $this->buatObjek();
+
+        $this->service->simpanLaporan($this->requestSimpan($objek));
+
+        // Reupload (masih dalam batas H+14)
+        $response = $this->service->simpanLaporan($this->requestSimpan($objek, [
+            'dokumen_pendukung' => ['https://contoh.test/nota-revisi.pdf'],
+        ]));
+        $data = $response->getData(true);
+
+        $this->assertTrue($data['status'], $data['message'] ?? '');
+
+        $laporan = LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)->first();
+        $this->assertEquals(2, $laporan->version);
+        $this->assertTrue($laporan->is_revision);
+        $this->assertEquals(1, $laporan->riwayat()->count());
+        $this->assertEquals(1, $laporan->riwayat()->first()->version);
+    }
+
+    /** @test */
+    public function reupload_ditolak_setelah_batas_h14()
+    {
+        $objek = $this->buatObjek();
+
+        // Buat laporan dengan deadline yang sudah lewat
+        LaporanHasilPengawasan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'status' => 'Menunggu Verifikasi',
+            'version' => 1,
+            'is_synced' => true,
+            'waktu_laporan' => now()->subDays(30),
+            'deadline_sinkronisasi' => now()->subDays(16)->toDateString(),
+        ]);
+
+        $response = $this->service->simpanLaporan($this->requestSimpan($objek));
+        $data = $response->getData(true);
+
+        $this->assertFalse($data['status']);
+        $this->assertStringContainsString('H+14', $data['message']);
+    }
+
+    /** @test */
+    public function detail_laporan_mengembalikan_field_utama()
+    {
+        $objek = $this->buatObjek();
+        $this->service->simpanLaporan($this->requestSimpan($objek));
+
+        $detail = $this->service->detailLaporan($objek->id);
+
+        $this->assertIsArray($detail);
+        $this->assertEquals('Menunggu Verifikasi', $detail['status']);
+        $this->assertEquals(1, $detail['version']);
+        $this->assertTrue($detail['can_upload_laporan']);
+        $this->assertArrayHasKey('dokumen_pendukung', $detail);
+        $this->assertArrayHasKey('histori', $detail);
+    }
+
+    /** @test */
+    public function detail_laporan_null_bila_belum_ada()
+    {
+        $objek = $this->buatObjek();
+
+        $this->assertNull($this->service->detailLaporan($objek->id));
+    }
+
+    /** @test */
+    public function cari_dokumen_relevan_kosong_untuk_nku_tidak_dikenal()
+    {
+        $this->assertEquals([], $this->service->cariDokumenRelevan(['999999-9999-9999-9999-999']));
+    }
+
+    /** @test */
+    public function simpan_laporan_bulk_ke_banyak_objek()
+    {
+        $objekA = $this->buatObjek();
+        $objekB = $this->buatObjek();
+
+        $response = $this->service->simpanLaporan(new Request([
+            'jenis_dokumen' => 'laporan',
+            'objek_pengawasan_ids' => [
+                $this->service->enkrip($objekA->id),
+                $this->service->enkrip($objekB->id),
+            ],
+            'dokumen_pendukung' => ['https://contoh.test/nota.pdf'],
+        ]));
+
+        $data = $response->getData(true);
+
+        $this->assertTrue($data['status'], $data['message'] ?? '');
+        $this->assertCount(2, $data['data']);
+        $this->assertEquals(2, LaporanHasilPengawasan::whereIn('objek_pengawasan_id', [$objekA->id, $objekB->id])->count());
+    }
+
+    /** @test */
+    public function dokumen_pendukung_dapat_berupa_string_dipisah_koma()
+    {
+        $objek = $this->buatObjek();
+
+        $this->service->simpanLaporan($this->requestSimpan($objek, [
+            'dokumen_pendukung' => 'https://a.test/1.pdf, https://a.test/2.pdf',
+        ]));
+
+        $laporan = LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)->first();
+
+        $this->assertEquals(['https://a.test/1.pdf', 'https://a.test/2.pdf'], $laporan->url_dokumen);
+    }
+
+    /** @test */
+    public function hitung_deadline_memilih_h14_bila_lebih_cepat()
+    {
+        $objek = $this->buatObjek();
+        $this->buatBap($objek, '2026-01-10'); // H+14 = 2026-01-24, kuartal terdekat = 2026-04-02
+
+        $this->assertEquals('2026-01-24', $this->service->hitungDeadline($objek->id));
+    }
+
+    /** @test */
+    public function hitung_deadline_memilih_tanggal_kuartal_bila_lebih_cepat()
+    {
+        $objek = $this->buatObjek();
+        $this->buatBap($objek, '2026-03-25'); // H+14 = 2026-04-08, kuartal terdekat = 2026-04-02
+
+        $this->assertEquals('2026-04-02', $this->service->hitungDeadline($objek->id));
+    }
+
+    /** @test */
+    public function can_upload_laporan_menyesuaikan_deadline()
+    {
+        $objek = $this->buatObjek();
+        $this->service->simpanLaporan($this->requestSimpan($objek));
+
+        $laporan = LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)->first();
+        $this->assertTrue($this->service->canUploadLaporan($laporan));
