+        $this->assertFalse($this->service->canUploadLaporan($laporan->fresh()));
+    }
+
+    /** @test */
+    public function cari_dokumen_relevan_positif_berdasarkan_nku()
+    {
+        $objek = $this->buatObjek();
+        $nku = $objek->no_kode_proyek;
