+
+    /** @test */
+    public function simpan_laporan_rollback_total_bila_satu_objek_lewat_h14()
+    {
+        $objekA = $this->buatObjek();
+        $objekB = $this->buatObjek();
+        $this->service->simpanLaporan($this->requestSimpan($objekB));
+
+        LaporanHasilPengawasan::where('objek_pengawasan_id', $objekB->id)
