+            'jenis_dokumen' => 'laporan',
+            'objek_pengawasan_ids' => [
+                $this->service->enkrip($objekA->id),
+                $this->service->enkrip($objekB->id),
+            ],
+            'dokumen_pendukung' => ['https://contoh.test/nota.pdf'],
