+        $this->assertFalse($data['status']);
+        $this->assertEquals(0, LaporanHasilPengawasan::where('objek_pengawasan_id', $objekA->id)->count());
+        $this->assertEquals(1, LaporanHasilPengawasan::where('objek_pengawasan_id', $objekB->id)->first()->version);
