+
+    /** @test */
+    public function guard_batas_reupload_melempar_exception_bila_lewat_h14()
+    {
+        $objek = $this->buatObjek();
+        $this->service->simpanLaporan($this->requestSimpan($objek));
+
+        $laporan = LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)->first();
