+
+        $this->service->guardBatasReupload($laporan->fresh());
+    }
+
+    /** @test */
+    public function simpan_laporan_menyimpan_portal_dokumen_id()
+    {
+        $objek = $this->buatObjek();
+        $portal = PortalDokumen::create([
+            'dokumen_id' => (int) (time() . rand(100, 999)),
+            'ref_number' => 'B.5/PSDKPLan/PW.110/IX/2026',
+            'subject' => 'SPDRUT Nota Dinas',
+            'sender' => 'UPT',
+        ]);
+
+        $response = $this->service->simpanLaporan($this->requestSimpan($objek, [
+            'portal_dokumen_id' => $this->service->enkrip($portal->id),
+        ]));
+        $data = $response->getData(true);
+
+        $this->assertTrue($data['status'], $data['message'] ?? '');
+        $this->assertEquals(
+            $portal->id,
+            LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)->first()->portal_dokumen_id
+        );
+    }
+
+    /** @test */
+    public function simpan_laporan_melewati_objek_yang_tidak_ditemukan()
+    {
+        $objek = $this->buatObjek();
+
+        $response = $this->service->simpanLaporan(new Request([
+            'jenis_dokumen' => 'laporan',
+            'objek_pengawasan_ids' => [
+                $this->service->enkrip(99999999),
+                $this->service->enkrip($objek->id),
+            ],
+            'dokumen_pendukung' => ['https://contoh.test/nota.pdf'],
+        ]));
+        $data = $response->getData(true);
+
+        $this->assertTrue($data['status'], $data['message'] ?? '');
+        $this->assertCount(1, $data['data']);
+        $this->assertNotNull(LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)->first());
+    }
+
+    /** @test */
+    public function simpan_laporan_ditolak_bila_tanpa_login()
+    {
+        Auth::logout();
+        $objek = $this->buatObjek();
+
+        $response = $this->service->simpanLaporan($this->requestSimpan($objek));
+        $data = $response->getData(true);
+
+        $this->assertFalse($data['status']);
+        $this->assertStringContainsString('tidak memiliki akses', $data['message']);
+    }
+
+    /** @test */
+    public function simpan_laporan_ditolak_untuk_role_pengawas()
+    {
+        $this->loginOperator('Pengawas Perikanan JF');
+        $objek = $this->buatObjek();
+
+        $response = $this->service->simpanLaporan($this->requestSimpan($objek));
+        $data = $response->getData(true);
+
+        $this->assertFalse($data['status']);
+        $this->assertStringContainsString('tidak memiliki akses', $data['message']);
+    }
+}
