@@ -0,0 +1,175 @@
+<?php
+
+namespace Tests\Unit\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use App\Http\Requests\PengawasanPerizinanBerusaha\Penjadwalan\EkstrakDokumenRequest;
+use App\Http\Requests\PengawasanPerizinanBerusaha\Penjadwalan\SimpanDokumenRequest;
+use Illuminate\Support\Facades\Validator;
+use Modules\Userman\Http\Requests\Master\KorespondensiCRS\PencarianDokumenRequest;
+use Tests\TestCase;
+
+/**
+ * Menguji whitelist jenis dokumen 'laporan' + validasi format nomor surat (5 tahap)
+ * pada request Pencarian/Ekstrak/Simpan dokumen.
+ */
+class LaporanDokumenRequestValidationTest extends TestCase
+{
+    private function validasiPencarian(array $data): \Illuminate\Validation\Validator
+    {
+        $request = PencarianDokumenRequest::create('/pencarian-dokumen', 'GET', $data);
+        $validator = Validator::make($data, $request->rules());
+        $request->withValidator($validator);
+        $validator->passes();
+
+        return $validator;
+    }
+
+    private function validasiEkstrak(array $data): \Illuminate\Validation\Validator
+    {
+        $request = EkstrakDokumenRequest::create('/ekstrak-dokumen', 'POST', $data);
+        $validator = Validator::make($data, $request->rules());
+        $request->withValidator($validator);
+        $validator->passes();
+
+        return $validator;
+    }
+
+    private function validasiSimpan(array $data): \Illuminate\Validation\Validator
+    {
+        $request = SimpanDokumenRequest::create('/simpan-dokumen', 'POST', $data);
+        $validator = Validator::make($data, $request->rules());
+        $request->withValidator($validator);
+        $validator->passes();
+
+        return $validator;
+    }
+
+    private function pencarianLaporan(array $extra = []): array
+    {
+        return array_merge([
+            'referensi_type' => 'objek_pengawasan',
+            'referensi_id' => 'id-terenkripsi',
+            'jenis_dokumen' => 'laporan',
+        ], $extra);
+    }
+
+    /** @test */
+    public function pencarian_dokumen_menerima_jenis_laporan()
+    {
+        $validator = $this->validasiPencarian($this->pencarianLaporan());
+
+        $this->assertFalse($validator->errors()->has('jenis_dokumen'));
+    }
+
+    /** @test */
+    public function pencarian_dokumen_menolak_jenis_tidak_dikenal()
+    {
+        $validator = $this->validasiPencarian($this->pencarianLaporan(['jenis_dokumen' => 'jenis_ngawur']));
+
+        $this->assertTrue($validator->errors()->has('jenis_dokumen'));
+    }
+
+    /**
+     * @test
+     * @dataProvider kmLaporanValidProvider
+     */
+    public function keyword_laporan_valid_untuk_km_yang_didukung(string $keyword)
+    {
+        $validator = $this->validasiPencarian($this->pencarianLaporan(['keyword' => $keyword]));
+
+        $this->assertFalse($validator->errors()->has('keyword'), $validator->errors()->first('keyword'));
+    }
+
+    public static function kmLaporanValidProvider(): array
+    {
+        return [
+            'PW.110 titik' => ['B.18413/PSDKPLan.1/PW.110/IX/2026'],
+            'PW 110 spasi' => ['B.18413/PSDKPLan.1/PW 110/IX/2026'],
+            'PW.120' => ['B.18413/PSDKPLan.1/PW.120/X/2026'],
+            'PW.130' => ['B.18413/PSDKPLan.1/PW.130/XII/2026'],
+            'PW.240' => ['B.18413/PSDKPLan.1/PW.240/I/2026'],
+        ];
+    }
+
+    /** @test */
+    public function keyword_laporan_tanpa_bulan_romawi_ditolak()
+    {
+        $validator = $this->validasiPencarian($this->pencarianLaporan([
+            'keyword' => 'B.18413/PSDKPLan.1/PW.110/2026',
+        ]));
+
+        $this->assertTrue($validator->errors()->has('keyword'));
+    }
+
+    /** @test */
+    public function keyword_laporan_dengan_km_bukan_laporan_ditolak()
+    {
+        $validator = $this->validasiPencarian($this->pencarianLaporan([
+            'keyword' => 'B.18413/PSDKPLan.1/KP.440/IX/2026',
+        ]));
+
+        $this->assertTrue($validator->errors()->has('keyword'));
+    }
+
+    /** @test */
+    public function keyword_laporan_terlalu_pendek_ditolak()
+    {
+        $validator = $this->validasiPencarian($this->pencarianLaporan(['keyword' => 'PW 110']));
+
+        $this->assertTrue($validator->errors()->has('keyword'));
+    }
+
+    /** @test */
+    public function keyword_laporan_kurang_garis_miring_ditolak()
+    {
+        $validator = $this->validasiPencarian($this->pencarianLaporan([
+            'keyword' => 'PW.110/IX/2026',
+        ]));
+
+        $this->assertTrue($validator->errors()->has('keyword'));
+    }
+
+    /** @test */
+    public function ekstrak_dokumen_menerima_jenis_laporan()
+    {
+        $validator = $this->validasiEkstrak([
+            'dokumen_id' => 'id-terenkripsi',
+            'jenis_dokumen' => 'laporan',
+        ]);
+
+        $this->assertFalse($validator->errors()->has('jenis_dokumen'));
+    }
+
+    /** @test */
+    public function ekstrak_dokumen_menolak_jenis_yang_tidak_mendukung_ekstraksi()
+    {
+        $validator = $this->validasiEkstrak([
+            'dokumen_id' => 'id-terenkripsi',
+            'jenis_dokumen' => 'stkl',
+        ]);
+
+        $this->assertTrue($validator->errors()->has('jenis_dokumen'));
+    }
+
+    /** @test */
+    public function simpan_dokumen_menerima_jenis_laporan()
+    {
+        $validator = $this->validasiSimpan([
+            'jenis_dokumen' => 'laporan',
+            'objek_pengawasan_ids' => ['id-terenkripsi'],
+        ]);
+
+        $this->assertFalse($validator->errors()->has('jenis_dokumen'));
+    }
+
+    /** @test */
+    public function simpan_dokumen_menolak_jenis_tidak_dikenal()
+    {
+        $validator = $this->validasiSimpan([
+            'jenis_dokumen' => 'jenis_ngawur',
+            'objek_pengawasan_ids' => ['id-terenkripsi'],
+        ]);
+
+        $this->assertTrue($validator->errors()->has('jenis_dokumen'));
+    }
+}
