+<?php
+
+namespace Tests\Unit\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use Database\Seeders\PPBBR\AkunPenjadwalanLhpSeeder;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Spatie\Permission\Models\Role;
+use Tests\TestCase;
+
+/**
+ * Memverifikasi AkunPenjadwalanLhpSeeder mendaftarkan permission
+ * berdasarkan route name terbaru dan memberikannya ke role yang tepat.
+ */
+class PermissionPenjadwalanLhpSeederTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    /** @test */
+    public function seeder_mendaftarkan_permission_berdasarkan_route_name()
+    {
+        $this->seed(AkunPenjadwalanLhpSeeder::class);
+
+        foreach (AkunPenjadwalanLhpSeeder::WRITE_PERMISSIONS as $name) {
+            $this->assertDatabaseHas('permissions', [
+                'name' => $name,
+                'guard_name' => 'api',
+            ]);
+        }
+
+        $this->assertDatabaseHas('permissions', ['name' => 'ppbbr.hasil-inspeksi.index']);
+    }
+
+    /** @test */
+    public function seeder_memberikan_permission_tulis_ke_role_operator()
+    {
+        $this->seed(AkunPenjadwalanLhpSeeder::class);
+
+        foreach (['Operator UPT WasRisk', 'Operator Pusat WasRisk'] as $roleName) {
+            $role = Role::findByName($roleName, 'api');
+            foreach (AkunPenjadwalanLhpSeeder::WRITE_PERMISSIONS as $name) {
+                $this->assertTrue(
+                    $role->hasPermissionTo($name),
+                    "Role {$roleName} seharusnya punya permission {$name}"
+                );
+            }
+        }
+    }
+
+    /** @test */
+    public function seeder_sync_seluruh_permission_ke_super_role()
+    {
+        $this->seed(AkunPenjadwalanLhpSeeder::class);
+
+        foreach (['Superuser', 'Superadmin'] as $roleName) {
+            $role = Role::findByName($roleName, 'api');
+            $this->assertTrue($role->hasPermissionTo('ppbbr.penjadwalan.dokumen.store'));
+            $this->assertTrue($role->hasPermissionTo('ppbbr.hasil-inspeksi.index'));
+        }
+    }
+}
diff --git a/tests/Unit/PengawasanPerizinanBerusaha/PenjadwalanServiceFlowTest.php b/tests/Unit/PengawasanPerizinanBerusaha/PenjadwalanServiceFlowTest.php
