@@ -0,0 +1,499 @@
+<?php
+
+namespace Tests\Unit\PengawasanPerizinanBerusaha;
+
+use App\Jobs\PengawasanPerizinanBerusaha\NotifikasiPersetujuanPenjadwalanMandiri;
+use App\Jobs\ProcessSendEmailKirimPenjadwalanInspeksi;
+use App\Jobs\ProcessSendWaKirimPenjadwalanInspeksi;
+use App\Models\PegawaiInternal;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenMetadata;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use App\Models\UnitKerja;
+use App\Models\User;
+use App\Services\PengawasanPerizinanBerusaha\PenjadwalanService;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Illuminate\Http\Request;
+use Illuminate\Support\Facades\Auth;
+use Illuminate\Support\Facades\Queue;
+use Database\Seeders\PPBBR\AkunPenjadwalanLhpSeeder;
+use Modules\Gateway\Entities\PortalDokumen;
+use Modules\Userman\Entities\Master\PortalKorespondensiCRS\Category;
+use Modules\Userman\Entities\Master\PortalKorespondensiCRS\DokumenCategory;
+use Spatie\Permission\Models\Permission;
+use Spatie\Permission\Models\Role;
+use Spatie\Permission\PermissionRegistrar;
+use Tests\TestCase;
+
+/**
+ * Menguji alur PenjadwalanService yang belum tercakup:
+ * simpanDokumen (non-laporan/bulk/STWAP/H-1), unggahDokumen (H-1),
+ * ringkasanStatus, dokumenExisting, pilihDokumenCsrs,
+ * inputPengajuanKeOSS, notifikasiInputPengawas, persetujuanPenjadwalanMandiri.
+ */
+class PenjadwalanServiceFlowTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    private PenjadwalanService $service;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        Queue::fake();
+        $this->service = new PenjadwalanService();
+        $this->loginUser($this->buatUnit());
+    }
+
+    private function buatUnit(): UnitKerja
+    {
+        return UnitKerja::create([
+            'kode_unit' => 'U-' . rand(100000, 999999),
+            'nama_unit' => 'Unit Uji ' . uniqid(),
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+    }
+
+    private function buatObjek(array $attrs = []): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $unit = $attrs['unit_kerja'] ?? null;
+        if (!$unit) {
+            $unit = $this->buatUnit()->kode_unit;
+        }
+
+        return ObjekPengawasanFactory::new()->create(array_merge([
+            'status' => ObjekPengawasan::PersetujuanDisetujuiOSS,
+            'unit_kerja' => $unit,
+            'jadwal' => now()->addMonth()->toDateString(),
+        ], $attrs));
+    }
+
+    private function buatPortalDokumen(array $attrs = []): PortalDokumen
+    {
+        return PortalDokumen::create(array_merge([
+            'dokumen_id' => (int) (time() . rand(100, 999)),
+            'ref_number' => 'B.1/PSDKPLan/PW.110/IX/2026',
+            'km' => 'PW 110.1',
+            'subject' => 'SPDRUT Dokumen',
+            'type' => 'OUT',
+            'sender' => 'UPT',
+            'dokumen' => 'http://contoh.test/dokumen.pdf',
+            'letter_date' => now()->toDateString(),
+            'date' => now()->toDateString(),
+            'create_date' => now(),
+        ], $attrs));
+    }
+
+    private function loginUser(UnitKerja $unit, string $role = 'Operator UPT WasRisk'): User
+    {
+        $roleModel = Role::firstOrCreate(['name' => $role, 'guard_name' => 'api']);
+
+        // Cerminkan seeder: permission tulis hanya untuk role Operator WasRisk
+        if (in_array($role, ['Operator UPT WasRisk', 'Operator Pusat WasRisk'])) {
+            $perms = [];
+            foreach (AkunPenjadwalanLhpSeeder::WRITE_PERMISSIONS as $name) {
+                $perms[] = Permission::findOrCreate($name, 'api');
+            }
+            $roleModel->givePermissionTo($perms);
+            app(PermissionRegistrar::class)->forgetCachedPermissions();
+        }
+
+        $user = User::create([
+            'username' => 'test_' . uniqid(),
+            'password' => bcrypt('password'),
+        ]);
+        $user->assignRole($role);
+
+        $pegawai = PegawaiInternal::create([
+            'nip' => 'NIP' . rand(10000, 99999),
+            'nama_pegawai' => 'Pegawai Uji',
+            'unit_kerja_id' => $unit->kode_unit,
+            'user_id' => $user->id,
+        ]);
+
+        $user->pegint_id = $pegawai->nip;
+        $user->save();
+
+        Auth::login($user);
+
+        return $user;
+    }
+
+    private function requestSimpan(array $objekIds, string $jenis, array $extra = []): Request
+    {
+        return new Request(array_merge([
+            'jenis_dokumen' => $jenis,
+            'objek_pengawasan_ids' => array_map(fn ($id) => $this->service->enkrip($id), $objekIds),
+        ], $extra));
+    }
+
+    /** @test */
+    public function simpan_dokumen_bulk_menyimpan_ke_banyak_objek()
+    {
+        $a = $this->buatObjek();
+        $b = $this->buatObjek();
+
+        $response = $this->service->simpanDokumen($this->requestSimpan([$a->id, $b->id], 'notula', [
+            'manual_nomor_surat' => 'ND-001/2026',
+        ]));
+        $data = $response->getData(true);
+
+        $this->assertTrue($data['status'], $data['message'] ?? '');
+        $this->assertEquals(2, DokumenPenjadwalan::where('jenis_dokumen', 'notula')
+            ->whereIn('objek_pengawasan_id', [$a->id, $b->id])->count());
+    }
+
+    /** @test */
+    public function simpan_dokumen_surat_tugas_menandai_kategori_stwap()
+    {
+        $objek = $this->buatObjek();
+        foreach (['notula', 'surat_pemberitahuan_oss', 'stkl'] as $jenis) {
+            DokumenPenjadwalan::create([
+                'objek_pengawasan_id' => $objek->id,
+                'jenis_dokumen' => $jenis,
+                'file_path' => "storage/uat/{$jenis}.pdf",
+            ]);
+        }
+
+        $category = Category::create(['kode' => 'STWAP', 'keterangan' => 'Surat Tugas Wajib Ambil PDF']);
+        $portal = $this->buatPortalDokumen();
+
+        $response = $this->service->simpanDokumen($this->requestSimpan([$objek->id], 'surat_tugas', [
+            'portal_dokumen_id' => $this->service->enkrip($portal->id),
+        ]));
+        $data = $response->getData(true);
+
+        $this->assertTrue($data['status'], $data['message'] ?? '');
+        $this->assertDatabaseHas('portal_dokumen_category', [
+            'dokumen_id' => $portal->id,
+            'category_id' => $category->id,
+        ]);
+        $this->assertEquals('korespondensi', $objek->fresh()->surat_tugas);
+    }
+
+    /** @test */
+    public function simpan_dokumen_ditolak_setelah_batas_h1()
+    {
+        $objek = $this->buatObjek(['jadwal' => now()->toDateString()]);
+
+        $response = $this->service->simpanDokumen($this->requestSimpan([$objek->id], 'notula'));
+        $data = $response->getData(true);
+
+        $this->assertFalse($data['status']);
+        $this->assertStringContainsString('Batas waktu unggah/ubah dokumen sudah berakhir', $data['message']);
+    }
+
+    /** @test */
+    public function unggah_dokumen_ditolak_setelah_batas_h1()
+    {
+        $objek = $this->buatObjek(['jadwal' => now()->toDateString()]);
+
+        $request = new Request([
+            'jenis_dokumen' => 'notula',
+            'objek_pengawasan_id' => $this->service->enkrip($objek->id),
+        ]);
+
+        $response = $this->service->unggahDokumen($request);
+        $data = $response->getData(true);
+
+        $this->assertFalse($data['status']);
+        $this->assertEquals('Batas waktu unggah/ubah dokumen sudah berakhir. Dokumen hanya dapat diunggah maksimal H-1.', $data['message']);
+    }
+
+    /** @test */
+    public function ringkasan_status_menghitung_sesuai_bucket()
+    {
+        $unit = $this->buatUnit();
+        $this->loginUser($unit);
+
+        $this->buatObjek(['unit_kerja' => $unit->kode_unit, 'status' => ObjekPengawasan::PersetujuanTanggalOSS]);
+        $this->buatObjek(['unit_kerja' => $unit->kode_unit, 'status' => ObjekPengawasan::PersetujuanDitolakOSS]);
+        $this->buatObjek(['unit_kerja' => $unit->kode_unit, 'status' => ObjekPengawasan::PersetujuanTanggalOperator]);
+        $this->buatObjek(['unit_kerja' => $unit->kode_unit, 'status' => ObjekPengawasan::PersetujuanDisetujuiOSS]);
+        $this->buatObjek(['unit_kerja' => $unit->kode_unit, 'status' => ObjekPengawasan::BelumUploadST]);
+
+        $response = $this->service->ringkasanStatus(new Request([]));
+        $data = $response->getData(true);
+
+        $this->assertTrue($data['status'], $data['message'] ?? '');
+        $this->assertEquals(5, $data['data']['proyek']);
+        $this->assertEquals(1, $data['data']['belum_ditugaskan']);
+        $this->assertEquals(2, $data['data']['dijadwalkan']);
+        $this->assertEquals(2, $data['data']['ditugaskan']);
+    }
+
+    /** @test */
+    public function dokumen_existing_mengembalikan_detail_dokumen()
+    {
+        $objek = $this->buatObjek();
+        DokumenPenjadwalan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'jenis_dokumen' => 'notula',
+            'file_path' => 'storage/uat/notula.pdf',
+            'manual_nomor_surat' => 'ND-001/2026',
+        ]);
+        DokumenMetadata::create([
+            'file_path' => 'storage/uat/notula.pdf',
+            'jenis_dokumen' => 'notula',
+            'jenis_item' => 'nku',
