+<?php
+
+namespace Tests\Unit\PengawasanPerizinanBerusaha;
+
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use App\Services\PengawasanPerizinanBerusaha\PenjadwalanService;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Illuminate\Support\Facades\Queue;
+use Tests\TestCase;
+
+/**
+ * Menguji validasi urutan upload perdana: Notula -> SP (OSS/UPT) -> STKL -> Surat Tugas.
+ */
+class PenjadwalanUrutanUploadTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    private PenjadwalanService $service;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        $this->service = new PenjadwalanService();
+        Queue::fake();
+    }
+
+    private function buatUnitKerja(): string
+    {
+        $kode = 'U-' . rand(100000, 999999);
+
+        \App\Models\UnitKerja::create([
+            'kode_unit' => $kode,
+            'nama_unit' => 'Test Unit ' . $kode,
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        return $kode;
+    }
+
+    private function buatObjek(string $status): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        return ObjekPengawasanFactory::new()->create([
+            'status' => $status,
+            'unit_kerja' => $this->buatUnitKerja(),
+        ]);
+    }
+
+    private function tambahDokumen(ObjekPengawasan $objek, string $jenis): void
+    {
+        DokumenPenjadwalan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'jenis_dokumen' => $jenis,
+            'file_path' => 'storage/uat/' . $jenis . '.pdf',
+        ]);
+    }
+
+    private function validasi(ObjekPengawasan $objek, string $jenis): void
+    {
+        $ref = new \ReflectionMethod(PenjadwalanService::class, 'validasiUrutanUpload');
+        $ref->setAccessible(true);
+        $ref->invoke($this->service, $objek, $jenis);
+    }
+
+    /** @test */
+    public function stkl_tanpa_notula_ditolak()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS);
+
+        $this->expectException(\Exception::class);
+        $this->expectExceptionMessage('Tidak dapat menyimpan STKL. Silakan unggah Notula');
+
+        $this->validasi($objek, 'stkl');
+    }
+
+    /** @test */
+    public function stkl_tanpa_sp_ditolak()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS);
+        $this->tambahDokumen($objek, 'notula');
+
+        $this->expectException(\Exception::class);
+        $this->expectExceptionMessage('Tidak dapat menyimpan STKL. Silakan unggah Surat Pemberitahuan');
+
+        $this->validasi($objek, 'stkl');
+    }
+
+    /** @test */
+    public function stkl_diterima_setelah_notula_dan_sp()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS);
+        $this->tambahDokumen($objek, 'notula');
+        $this->tambahDokumen($objek, 'surat_pemberitahuan_oss');
+
+        $this->validasi($objek, 'stkl');
+        $this->assertTrue(true);
+    }
+
+    /** @test */
+    public function sp_diterima_dengan_notula_saja()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS);
+        $this->tambahDokumen($objek, 'notula');
+
+        $this->validasi($objek, 'surat_pemberitahuan_oss');
+        $this->validasi($objek, 'surat_pemberitahuan_upt');
+        $this->assertTrue(true);
+    }
+
+    /** @test */
+    public function surat_tugas_ditolak_tanpa_sp()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::LengkapiDokumen);
+        $this->tambahDokumen($objek, 'notula');
+        $this->tambahDokumen($objek, 'stkl');
+
+        $this->expectException(\Exception::class);
+        $this->expectExceptionMessage('Silakan unggah Surat Pemberitahuan terlebih dahulu');
+
+        $this->validasi($objek, 'surat_tugas');
+    }
+
+    /** @test */
+    public function surat_tugas_ditolak_tanpa_stkl()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::LengkapiDokumen);
+        $this->tambahDokumen($objek, 'notula');
+        $this->tambahDokumen($objek, 'surat_pemberitahuan_oss');
+
+        $this->expectException(\Exception::class);
+        $this->expectExceptionMessage('Silakan unggah STKL terlebih dahulu');
+
+        $this->validasi($objek, 'surat_tugas');
+    }
+
+    /** @test */
+    public function surat_tugas_diterima_setelah_notula_sp_stkl()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::LengkapiDokumen);
+        $this->tambahDokumen($objek, 'notula');
+        $this->tambahDokumen($objek, 'stkl');
+        $this->tambahDokumen($objek, 'surat_pemberitahuan_oss');
+
+        $this->validasi($objek, 'surat_tugas');
+        $this->assertTrue(true);
+    }
+
+    /** @test */
+    public function status_tidak_memadai_ditolak()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::Selesai);
+
+        $this->expectException(\Exception::class);
+        $this->expectExceptionMessage('Tidak dapat menyimpan dokumen penjadwalan. Status saat ini');
+
+        $this->validasi($objek, 'notula');
+    }
+
+    /** @test */
+    public function evaluasi_status_lengkap_menjadi_menunggu_inspeksi()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::LengkapiDokumen);
+        $this->tambahDokumen($objek, 'notula');
+        $this->tambahDokumen($objek, 'stkl');
+        $this->tambahDokumen($objek, 'surat_pemberitahuan_oss');
+        $this->tambahDokumen($objek, 'surat_tugas');
+
+        $ref = new \ReflectionMethod(PenjadwalanService::class, 'evaluasiStatusPenjadwalan');
+        $ref->setAccessible(true);
+        $ref->invoke($this->service, $objek);
+
+        $this->assertEquals(ObjekPengawasan::MenungguInspeksi, $objek->fresh()->status);
+    }
+
+    /** @test */
+    public function evaluasi_status_belum_lengkap_menjadi_lengkapi_dokumen()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS);
+        $this->tambahDokumen($objek, 'notula');
+
+        $ref = new \ReflectionMethod(PenjadwalanService::class, 'evaluasiStatusPenjadwalan');
+        $ref->setAccessible(true);
+        $ref->invoke($this->service, $objek);
+
+        $this->assertEquals(ObjekPengawasan::LengkapiDokumen, $objek->fresh()->status);
+    }
+
+    /** @test */
+    public function stkl_diterima_dengan_sp_upt()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS);
+        $this->tambahDokumen($objek, 'notula');
+        $this->tambahDokumen($objek, 'surat_pemberitahuan_upt');
+
+        $this->validasi($objek, 'stkl');
+        $this->assertTrue(true);
+    }
+
+    /** @test */
+    public function surat_tugas_diterima_dengan_sp_upt()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::LengkapiDokumen);
+        $this->tambahDokumen($objek, 'notula');
+        $this->tambahDokumen($objek, 'surat_pemberitahuan_upt');
+        $this->tambahDokumen($objek, 'stkl');
+
+        $this->validasi($objek, 'surat_tugas');
+        $this->assertTrue(true);
+    }
+
+    /** @test */
+    public function status_belum_upload_st_diizinkan_unggah_notula()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::BelumUploadST);
+
+        $this->validasi($objek, 'notula');
+        $this->assertTrue(true);
+    }
+
+    /** @test */
+    public function update_dokumen_yang_sudah_ada_diizinkan_tanpa_urutan()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::LengkapiDokumen);
+        $this->tambahDokumen($objek, 'stkl');
+
+        $this->validasi($objek, 'stkl');
+        $this->assertTrue(true);
+    }
+}
