diff --git a/app/Console/Commands/PengawasanPerizinanBerusaha/Penjadwalan/UatSimulasiLaporanCommand.php b/app/Console/Commands/PengawasanPerizinanBerusaha/Penjadwalan/UatSimulasiLaporanCommand.php
new file mode 100644
index 000000000..17eac10ce
--- /dev/null
+++ b/app/Console/Commands/PengawasanPerizinanBerusaha/Penjadwalan/UatSimulasiLaporanCommand.php
@@ -0,0 +1,201 @@
+<?php
+
+namespace App\Console\Commands\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use App\Models\PengawasanPerizinanBerusaha\InspeksiLapangan\BeritaAcaraPemeriksaan;
+use App\Models\PengawasanPerizinanBerusaha\LaporanPengawasan\LaporanHasilPengawasan;
+use App\Models\PengawasanPerizinanBerusaha\LaporanPengawasan\LaporanHasilPengawasanRiwayat;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenMetadata;
+use App\Services\PengawasanPerizinanBerusaha\LaporanHasilPengawasanService;
+use Illuminate\Console\Command;
+
+class UatSimulasiLaporanCommand extends Command
+{
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'ppbbr:uat-simulasi-laporan {objek_pengawasan_id} {--skenario=notif : notif|belum-tempo|aktif|revisi|kedaluwarsa} {--reset : siapkan ulang via uat-prepare-laporan}';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Simulasi data LHP dari hasil pengawasan existing untuk UAT: tanpa/dengan laporan dalam berbagai kasus PRD (notifikasi jatuh tempo, reupload, histori, validasi H+14).';
+
+    /**
+     * Execute the console command.
+     */
+    public function handle(): int
+    {
+        $id = $this->argument('objek_pengawasan_id');
+        $skenario = $this->option('skenario');
+
+        $objek = ObjekPengawasan::find($id);
+        if (!$objek) {
+            $this->error("Objek Pengawasan dengan ID {$id} tidak ditemukan!");
+            return Command::FAILURE;
+        }
+
+        if ($this->option('reset')) {
+            $this->call('ppbbr:uat-prepare-laporan', [
+                'objek_pengawasan_id' => $id,
+                '--reset' => true,
+            ]);
+            $objek->refresh();
+        }
+
+        if ($objek->status !== ObjekPengawasan::Selesai) {
+            $this->warn("Status objek saat ini '{$objek->status}' (bukan Selesai). Lanjut dengan skenario '{$skenario}'.");
+        }
+
+        $service = new LaporanHasilPengawasanService();
+
+        $next = match ($skenario) {
+            'belum-tempo' => $this->skenarioBelumTempo($objek, $service),
+            'aktif' => $this->skenarioAktif($objek, $service),
+            'revisi' => $this->skenarioRevisi($objek, $service),
+            'kedaluwarsa' => $this->skenarioKedaluwarsa($objek),
+            default => $this->skenarioNotif($objek, $service),
+        };
+
+        $this->info("=========================================");
+        $this->info("Skenario '{$skenario}' siap. Objek {$objek->id} - {$objek->nama_perusahaan}");
+        foreach ($next as $baris) {
+            $this->line($baris);
+        }
+        $this->info("=========================================");
+
+        return Command::SUCCESS;
+    }
+
+    private function hapusLaporan(ObjekPengawasan $objek): void
+    {
+        $ids = LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)->pluck('id');
+        LaporanHasilPengawasanRiwayat::whereIn('laporan_id', $ids)->delete();
+        LaporanHasilPengawasan::where('objek_pengawasan_id', $objek->id)->delete();
+        DokumenMetadata::where('objek_pengawasan_id', $objek->id)
+            ->where('jenis_dokumen', 'laporan')
+            ->delete();
+    }
+
+    private function setBap(ObjekPengawasan $objek, string $tanggal): void
+    {
+        BeritaAcaraPemeriksaan::updateOrCreate(
+            ['objek_pengawasan_id' => $objek->id],
+            [
+                'nomor_surat' => 'BAP-UAT-' . $objek->id . '/' . date('Y'),
+                'tanggal_pemeriksaan' => $tanggal,
+                'nama_pj' => 'PJ UAT',
+                'kontak_pj' => '08123456789',
+            ]
+        );
+    }
+
+    private function buatLaporan(ObjekPengawasan $objek, array $attrs): LaporanHasilPengawasan
+    {
+        return LaporanHasilPengawasan::create(array_merge([
+            'objek_pengawasan_id' => $objek->id,
+            'portal_dokumen_id' => null,
+            'status' => LaporanHasilPengawasanService::STATUS_MENUNGGU_VERIFIKASI,
+            'version' => 1,
+            'is_revision' => false,
+            'waktu_laporan' => now(),
+            'is_synced' => true,
+            'url_dokumen' => ['https://uat.test/nota.pdf'],
+            'is_dokumentasi_kegiatan' => false,
+            'uploaded_by' => null,
+        ], $attrs));
+    }
+
+    private function skenarioNotif(ObjekPengawasan $objek, LaporanHasilPengawasanService $service): array
+    {
+        $this->hapusLaporan($objek);
+
+        // Cari tanggal BAP agar deadline jatuh tepat hari ini
+        $base = null;
+        for ($i = 1; $i <= 90; $i++) {
+            $tgl = now()->subDays($i)->toDateString();
+            $this->setBap($objek, $tgl);
+            if ($service->hitungDeadline($objek->id) === now()->toDateString()) {
+                $base = $tgl;
+                break;
+            }
+        }
+
+        return [
+            "Tanpa laporan, deadline hari ini (BAP {$base}).",
+            "can_upload_laporan: true.",
+            "Uji notif: php artisan ppbbr:notifikasi-sinkronisasi-laporan",
+            "Uji validasi: Simpan laporan via UI (Cari -> Ekstrak -> Simpan).",
+        ];
+    }
+
+    private function skenarioBelumTempo(ObjekPengawasan $objek, LaporanHasilPengawasanService $service): array
+    {
+        $this->hapusLaporan($objek);
+        $this->setBap($objek, now()->toDateString());
+        $deadline = $service->hitungDeadline($objek->id);
+
+        return [
+            "Tanpa laporan, deadline {$deadline} (belum tempo).",
+            "can_upload_laporan: true.",
+            "Uji notif: command tidak mengirim untuk objek ini.",
+        ];
+    }
+
+    private function skenarioAktif(ObjekPengawasan $objek, LaporanHasilPengawasanService $service): array
+    {
+        $this->hapusLaporan($objek);
+        $this->setBap($objek, now()->toDateString());
+        $laporan = $this->buatLaporan($objek, [
+            'deadline_sinkronisasi' => $service->hitungDeadline($objek->id),
+        ]);
+
+        return [
+            "Laporan v{$laporan->version}, deadline {$laporan->deadline_sinkronisasi}, histori kosong.",
+            "Uji validasi: reupload via UI -> version 2 + histori 1.",
+        ];
+    }
+
+    private function skenarioRevisi(ObjekPengawasan $objek, LaporanHasilPengawasanService $service): array
+    {
+        $this->hapusLaporan($objek);
+        $this->setBap($objek, now()->toDateString());
+        $laporan = $this->buatLaporan($objek, [
+            'version' => 2,
+            'is_revision' => true,
+            'deadline_sinkronisasi' => $service->hitungDeadline($objek->id),
+        ]);
+        LaporanHasilPengawasanRiwayat::create([
+            'laporan_id' => $laporan->id,
+            'version' => 1,
+            'file_url' => ['https://uat.test/nota-v1.pdf'],
+            'status' => LaporanHasilPengawasanService::STATUS_MENUNGGU_VERIFIKASI,
+            'aktor_nip' => null,
+        ]);
+
+        return [
+            "Laporan v2 + histori 1 baris.",
+            "Uji: buka detail -> histori tampil; reupload lagi -> version 3.",
+        ];
+    }
+
+    private function skenarioKedaluwarsa(ObjekPengawasan $objek): array
+    {
+        $this->hapusLaporan($objek);
+        $this->setBap($objek, now()->subDays(30)->toDateString());
+        $this->buatLaporan($objek, [
+            'deadline_sinkronisasi' => now()->subDay()->toDateString(),
+        ]);
+
+        return [
+            "Laporan lewat deadline (H+14 hari kerja). can_upload_laporan: false.",
+            "Uji validasi: reupload via UI -> ditolak pesan H+14.",
+            "status_tombol.laporan.enable: false.",
+        ];
+    }
+}
