@@ -0,0 +1,166 @@
+<?php
+
+namespace App\Console\Commands\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenMetadata;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use Illuminate\Console\Command;
+
+class UatSimulasiPenjadwalanCommand extends Command
+{
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'ppbbr:uat-simulasi-penjadwalan {objek_pengawasan_id} {--skenario=baru : baru|parsial|lengkap|inspeksi|terlewat|revisi} {--reset : bangun ulang dokumen via uat-prepare-laporan}';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Simulasi data penjadwalan untuk UAT: siapkan objek ke berbagai kasus PRD (urutan upload, kelengkapan, notifikasi, H-1/Hari-H, revisi).';
+
+    /**
+     * Execute the console command.
+     */
+    public function handle(): int
+    {
+        $id = $this->argument('objek_pengawasan_id');
+        $skenario = $this->option('skenario');
+
+        $objek = ObjekPengawasan::find($id);
+        if (!$objek) {
+            $this->error("Objek Pengawasan dengan ID {$id} tidak ditemukan!");
+            return Command::FAILURE;
+        }
+
+        if ($this->option('reset')) {
+            $this->call('ppbbr:uat-prepare-laporan', [
+                'objek_pengawasan_id' => $id,
+                '--reset' => true,
+            ]);
+            $objek->refresh();
+        }
+
+        $next = match ($skenario) {
+            'parsial' => $this->skenarioParsial($objek),
+            'lengkap' => $this->skenarioLengkap($objek),
+            'inspeksi' => $this->skenarioInspeksi($objek),
+            'terlewat' => $this->skenarioTerlewat($objek),
+            'revisi' => $this->skenarioRevisi($objek),
+            default => $this->skenarioBaru($objek),
+        };
+
+        $this->info("=========================================");
+        $this->info("Skenario penjadwalan '{$skenario}' siap. Objek {$objek->id} - {$objek->nama_perusahaan}");
+        foreach ($next as $baris) {
+            $this->line($baris);
+        }
+        $this->info("=========================================");
+
+        return Command::SUCCESS;
+    }
+
+    private function hapusDokumen(array $jenisList, ObjekPengawasan $objek): void
+    {
+        $ids = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+            ->whereIn('jenis_dokumen', $jenisList)
+            ->pluck('id');
+        DokumenMetadata::where('objek_pengawasan_id', $objek->id)
+            ->whereIn('jenis_dokumen', $jenisList)
+            ->delete();
+        DokumenPenjadwalan::whereIn('id', $ids)->delete();
+
+        foreach ($jenisList as $jenis) {
+            if ($jenis === 'stkl') {
+                $objek->stkl = null;
+            } else if ($jenis === 'surat_tugas') {
+                $objek->surat_tugas = null;
+            } else if (str_starts_with($jenis, 'surat_pemberitahuan')) {
+                if (!DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+                    ->whereIn('jenis_dokumen', ['surat_pemberitahuan_oss', 'surat_pemberitahuan_upt'])->exists()) {
+                    $objek->surat_pemberitahuan = null;
+                }
+            }
+        }
+        $objek->save();
+    }
+
+    private function skenarioBaru(ObjekPengawasan $objek): array
+    {
+        $this->hapusDokumen(['notula', 'surat_pemberitahuan_oss', 'surat_pemberitahuan_upt', 'stkl', 'surat_tugas'], $objek);
+        $objek->status = ObjekPengawasan::PersetujuanDisetujuiOSS;
+        $objek->jadwal = now()->addDays(7)->toDateString();
+        $objek->save();
+
+        return [
+            "Dokumen kosong, status Disetujui (OSS).",
+            "Uji urutan upload perdana: Notula -> STKL -> SP -> ST.",
+        ];
+    }
+
+    private function skenarioParsial(ObjekPengawasan $objek): array
+    {
+        $this->hapusDokumen(['surat_pemberitahuan_oss', 'surat_pemberitahuan_upt', 'surat_tugas'], $objek);
+        $objek->status = ObjekPengawasan::LengkapiDokumen;
+        $objek->jadwal = now()->addDays(7)->toDateString();
+        $objek->save();
+
+        return [
+            "Dokumen tersisa: Notula + STKL. Status Lengkapi Dokumen.",
+            "Uji: lanjutkan SP (butuh STKL: lolos) -> ST.",
+        ];
+    }
+
+    private function skenarioLengkap(ObjekPengawasan $objek): array
+    {
+        $objek->status = ObjekPengawasan::MenungguInspeksi;
+        $objek->jadwal = now()->addDays(7)->toDateString();
+        $objek->save();
+
+        return [
+            "4 dokumen lengkap. Status Menunggu Inspeksi.",
+            "Uji: daftar pantau + notifikasi kelengkapan (job ter-cover unit test).",
+        ];
+    }
+
+    private function skenarioInspeksi(ObjekPengawasan $objek): array
+    {
+        $objek->status = ObjekPengawasan::Inspeksi;
+        $objek->jadwal = now()->toDateString();
+        $objek->save();
+
+        return [
+            "Status Inspeksi, jadwal hari ini (simulasi Hari-H).",
+            "Uji: menu inspeksi + batas H-1 (unggah ditolak).",
+        ];
+    }
+
+    private function skenarioTerlewat(ObjekPengawasan $objek): array
+    {
+        $this->hapusDokumen(['surat_pemberitahuan_oss', 'surat_pemberitahuan_upt', 'surat_tugas'], $objek);
+        $objek->status = ObjekPengawasan::LengkapiDokumen;
+        $objek->jadwal = now()->subDay()->toDateString();
+        $objek->save();
+
+        return [
+            "Dokumen tak lengkap + jadwal kemarin. Status Lengkapi Dokumen.",
+            "Uji: cron ppbbr:penjadwalan-expired -> Penjadwalan Terlewat, atau simulasi mass update.",
+        ];
+    }
+
+    private function skenarioRevisi(ObjekPengawasan $objek): array
+    {
+        $objek->status = ObjekPengawasan::MenungguInspeksi;
+        $objek->jadwal = now()->addDays(7)->toDateString();
+        $objek->save();
+
+        return [
+            "4 dokumen lengkap. Status Menunggu Inspeksi.",
+            "Uji: update/revisi dokumen apa pun tanpa urutan (H-1).",
+        ];
+    }
+}
