+    /**
+     * Tambah N hari kerja dari tanggal dasar (lewati Sabtu-Minggu dan
+     * libur nasional di `mst_hari_libur_nasional`).
+     */
+    public function tambahHariKerja(Carbon $base, int $days): Carbon
+    {
+        $libur = $this->tanggalLiburNasional(
+            $base->toDateString(),
+            $base->copy()->addDays($days + 60)->toDateString()
+        );
+
+        $tanggal = $base->copy();
+        $dihitung = 0;
+        while ($dihitung < $days) {
+            $tanggal->addDay();
+            if ($tanggal->isWeekend() || in_array($tanggal->toDateString(), $libur, true)) {
+                continue;
+            }
+            $dihitung++;
+        }
+
+        return $tanggal;
+    }
+
+    /**
+     * Selisih hari kerja dari -> sampai (bertanda: negatif bila sudah lewat).
+     */
+    public function selisihHariKerja(Carbon $dari, Carbon $sampai): int
+    {
+        $maju = $sampai->gte($dari);
+        $awal = $maju ? $dari->copy()->startOfDay() : $sampai->copy()->startOfDay();
+        $akhir = $maju ? $sampai->copy()->startOfDay() : $dari->copy()->startOfDay();
+
+        $libur = $this->tanggalLiburNasional($awal->toDateString(), $akhir->toDateString());
+
+        $hitung = 0;
+        $t = $awal->copy();
+        while ($t->lt($akhir)) {
+            $t->addDay();
+            if ($t->isWeekend() || in_array($t->toDateString(), $libur, true)) {
+                continue;
+            }
+            $hitung++;
+        }
+
+        return $maju ? $hitung : -$hitung;
+    }
+
+    /**
+     * Daftar tanggal libur nasional (Y-m-d) pada rentang.
+     *
+     * Di-cache per tahun kalender (data SKB praktis statis) agar list
+     * dengan banyak baris tidak menimbulkan N+1 query.
+     */
+    private function tanggalLiburNasional(string $dari, string $sampai): array
+    {
+        $semua = [];
+        foreach (range((int) substr($dari, 0, 4), (int) substr($sampai, 0, 4)) as $tahun) {
+            $semua = array_merge($semua, Cache::remember(
+                "ppbbr:libur-nasional:{$tahun}",
+                now()->addDay(),
+                fn () => HariLiburNasional::whereYear('tanggal', $tahun)
+                    ->pluck('tanggal')
+                    ->map(fn ($t) => Carbon::parse($t)->toDateString())
+                    ->all()
+            ));
+        }
+
+        return array_values(array_filter(
+            $semua,
+            fn ($t) => $t >= $dari && $t <= $sampai
+        ));
+    }
+
