+<?php
+
+namespace Tests\Feature\Master;
+
+use App\Models\Master\HariLiburNasional;
+use App\Models\User;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Illuminate\Support\Facades\Http;
+use PHPOpenSourceSaver\JWTAuth\Facades\JWTAuth;
+use Tests\TestCase;
+
+/**
+ * Menguji sinkronisasi hari libur: primer kemendesa.link (SKB, tanpa key),
+ * fallback api.co.id bila primer gagal.
+ */
+class HariLiburSinkronisasiTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    private function token(): string
+    {
+        return JWTAuth::fromUser(User::factory()->create());
+    }
+
+    /** @test */
+    public function sinkronisasi_primer_kemendesa_menyimpan_data()
+    {
+        Http::fake([
+            'api.kemendesa.link/*' => Http::response([
+                'data' => [
+                    ['date' => '2026-01-01', 'name' => 'Tahun Baru 2026 Masehi'],
+                    ['date' => '2026-08-17', 'name' => 'Proklamasi Kemerdekaan'],
+                ],
+            ], 200),
+        ]);
+
+        $response = $this->withHeader('Authorization', 'Bearer ' . $this->token())
+            ->getJson('/api/v1/master/hari-libur?tahun=2026');
+
+        $response->assertStatus(200);
+        $response->assertJsonPath('status', true);
+        $this->assertDatabaseHas('mst_hari_libur_nasional', [
+            'tanggal' => '2026-08-17',
+            'nama' => 'Proklamasi Kemerdekaan',
+        ]);
+    }
+
+    /** @test */
+    public function primer_gagal_fallback_ke_api_co_id()
+    {
+        config(['services.api_co_id.holidays_key' => 'test-key']);
+
+        Http::fake([
+            'api.kemendesa.link/*' => Http::response([], 500),
+            'use.api.co.id/*' => Http::response([
+                'is_success' => true,
+                'data' => [
+                    ['date' => '2026-01-01', 'name' => 'Tahun Baru', 'type' => 'Public Holiday'],
+                    ['date' => '2026-01-05', 'name' => 'Peringatan', 'type' => 'Observance'],
+                ],
+            ], 200),
+        ]);
+
+        $response = $this->withHeader('Authorization', 'Bearer ' . $this->token())
+            ->getJson('/api/v1/master/hari-libur?tahun=2026');
+
+        $response->assertStatus(200);
+        $this->assertDatabaseHas('mst_hari_libur_nasional', [
+            'tanggal' => '2026-01-01',
+            'nama' => 'Tahun Baru',
+        ]);
+        $this->assertDatabaseMissing('mst_hari_libur_nasional', [
+            'tanggal' => '2026-01-05',
+        ]);
+    }
+}
