new file mode 100644
index 000000000..bf4adb683
--- /dev/null
+++ b/tests/Feature/Penjadwalan/ResetMassalPenjadwalanTest.php
@@ -0,0 +1,112 @@
+<?php
+
+namespace Tests\Feature\Penjadwalan;
+
+use App\Http\Controllers\FrontendHelper\TestController;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Illuminate\Http\Request;
+use Tests\TestCase;
+
+/**
+ * Menguji reset massal khusus penjadwalan (dev/local) berbasis status,
+ * tanpa input ID.
+ */
+class ResetMassalPenjadwalanTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        config(['app.env' => 'local']);
+    }
+
+    private function buatObjek(string $status, bool $denganDokumen = false): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $kode = 'U-' . rand(100000, 999999);
+        \App\Models\UnitKerja::create([
+            'kode_unit' => $kode,
+            'nama_unit' => 'Unit Uji ' . uniqid(),
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        $objek = ObjekPengawasanFactory::new()->create([
+            'status' => $status,
+            'unit_kerja' => $kode,
+        ]);
+
+        if ($denganDokumen) {
+            DokumenPenjadwalan::create([
+                'objek_pengawasan_id' => $objek->id,
+                'jenis_dokumen' => 'notula',
+                'file_path' => 'storage/uat/notula.pdf',
+            ]);
+        }
+
+        return $objek;
+    }
+
+    private function resetMassal(array $query): array
+    {
+        $response = (new TestController())->resetMassalPenjadwalan(new Request($query));
+
+        return [$response->getStatusCode(), $response->getData(true)];
+    }
+
+    /** @test */
+    public function reset_massal_terlewat_ke_disetujui_oss_tanpa_input_id()
+    {
+        $a = $this->buatObjek(ObjekPengawasan::PenjadwalanTerlewat, true);
+        $b = $this->buatObjek(ObjekPengawasan::PenjadwalanTerlewat, true);
+        $lain = $this->buatObjek(ObjekPengawasan::Selesai);
+
+        [$http, $data] = $this->resetMassal(['target' => 'disetujui_oss']);
+
+        $this->assertEquals(200, $http);
+        $this->assertGreaterThanOrEqual(2, $data['data']['jumlah']);
+
+        $ids = array_column($data['data']['hasil'], 'objek_pengawasan_id');
+        $this->assertContains($a->id, $ids);
+        $this->assertContains($b->id, $ids);
+        $this->assertNotContains($lain->id, $ids);
+
+        $this->assertEquals(ObjekPengawasan::PersetujuanDisetujuiOSS, $a->fresh()->status);
+        $this->assertEquals(ObjekPengawasan::PersetujuanDisetujuiOSS, $b->fresh()->status);
+        $this->assertEquals(ObjekPengawasan::Selesai, $lain->fresh()->status);
+        $this->assertEquals(0, DokumenPenjadwalan::whereIn('objek_pengawasan_id', [$a->id, $b->id])->count());
+    }
+
+    /** @test */
+    public function reset_massal_menolak_target_non_penjadwalan()
+    {
+        [$http, $data] = $this->resetMassal(['target' => 'reset_laporan']);
+
+        $this->assertEquals(422, $http);
+        $this->assertStringContainsString('Target tidak valid', $data['message']);
+    }
+
+    /** @test */
+    public function reset_massal_bisa_difilter_unit_kerja()
+    {
+        $a = $this->buatObjek(ObjekPengawasan::PenjadwalanTerlewat, true);
+
+        [$http, $data] = $this->resetMassal([
+            'target' => 'disetujui_oss',
+            'unit_kerja' => $a->unit_kerja,
+        ]);
+
+        $this->assertEquals(200, $http);
+        $ids = array_column($data['data']['hasil'], 'objek_pengawasan_id');
+        $this->assertContains($a->id, $ids);
+        $this->assertEquals(ObjekPengawasan::PersetujuanDisetujuiOSS, $a->fresh()->status);
+    }
+}
