+<?php
+
+namespace Tests\Feature\Penjadwalan;
+
+use App\Http\Controllers\FrontendHelper\TestController;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Tests\TestCase;
+
+/**
+ * Menguji reset satuan objek (dev/local), termasuk target simulasi terlewat.
+ */
+class ResetObjekPengawasanTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        config(['app.env' => 'local']);
+    }
+
+    private function buatObjek(string $status, bool $denganDokumen = false): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $kode = 'U-' . rand(100000, 999999);
+        \App\Models\UnitKerja::create([
+            'kode_unit' => $kode,
+            'nama_unit' => 'Unit Uji ' . uniqid(),
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        $objek = ObjekPengawasanFactory::new()->create([
+            'status' => $status,
+            'unit_kerja' => $kode,
+        ]);
+
+        if ($denganDokumen) {
+            DokumenPenjadwalan::create([
+                'objek_pengawasan_id' => $objek->id,
+                'jenis_dokumen' => 'notula',
+                'file_path' => 'storage/uat/notula.pdf',
+            ]);
+        }
+
+        return $objek;
+    }
+
+    /** @test */
+    public function reset_terlewat_simulasi_overdue_pertahankan_dokumen()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::PersetujuanDisetujuiOSS, true);
+
+        $response = (new TestController())->resetObjekPengawasan($objek->id, 'terlewat');
+        $data = $response->getData(true);
+
+        $this->assertEquals(200, $response->getStatusCode());
+        $this->assertEquals(ObjekPengawasan::PenjadwalanTerlewat, $objek->fresh()->status);
+        $this->assertEquals(
+            now()->subDay()->toDateString(),
+            \Carbon\Carbon::parse($objek->fresh()->jadwal)->toDateString()
+        );
+        $this->assertEquals(1, DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)->count());
+    }
+}

