+<?php
+
+namespace Tests\Feature\Penjadwalan;
+
+use App\Models\PegawaiInternal;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\UnitKerja;
+use App\Models\User;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use PHPOpenSourceSaver\JWTAuth\Facades\JWTAuth;
+use Spatie\Permission\Models\Role;
+use Tests\TestCase;
+
+/**
+ * Regresi: sisa_hari list penjadwalan harus positif untuk jadwal mendatang
+ * (bug tanda terbalik akibat default signed diffInDays Carbon 3).
+ */
+class PenjadwalanSisaHariTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    private UnitKerja $unit;
+    private string $token;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $this->unit = UnitKerja::create([
+            'kode_unit' => 'U-' . rand(100000, 999999),
+            'nama_unit' => 'Unit Uji ' . uniqid(),
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        Role::firstOrCreate(['name' => 'Operator UPT WasRisk', 'guard_name' => 'api']);
+        $user = User::create([
+            'username' => 'test_' . uniqid(),
+            'password' => bcrypt('password'),
+        ]);
+        $user->assignRole('Operator UPT WasRisk');
+
+        $pegawai = PegawaiInternal::create([
+            'nip' => 'NIP' . rand(10000, 99999),
+            'nama_pegawai' => 'Pegawai Uji',
+            'unit_kerja_id' => $this->unit->kode_unit,
+            'user_id' => $user->id,
+        ]);
+        $user->pegint_id = $pegawai->nip;
+        $user->save();
+
+        $this->token = JWTAuth::fromUser($user);
+    }
+
+    private function daftar(): array
+    {
+        $response = $this->withHeader('Authorization', "Bearer {$this->token}")
+            ->getJson('/api/v1/ppbbr/penjadwalan');
+
+        $response->assertStatus(200);
+        $response->assertJsonPath('status', true);
+
+        return $response->json('data');
+    }
+
+    /** @test */
+    public function sisa_hari_positif_untuk_jadwal_mendatang()
+    {
+        ObjekPengawasanFactory::new()->create([
+            'status' => ObjekPengawasan::PersetujuanDisetujuiOSS,
+            'unit_kerja' => $this->unit->kode_unit,
+            'jadwal' => now()->addDay()->toDateString(),
+        ]);
+
+        $item = $this->daftar()[0];
+
+        $this->assertEquals(1, $item['sisa_hari']);
+    }
+
+    /** @test */
+    public function sisa_hari_null_untuk_jadwal_lewat()
+    {
+        ObjekPengawasanFactory::new()->create([
+            'status' => ObjekPengawasan::PersetujuanDisetujuiOSS,
+            'unit_kerja' => $this->unit->kode_unit,
+            'jadwal' => now()->subDay()->toDateString(),
+        ]);
+
+        $item = $this->daftar()[0];
+
+        $this->assertNull($item['sisa_hari']);
+    }
+}

