diff --git a/app/Console/Commands/PengawasanPerizinanBerusaha/Penjadwalan/BersihkanDokumenPhantom.php b/app/Console/Commands/PengawasanPerizinanBerusaha/Penjadwalan/BersihkanDokumenPhantom.php
