@@ -0,0 +1,97 @@
+<?php
+
+namespace App\Console\Commands\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use Illuminate\Console\Command;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+
+class BersihkanDokumenPhantom extends Command
+{
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'ppbbr:bersihkan-dokumen-phantom {--fix : Hapus record phantom dan turunkan status yang terlanjur} {--force : Lewati konfirmasi (untuk pemanggilan via TestController)}';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Deteksi (dan opsional hapus) DokumenPenjadwalan tanpa file (file_path null + portal_dokumen_id null)';
+
+    /**
+     * Execute the console command.
+     */
+    public function handle()
+    {
+        $phantoms = DokumenPenjadwalan::whereNull('file_path')
+            ->whereNull('portal_dokumen_id')
+            ->with('objekPengawasan')
+            ->get();
+
+        if ($phantoms->isEmpty()) {
+            $this->info('Tidak ada dokumen phantom. Data bersih.');
+            return 0;
+        }
+
+        $this->warn("Ditemukan {$phantoms->count()} dokumen phantom:");
+        $this->table(
+            ['ID', 'Objek ID', 'Kode Proyek', 'Jenis', 'Nomor Surat', 'Created'],
+            $phantoms->map(fn ($d) => [
+                $d->id,
+                $d->objek_pengawasan_id,
+                $d->objekPengawasan?->no_kode_proyek ?? '-',
+                $d->jenis_dokumen,
+                $d->manual_nomor_surat ?? '-',
+                $d->created_at,
+            ])->toArray()
+        );
+
+        if (!$this->option('fix')) {
+            $this->info('Mode dry-run. Jalankan dengan --fix untuk menghapus dan memperbaiki status.');
+            return 0;
+        }
+
+        if (!$this->option('force') && !$this->confirm('Hapus semua dokumen phantom di atas?', false)) {
+            $this->info('Dibatalkan.');
+            return 0;
+        }
+
+        $objekIds = $phantoms->pluck('objek_pengawasan_id')->unique()->values();
+        DokumenPenjadwalan::whereIn('id', $phantoms->pluck('id'))->delete();
+        $this->info("Berhasil menghapus {$phantoms->count()} dokumen phantom.");
+
+        // Turunkan status objek yang terlanjur Menunggu Inspeksi padahal dokumen tidak lengkap
+        $diturunkan = 0;
+        foreach ($objekIds as $objekId) {
+            $objek = ObjekPengawasan::find($objekId);
+            if (!$objek || $objek->status !== ObjekPengawasan::MenungguInspeksi) {
+                continue;
+            }
+
+            $valid = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+                ->where(function ($q) {
+                    $q->whereNotNull('file_path')->orWhereNotNull('portal_dokumen_id');
+                })
+                ->pluck('jenis_dokumen')->toArray();
+
+            $lengkap = in_array('notula', $valid)
+                && in_array('stkl', $valid)
+                && (in_array('surat_pemberitahuan_oss', $valid) || in_array('surat_pemberitahuan_upt', $valid))
+                && in_array('surat_tugas', $valid);
+
+            if (!$lengkap) {
+                $objek->status = ObjekPengawasan::LengkapiDokumen;
+                $objek->save();
+                $diturunkan++;
+            }
+        }
+
+        $this->info("Status diturunkan ke Lengkapi Dokumen pada {$diturunkan} objek pengawasan.");
+
+        return 0;
+    }
+}
