+<?php
+
+namespace App\Http\Requests\PengawasanPerizinanBerusaha\HasilInspeksiLapangan;
+
+use Illuminate\Foundation\Http\FormRequest;
+
+/**
+ * Validasi lookup dokumen Laporan relevan berdasarkan NKU.
+ *
+ * Bukan pencarian CSRS: lookup ke metadata tersimpan
+ * (NKU -> Objek Pengawasan -> Nomor ST -> dokumen Laporan).
+ */
+class CariDokumenRelevanRequest extends FormRequest
+{
+    public function authorize(): bool
+    {
+        return true;
+    }
+
+    public function rules(): array
+    {
+        return [
+            /**
+             * Daftar NKU (1 atau banyak). Contoh: ?nku[]=202206-2118-4358-7973-033
+             * @example ["202206-2118-4358-7973-033"]
+             */
+            'nku' => 'required|array|min:1',
+            'nku.*' => 'required|string|max:255',
+        ];
+    }
+}
