+<?php
+
+namespace Tests\Feature\PengawasanPerizinanBerusaha;
+
+use App\Models\PegawaiInternal;
+use App\Models\Penjadwalan\DokumenMetadata;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use App\Models\UnitKerja;
+use App\Models\User;
+use Database\Factories\ObjekPengawasanFactory;
+use Illuminate\Foundation\Testing\DatabaseTransactions;
+use Modules\Gateway\Entities\PortalDokumen;
+use PHPOpenSourceSaver\JWTAuth\Facades\JWTAuth;
+use Spatie\Permission\Models\Role;
+use Tests\TestCase;
+
+/**
+ * Menguji endpoint lookup dokumen Laporan relevan berdasarkan NKU
+ * (PRD LHP §3.5): NKU -> Objek -> Nomor ST -> metadata laporan.
+ */
+class LaporanCariRelevanTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    private string $token;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $unit = UnitKerja::create([
+            'kode_unit' => 'U-' . rand(100000, 999999),
+            'nama_unit' => 'Unit Uji ' . uniqid(),
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+
+        Role::firstOrCreate(['name' => 'Operator UPT WasRisk', 'guard_name' => 'api']);
+        $user = User::create([
+            'username' => 'test_' . uniqid(),
+            'password' => bcrypt('password'),
+        ]);
+        $user->assignRole('Operator UPT WasRisk');
+
+        $pegawai = PegawaiInternal::create([
+            'nip' => 'NIP' . rand(10000, 99999),
+            'nama_pegawai' => 'Pegawai Uji',
+            'unit_kerja_id' => $unit->kode_unit,
+            'user_id' => $user->id,
+        ]);
+        $user->pegint_id = $pegawai->nip;
+        $user->save();
+
+        $this->token = JWTAuth::fromUser($user);
+        $this->unitKode = $unit->kode_unit;
+    }
+
+    private string $unitKode;
+
+    private function buatObjek(string $nku): ObjekPengawasan
+    {
+        return ObjekPengawasanFactory::new()->create([
+            'no_kode_proyek' => $nku,
+            'status' => ObjekPengawasan::Selesai,
+            'unit_kerja' => $this->unitKode,
+        ]);
+    }
+
+    /** @test */
+    public function mengembalikan_rekomendasi_untuk_nku_yang_punya_laporan()
+    {
+        $nku = '202603-0711-0133-1743-190';
+        $stNomor = 'B.18413/PSDKPLan.1/KP.440/IX/2026';
+        $objek = $this->buatObjek($nku);
+
+        DokumenPenjadwalan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'jenis_dokumen' => 'surat_tugas',
+            'manual_nomor_surat' => $stNomor,
+            'file_path' => 'storage/uat/st.pdf',
+        ]);
+
+        $portal = PortalDokumen::create([
+            'dokumen_id' => (int) (time() . rand(100, 999)),
+            'ref_number' => 'B.18413/PSDKPLan.1/PW.110/IX/2026',
+            'subject' => 'SPDRUT Nota Dinas',
+            'sender' => 'UPT',
+            'letter_date' => now()->toDateString(),
+        ]);
+
+        DokumenMetadata::create([
+            'portal_dokumen_id' => $portal->id,
+            'jenis_dokumen' => 'laporan',
+            'jenis_item' => 'nomor_st',
+            'nilai' => $stNomor,
+        ]);
+
+        $response = $this->withHeader('Authorization', "Bearer {$this->token}")
+            ->getJson('/api/v1/ppbbr/hasil-inspeksi/dokumen/cari-relevan?nku[]=' . urlencode($nku));
+
+        $response->assertStatus(200);
+        $response->assertJsonPath('status', true);
+        $rekomendasi = $response->json('data.rekomendasi_dokumen');
+        $this->assertCount(1, $rekomendasi);
+        $this->assertEquals($stNomor, $rekomendasi[0]['nilai']);
+        $this->assertNotNull($rekomendasi[0]['portal_dokumen_id']);
+    }
+
+    /** @test */
+    public function mengembalikan_kosong_untuk_nku_tidak_dikenal()
+    {
+        $response = $this->withHeader('Authorization', "Bearer {$this->token}")
+            ->getJson('/api/v1/ppbbr/hasil-inspeksi/dokumen/cari-relevan?nku[]=999999-9999-9999-9999-999');
+
+        $response->assertStatus(200);
+        $response->assertJsonPath('status', true);
+        $this->assertEquals([], $response->json('data.rekomendasi_dokumen'));
+    }
+
+    /** @test */
+    public function menolak_bila_param_nku_tidak_dikirim()
+    {
+        $response = $this->withHeader('Authorization', "Bearer {$this->token}")
+            ->getJson('/api/v1/ppbbr/hasil-inspeksi/dokumen/cari-relevan');
+
+        $response->assertStatus(422);
+    }
+}

