@@ -0,0 +1,106 @@
+<?php
+
+namespace App\Console\Commands\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use Illuminate\Console\Command;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use App\Services\PengawasanPerizinanBerusaha\EkstrakDokumenService;
+
+/**
+ * Memulihkan manual_nomor_surat pada dokumen ST hasil migrasi legacy
+ * (hanya punya file_path) dengan mengekstrak ulang PDF-nya.
+ *
+ * Tanpa nomor, ST legacy selalu `invalid` saat pencocokan LHP
+ * (cocokkanKeObjek hanya cek manual_nomor_surat / portal ref_number).
+ */
+class PulihkanNomorStLegacy extends Command
+{
+    protected $signature = 'ppbbr:pulihkan-nomor-st-legacy
+        {--fix : Tulis manual_nomor_surat hasil ekstraksi ke database}
+        {--limit=50 : Batas jumlah dokumen diproses per jalan}';
+
+    protected $description = 'Ekstrak ulang PDF ST legacy (tanpa nomor surat) untuk memulihkan manual_nomor_surat';
+
+    public function handle(): int
+    {
+        $limit = (int) $this->option('limit');
+
+        $docs = DokumenPenjadwalan::where('jenis_dokumen', 'surat_tugas')
+            ->whereNull('manual_nomor_surat')
+            ->whereNull('portal_dokumen_id')
+            ->whereNotNull('file_path')
+            ->limit($limit)
+            ->get(['id', 'objek_pengawasan_id', 'file_path']);
+
+        if ($docs->isEmpty()) {
+            $this->info('Tidak ada dokumen ST legacy tanpa nomor surat.');
+            return self::SUCCESS;
+        }
+
+        $this->info("Ditemukan {$docs->count()} dokumen ST tanpa nomor surat.");
+
+        if (!$this->option('fix')) {
+            $this->table(['ID', 'Objek ID', 'File'], $docs->map(fn ($d) => [$d->id, $d->objek_pengawasan_id, $d->file_path])->toArray());
+            $this->info('Mode dry-run. Jalankan dengan --fix untuk mengekstrak dan menyimpan nomor.');
+            return self::SUCCESS;
+        }
+
+        $ekstrak = new EkstrakDokumenService();
+        $ok = 0;
+        $gagal = 0;
+
+        foreach ($docs as $doc) {
+            $fullPath = $this->resolvePath($doc->file_path);
+
+            if (!$fullPath || !file_exists($fullPath)) {
+                $this->warn("ID {$doc->id}: file fisik tidak ditemukan ({$doc->file_path})");
+                $gagal++;
+                continue;
+            }
+
+            try {
+                $items = $ekstrak->ekstrakViaPython($fullPath);
+            } catch (\Exception $e) {
+                $this->warn("ID {$doc->id}: ekstraksi gagal: {$e->getMessage()}");
+                $gagal++;
+                continue;
+            }
+
+            $nomor = collect(is_array($items) ? $items : [])
+                ->where('jenis_item', 'nomor_st')
+                ->pluck('nilai')
+                ->filter()
+                ->first();
+
+            if (!$nomor) {
+                $this->warn("ID {$doc->id}: tidak ada Nomor ST terbaca");
+                $gagal++;
+                continue;
+            }
+
+            $doc->manual_nomor_surat = $nomor;
+            $doc->save();
+            $this->info("ID {$doc->id}: {$nomor}");
+            $ok++;
+        }
+
+        $this->info("Selesai. Berhasil: {$ok}, gagal: {$gagal}.");
+
+        return self::SUCCESS;
+    }
+
+    private function resolvePath(?string $filePath): ?string
+    {
+        if (!$filePath) return null;
+
+        if (str_starts_with($filePath, 'storage/')) {
+            return storage_path('app/public/' . substr($filePath, strlen('storage/')));
+        }
+
+        if (str_starts_with($filePath, 'bucket/')) {
+            return public_path($filePath);
+        }
+
+        return null;
+    }
+}
