+    /**
+     * Pulihkan manual_nomor_surat ST legacy via ekstraksi ulang PDF.
+     *
+     * Endpoint: GET /fe-test/ppbbr/pulihkan-nomor-st-legacy?fix=1&limit=50
+     * Tanpa ?fix=1: dry-run (hanya daftar). Dengan ?fix=1: ekstrak + simpan nomor.
+     */
+    public function pulihkanNomorStLegacy(Request $request)
+    {
+        if (config('app.env') !== 'local' && config('app.env') !== 'dev') {
+            return response()->json(['message' => 'Hanya bisa diakses di environment dev/local'], 403);
+        }
+
+        \Illuminate\Support\Facades\Artisan::call('ppbbr:pulihkan-nomor-st-legacy', [
+            '--fix' => (bool) $request->query('fix', false),
+            '--limit' => (int) $request->query('limit', 50),
+        ]);
+        $output = \Illuminate\Support\Facades\Artisan::output();
+
+        return response()->json([
+            'message' => 'Berhasil menjalankan pemulihan nomor ST legacy',
+            'output' => array_values(array_filter(explode("\n", trim($output)))),
+        ]);
+    }
 }
