+            ], 422);
+        }
+
+        $userId = \Illuminate\Support\Facades\Auth::id() ?? 0;
+        $keys = [
+            "ppbbr:cari_surat:{$userId}:{$jenis}:{$referensiId}",
+            "crs:cari_surat:{$userId}:{$jenis}:{$referensiId}",
+            "ppbbr:upload_manual:{$userId}:{$jenis}:{$referensiId}",
+        ];
+
+        $dibersihkan = [];
