+
+def classify(path):
+    """Tentukan jenis dokumen dari nama berkas (folder sudah dipisah per jenis).
+
+    Sejak korpus dirapikan, `surat-tugas/` dan `laporan-campuran/` sudah terpisah.
+    Nama berkas tetap jadi penentu utama supaya label laporan tidak menyesatkan
+    bila kelak ada berkas yang salah tempat lagi.
+    """
+    name = os.path.basename(path).lower()
+
+    if "notulen" in name or "notula" in name:
+        return "Notula"
+    if "laporan" in name or "nota_dinas" in name or "nodin" in name:
+        return "Laporan"
+    if "surat_tugas" in name or "spt" in name or "revisi_b_" in name:
+        return "Surat Tugas"
+    return "Surat Tugas"
+
+
+def collect():
+    samples = []
+    for sub in ("notula", "surat-tugas", "laporan-campuran"):
+        for f in sorted(glob.glob(os.path.join(KORPUS, sub, "*.pdf"))):
+            samples.append((classify(f), f))
+    return samples
+
+
+def run(path):
+    t0 = time.perf_counter()
+    p = subprocess.run([PY, SCRIPT, path], capture_output=True, text=True,
+                       encoding="utf-8", errors="replace")
+    dt = time.perf_counter() - t0
+    stats = {}
+    m = re.search(r"^STATS\s*(\{.*\})", p.stdout + p.stderr, re.M)
+    if m:
+        try:
+            stats = json.loads(m.group(1))
+        except Exception:
+            pass
+    payload = p.stdout
+    payload = re.sub(r"^STATS\s*\{.*\}\s*$", "", payload, flags=re.M).strip()
+    try:
+        hits = json.loads(payload) if payload else []
+    except Exception:
+        hits = []
+    return dt, stats, len(hits)
+
+
+rows = collect()
+out = []
+print(f"{'TYPE':12} {'TIME':>7} {'PAGES':>5} {'NATIVE':>6} {'OCR':>4} {'OCR_S':>6} {'HITS':>4}  FILE")
+for label, f in rows:
+    dt, st, nh = run(f)
+    out.append({
