+        "file": os.path.basename(f),
+        "waktu_total_s": round(dt, 3),
+        "halaman": st.get("pages_total", ""),
+        "halaman_native": st.get("pages_native", ""),
+        "halaman_ocr": st.get("pages_ocr", ""),
+        "halaman_ocr_skip": st.get("pages_ocr_skipped", ""),
+        "detik_ocr": st.get("ocr_seconds", 0),
+        "detik_native": st.get("native_seconds", 0),
+        "jumlah_hit": nh,
+    })
+    print(f"{label:12} {dt:6.2f}s {st.get('pages_total',0):5} {st.get('pages_native',0):6} "
+          f"{st.get('pages_ocr',0):4} {st.get('ocr_seconds',0):5.2f}s {nh:4}  {os.path.basename(f)[:44]}")
+
+with open(OUT, "w", newline="", encoding="utf-8") as fh:
+    w = csv.DictWriter(fh, fieldnames=list(out[0].keys()))
+    w.writeheader()
+    w.writerows(out)
+
+n = len(out)
+print()
