+#!/usr/bin/env python
+"""
+uji_ekstraksi.py — Uji batch ekstraksi NKU & Nomor ST untuk modul PPBBR-SDP.
+
+Skrip ini MENGGANTIKAN tiga skrip uji lama yang terpecah per jenis dokumen:
+    dummySurat/04-arsip-uji-lama/skrip-read_nku.py           (folder ST, NKU saja)
+    dummySurat/04-arsip-uji-lama/skrip-read_st.py            (folder Laporan, ST saja)
+    dummySurat/04-arsip-uji-lama/skrip-read_nku_notula.py    (folder Notula, NKU saja)
+
+Alasan penggabungan:
+  1. Tiga skrip itu menduplikasi regex, format_nku(), format_st(), dan loop OCR.
+  2. Ketiganya masih memakai guard lama `if len(native_text.strip()) > 50: continue`
+     yang membuat OCR tetap jalan di halaman tipis padahal target sudah ketemu —
+     bug yang sudah diperbaiki di produksi (scripts/PPBBR/extract_dokumen.py).
+  3. Sebagian masih ekstrak NKU saja atau ST saja, padahal satu dokumen bisa
+     memuat keduanya (mis. Surat Tugas memuat NKU perusahaan + Nomor ST).
+
+Prinsip: skrip ini TIDAK menyalin ulang logika ekstraksi. Ia memanggil
+extract_dokumen.py — sumber kebenaran yang dipakai PHP — sehingga hasil uji
+selalu mencerminkan perilaku produksi, bukan implementasi paralel yang bisa
+menyimpang.
+
+Pemakaian:
+    # 1) Uji default: sampel scan/foto (OCR murni) di dummySurat/korpus/scan-foto
+    python scripts/PPBBR/uji_ekstraksi.py
+
+    # 2) Uji korpus ber-text-layer (PDF dari portal) di dummySurat/korpus/text-layer
+    python scripts/PPBBR/uji_ekstraksi.py --dir docs/.../dummySurat --mode korpus
+
+    # 3) Keduanya sekaligus, tulis CSV ringkasan
+    python scripts/PPBBR/uji_ekstraksi.py --mode semua --csv
+
+    # 4) Satu file saja
+    python scripts/PPBBR/uji_ekstraksi.py --file "docs/.../surat tugas-scan.pdf"
+
+Opsi:
+    --dir PATH        Folder root yang ditelusuri (default: dummySurat).
+    --mode {ocr,korpus,semua}
+                      ocr    -> hanya korpus/scan-foto/ (default)
+                      korpus -> hanya korpus/text-layer/
+                      semua  -> keduanya
+    --csv             Tulis CSV hasil ke dummySurat/03-hasil/uji-ekstraksi-<mode>.csv
+    --json            Cetak hasil lengkap sebagai JSON (untuk parsing mesin)
+    --max-pages N     Batas halaman yang diproses (0 = semua, default 0)
+    --quiet           Sembunyikan progres per file
+"""
+
+import argparse
+import csv
+import json
+import os
+import re
+import subprocess
+import sys
+import time
+
+# ── Lokasi skrip produksi yang diuji ────────────────────────────────────────
+SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
+EXTRACTOR = os.path.join(SCRIPT_DIR, "extract_dokumen.py")
+
+# Root default: docs/Modul/PPBBR-SDP/penjadwalan/dummySurat
+_REPO_ROOT = os.path.abspath(os.path.join(SCRIPT_DIR, "..", ".."))
+DUMMY_SURAT = os.path.join(
+    _REPO_ROOT, "docs", "Modul", "PPBBR-SDP", "penjadwalan", "dummySurat"
+)
+
+# ── Klasifikasi jenis dokumen (berbasis nama folder & nama file) ────────────
+# Berbasis pola nama, bukan sekadar nama folder: korpus pernah punya folder ST/
+# yang ternyata juga berisi 6 file Laporan. Kini folder sudah dipisah per jenis,
+# tetapi pencocokan nama berkas tetap dipertahankan sebagai jaring pengaman.
+JENIS_RULES = [
+    (r"notulen|notula", "Notula"),
+    (r"pemberitahuan|sp_upt|sp-upt|surat_pemberitahuan", "Surat Pemberitahuan UPT"),
+    (r"surat_tugas|surat-tugas|surat tugas|spt|revisi_b_|revisi-b-|revisi_spt|revisi-spt",
+     "Surat Tugas"),
+    (r"laporan|nota_dinas|nota-dinas|nodin", "Laporan Hasil Pengawasan"),
+]
+
+# Nama folder korpus -> jenis dokumen. Dipakai sebagai fallback KEDUA.
+#
+# Sejak korpus dirapikan, folder sudah jadi penanda jenis yang dapat dipercaya:
+# semuanya berisi satu jenis saja. Tetapi urutannya penting — pencocokan nama
+# berkas dijalankan LEBIH DULU, karena justru itulah yang mengungkap bahwa
+# `surat-tugas/` pernah memuat berkas Laporan. Folder adalah petunjuk, nama
+# berkas adalah bukti. Fallback ini hanya menangkap berkas yang namanya tidak
+# menyebut jenis surat sama sekali (mis. nama pengawas disambung jadi satu).
+FOLDER_RULES = [
+    (r"/korpus/scan-foto/notula/", "Notula"),
+    (r"/korpus/scan-foto/surat-tugas/", "Surat Tugas"),
+    (r"/korpus/scan-foto/surat-pemberitahuan-upt/", "Surat Pemberitahuan UPT"),
+    (r"/korpus/scan-foto/laporan-hasil-pengawasan/", "Laporan Hasil Pengawasan"),
+    (r"/korpus/text-layer/notula/", "Notula"),
+    (r"/korpus/text-layer/surat-tugas/", "Surat Tugas"),
+    (r"/korpus/text-layer/laporan-campuran/", "Laporan Hasil Pengawasan"),
+]
+
+
+def klasifikasi_jenis(path):
+    """Tentukan jenis dokumen dari path (nama berkas dulu, folder sebagai cadangan).
+
+    `path` dinormalkan ke lowercase lebih dulu, jadi semua pola harus lowercase.
+    Korpus sudah dinormalkan ke kebab-case (`surat-tugas`, `nota-dinas`).
+    """
+    haystack = path.replace("\\", "/").lower()
+    for pola, jenis in JENIS_RULES:
+        if re.search(pola, haystack):
+            return jenis
+    for pola, jenis in FOLDER_RULES:
+        if re.search(pola, haystack):
+            return jenis
+    return "Tidak Diketahui"
+
+
+def kumpulkan_pdf(root, mode):
+    """Kumpulkan daftar PDF sesuai mode uji."""
+    hasil = []
+
+    if mode in ("ocr", "semua"):
+        basis = os.path.join(root, "korpus", "scan-foto")
+        if os.path.isdir(basis):
+            for dirpath, _dirs, files in os.walk(basis):
+                for nama in sorted(files):
+                    if nama.lower().endswith(".pdf"):
+                        hasil.append(os.path.join(dirpath, nama))
+        elif not os.path.isdir(root):
+            pass
+        else:
+            print(f"[PERINGATAN] Folder tidak ada: {basis}", file=sys.stderr)
+
+    if mode in ("korpus", "semua"):
+        basis = os.path.join(root, "korpus", "text-layer")
+        if os.path.isdir(basis):
+            for dirpath, _dirs, files in os.walk(basis):
+                for nama in sorted(files):
+                    if nama.lower().endswith(".pdf"):
+                        hasil.append(os.path.join(dirpath, nama))
+
+    # Buang duplikat, pertahankan urutan
+    unik, terlihat = [], set()
+    for p in hasil:
+        kunci = os.path.abspath(p)
+        if kunci not in terlihat:
+            terlihat.add(kunci)
+            unik.append(p)
+    return unik
+
+
+def jenis_ke_kunci(jenis_label):
+    """
+    Petakan label jenis (untuk tampilan) ke jenis_dokumen kanonik yang dikenali
+    extract_dokumen.py. Ini penting: mengirim nama tampilan apa adanya akan
+    membuat Python menganggapnya "jenis tak dikenal" lalu mematikan penyaringan
+    KM — hasilnya bisa menyesatkan.
+
+    Label yang tidak punya padanan kanonik mengembalikan None (= tanpa filter),
+    dan itu memang yang diinginkan untuk folder campuran seperti Laporan/ yang
+    isinya termasuk Nota Dinas dan file Surat Tugas.
+    """
+    return {
+        "Notula": "notula",
+        "Surat Tugas": "surat_tugas",
+        "Surat Pemberitahuan UPT": "surat_pemberitahuan_upt",
+        "Laporan Hasil Pengawasan": "laporan",
+    }.get(jenis_label)
+
+
+def jalankan_ekstraktor(pdf_path, max_pages=0, jenis_dokumen=None):
+    """
+    Panggil extract_dokumen.py dan kembalikan (hasil, stats, durasi_dinding).
+
+    Stdout: payload JSON (daftar {jenis_item, nilai}).
+    Stderr: satu baris "STATS {...}" berisi instrumentasi halaman/waktu.
+
+    `jenis_dokumen` menentukan kode KM yang sah untuk Nomor Surat. Posisi
+    argumen bersifat tetap (<pdf> [max_pages] [jenis_dokumen]), jadi max_pages
+    selalu dikirim bila jenis_dokumen dikirim.
+    """
+    perintah = [sys.executable, EXTRACTOR, pdf_path]
+    if max_pages or jenis_dokumen:
+        perintah.append(str(max_pages))
+    if jenis_dokumen:
+        perintah.append(jenis_dokumen)
+
+    t0 = time.perf_counter()
+    proc = subprocess.run(
+        perintah, capture_output=True, text=True, encoding="utf-8", errors="replace"
+    )
+    durasi = time.perf_counter() - t0
+
+    # Stats dibaca dari stderr (prefix "STATS " sengaja tanpa '[' atau '{'
+    # agar tidak bentrok dengan deteksi payload JSON di sisi PHP).
+    stats = {}
+    m = re.search(r"^STATS\s*(\{.*\})\s*$", proc.stderr, re.MULTILINE)
+    if m:
+        try:
+            stats = json.loads(m.group(1))
+        except json.JSONDecodeError:
+            stats = {}
+
+    # Payload JSON: bersihkan baris STATS bila ikut terbawa di stdout.
+    stdout_bersih = re.sub(r"^STATS\s*\{.*\}\s*$", "", proc.stdout, flags=re.MULTILINE).strip()
+    try:
+        data = json.loads(stdout_bersih) if stdout_bersih else []
+        if isinstance(data, dict):  # payload error dari extractor
+            data = [data]
+    except json.JSONDecodeError:
+        data = [{"jenis_item": "ERROR", "nilai": stdout_bersih[:200]}]
+
+    return data, stats, durasi
+
+
+def pisahkan_hasil(data):
+    """Pisahkan daftar hasil menjadi (list NKU, list Nomor ST)."""
+    nku, st = [], []
+    for item in data:
+        if not isinstance(item, dict):
+            continue
+        if item.get("jenis_item") == "nku":
+            nku.append(item.get("nilai", ""))
+        elif item.get("jenis_item") == "nomor_st":
+            st.append(item.get("nilai", ""))
+    return nku, st
+
+
+def main():
+    parser = argparse.ArgumentParser(
+        description="Uji batch ekstraksi NKU & Nomor ST (PPBBR-SDP).",
+        formatter_class=argparse.RawDescriptionHelpFormatter,
+    )
+    parser.add_argument("--dir", default=DUMMY_SURAT,
+                        help=f"Folder root (default: {DUMMY_SURAT})")
+    parser.add_argument("--mode", choices=["ocr", "korpus", "semua"], default="ocr",
+                        help="Jenis korpus yang diuji (default: ocr)")
+    parser.add_argument("--file", default=None,
+                        help="Uji satu file PDF saja (mengabaikan --dir/--mode)")
+    parser.add_argument("--csv", action="store_true",
+                        help="Tulis CSV hasil ke dummySurat/03-hasil/")
+    parser.add_argument("--json", action="store_true",
+                        help="Cetak hasil lengkap sebagai JSON")
+    parser.add_argument("--max-pages", type=int, default=0,
+                        help="Batas halaman (0 = semua, default 0)")
+    parser.add_argument("--tanpa-filter-jenis", action="store_true",
+                        help="Jangan kirim jenis_dokumen ke ekstraktor (uji perilaku lama: tanpa filter KM)")
+    parser.add_argument("--quiet", action="store_true",
+                        help="Sembunyikan progres per file")
+    args = parser.parse_args()
+
+    if not os.path.exists(EXTRACTOR):
+        print(f"[FATAL] Skrip ekstraktor tidak ditemukan: {EXTRACTOR}", file=sys.stderr)
+        return 2
+
+    # Daftar file yang diuji
+    if args.file:
+        berkas = [args.file]
+        mode_label = "file"
+    else:
+        berkas = kumpulkan_pdf(args.dir, args.mode)
+        mode_label = args.mode
+
+    if not berkas:
+        print(f"[FATAL] Tidak ada PDF yang cocok (mode={mode_label}, dir={args.dir}).",
+              file=sys.stderr)
+        print("[INFO] Pastikan sampel sudah disalin ke",
+              "dummySurat/korpus/scan-foto/<jenis>/", file=sys.stderr)
+        return 1
+
+    if not args.quiet:
+        print(f"Uji ekstraksi — mode: {mode_label} | {len(berkas)} file | max_pages: "
+              f"{args.max_pages or 'semua'}")
+        print("=" * 100)
+        print(f"{'JENIS':<28} {'FILE':<40} {'WAKTU':>8} {'HAL':>4} {'OCR':>4} "
+              f"{'DETIK_OCR':>10} {'NKU':>4} {'ST':>3}")
+        print("-" * 100)
+
+    baris = []
+    total_mulai = time.perf_counter()
+
+    for pdf_path in berkas:
+        jenis = klasifikasi_jenis(pdf_path)
+        nama = os.path.basename(pdf_path)
+        # Kirim jenis_dokumen kanonik bila dikenal, agar penyaringan kode KM
+        # mencerminkan perilaku produksi (PHP kini mengirim parameter ini).
+        # None => tanpa penyaringan (untuk label campuran seperti "Laporan/").
+        kunci = None if args.tanpa_filter_jenis else jenis_ke_kunci(jenis)
+        data, stats, durasi = jalankan_ekstraktor(pdf_path, args.max_pages, kunci)
+        nku, st = pisahkan_hasil(data)
+
+        baris.append({
+            "jenis_dokumen": jenis,
+            "jenis_dokumen_dikirim": kunci or "(tanpa filter)",
+            "file": nama,
+            "path": pdf_path,
+            "waktu_total_s": round(durasi, 2),
+            "halaman": stats.get("pages_total", ""),
+            "halaman_native": stats.get("pages_native", ""),
+            "halaman_ocr": stats.get("pages_ocr", ""),
+            "halaman_ocr_skip": stats.get("pages_ocr_skipped", ""),
+            "detik_ocr": round(stats.get("ocr_seconds", 0.0), 2),
+            "detik_native": round(stats.get("native_seconds", 0.0), 3),
+            "jumlah_nku": len(nku),
+            "jumlah_st": len(st),
+            "nku": "; ".join(sorted(nku)),
+            "nomor_st": "; ".join(sorted(st)),
+        })
+
+        if not args.quiet:
+            print(f"{jenis[:28]:<28} {nama[:40]:<40} {durasi:7.2f}s "
+                  f"{stats.get('pages_total', 0):>4} {stats.get('pages_ocr', 0):>4} "
+                  f"{stats.get('ocr_seconds', 0.0):>9.2f}s {len(nku):>4} {len(st):>3}")
+
+    total_durasi = time.perf_counter() - total_mulai
+
+    # ── Ringkasan ───────────────────────────────────────────────────────────
+    n_file = len(baris)
+    ada_nku = sum(1 for b in baris if b["jumlah_nku"] > 0)
+    ada_st = sum(1 for b in baris if b["jumlah_st"] > 0)
+    ada_target = sum(1 for b in baris if b["jumlah_nku"] > 0 or b["jumlah_st"] > 0)
+    total_ocr_hal = sum(b["halaman_ocr"] for b in baris if isinstance(b["halaman_ocr"], int))
+    total_skip_hal = sum(b["halaman_ocr_skip"] for b in baris if isinstance(b["halaman_ocr_skip"], int))
+    total_detik_ocr = sum(b["detik_ocr"] for b in baris)
+    waktu_maks = max((b["waktu_total_s"] for b in baris), default=0.0)
+
+    if not args.quiet:
+        print("=" * 100)
+        print("RINGKASAN")
+        per_jenis = {}
+        for b in baris:
+            per_jenis.setdefault(b["jenis_dokumen"], []).append(b)
+        for jenis, items in sorted(per_jenis.items()):
+            nk = sum(i["jumlah_nku"] for i in items)
+            stc = sum(i["jumlah_st"] for i in items)
+            print(f"  {jenis:<30} {len(items):>3} file | NKU {nk:>3} | ST {stc:>3}")
+        print(f"  {'TOTAL':<30} {n_file:>3} file | "
+              f"{ada_target} file punya target | {n_file - ada_target} tanpa target")
+        print(f"  Halaman di-OCR      : {total_ocr_hal}  (dilewati: {total_skip_hal})")
+        print(f"  Total detik OCR     : {total_detik_ocr:.2f}s")
+        print(f"  Waktu total (wall)  : {total_durasi:.2f}s | rata-rata "
+              f"{total_durasi / n_file:.2f}s/file | maksimum {waktu_maks:.2f}s")
+        print("=" * 100)
+
+    # ── Tulis CSV ───────────────────────────────────────────────────────────
+    if args.csv:
+        out_dir = os.path.join(args.dir, "03-hasil")
+        os.makedirs(out_dir, exist_ok=True)
+        out_csv = os.path.join(out_dir, f"uji-ekstraksi-{mode_label}.csv")
+        kolom = ["jenis_dokumen", "jenis_dokumen_dikirim", "file", "waktu_total_s",
+                 "halaman", "halaman_native",
+                 "halaman_ocr", "halaman_ocr_skip", "detik_ocr", "detik_native",
+                 "jumlah_nku", "jumlah_st", "nku", "nomor_st"]
+        with open(out_csv, "w", newline="", encoding="utf-8") as f:
+            writer = csv.DictWriter(f, fieldnames=kolom, extrasaction="ignore")
+            writer.writeheader()
+            writer.writerows(baris)
+        print(f"[OK] CSV ditulis: {out_csv}")
+
+    if args.json:
+        print(json.dumps({
+            "mode": mode_label,
+            "jumlah_file": n_file,
+            "ringkasan": {
+                "file_punya_target": ada_target,
+                "file_tanpa_target": n_file - ada_target,
+                "halaman_ocr": total_ocr_hal,
+                "halaman_ocr_skip": total_skip_hal,
+                "detik_ocr_total": round(total_detik_ocr, 2),
+                "waktu_total_s": round(total_durasi, 2),
+                "waktu_maks_s": waktu_maks,
+            },
+            "hasil": baris,
+        }, indent=2, ensure_ascii=False))
+
+    return 0
+
+
+if __name__ == "__main__":
+    sys.exit(main())
