+#!/usr/bin/env python
+"""
+uji_regex_nku.py — Test regresi untuk regex & perakitan teks OCR pada
+ekstraktor PPBBR-SDP.
+
+Latar belakang (audit 2026-09-20, korpus scan/foto Wasrisk):
+  Dua bug ditemukan saat menguji 8 sampel tanpa text layer:
+    1. `\\b` menolak NKU yang menempel pada kata, karena OCR merekatkan kata
+       tanpa spasi (`...Proyek202604-1613-4114-5048-357dengan...`) dan digit
+       serta huruf sama-sama word-character.
+    2. Tabel kolom Notula memecah satu NKU menjadi dua baris, dan OCR
+       mengurutkan kolom secara vertikal sehingga `2026` menyela 21 digit.
+
+Test ini mengunci kedua perbaikan tersebut, sekaligus memastikan proteksi lama
+(menolak NKU yang menempel pada NIB / angka lebih panjang) tidak hilang.
+
+Jalankan:
+    python scripts/PPBBR/uji_regex_nku.py
+    # atau dengan venv khusus:
+    C:\\Users\\DATA-PSDKP\\.workbuddy-ai\\binaries\\python\\envs\\ppbbr\\Scripts\\python.exe \\
+        scripts/PPBBR/uji_regex_nku.py
+
+Tidak butuh RapidOCR — test ini murni regex & perakitan token, sehingga selesai
+dalam milidetik dan aman dijalankan di CI.
+"""
+
+import importlib.util
+import os
+import subprocess
+import sys
+
+# ── Muat extract_dokumen.py sebagai modul (namanya tidak bisa di-import biasa) ──
+_HERE = os.path.dirname(os.path.abspath(__file__))
+_SPEC = importlib.util.spec_from_file_location(
+    "extract_dokumen", os.path.join(_HERE, "extract_dokumen.py")
+)
+mod = importlib.util.module_from_spec(_SPEC)
+_SPEC.loader.exec_module(mod)
+
+_gagal = 0
+
+
+def bx(teks):
+    """Bentuk box RapidOCR: [titik_poligon, teks, skor]."""
+    return [[[0, 0], [1, 0], [1, 1], [0, 1]], teks, 0.99]
+
+
+def cek(label, dapat, harap):
+    global _gagal
+    ok = sorted(dapat) == sorted(harap)
+    if not ok:
+        _gagal += 1
+    print(f"  [{'OK   ' if ok else 'GAGAL'}] {label}")
+    if not ok:
+        print(f"          dapat : {sorted(dapat)}")
+        print(f"          harap : {sorted(harap)}")
+
+
+def nku_dari(teks):
+    return [mod.format_nku(m) for m in mod.nku_pattern.findall(teks)]
+
+
+def main():
+    print("=== A. nku_pattern: kasus yang harus TETAP DITOLAK (proteksi lama \\b) ===")
+    for label, teks in [
+        ("NIB 13 digit menempel NKU", "NIB9120409862709202604-1613-4114-5048-357 terdaftar"),
+        ("angka 22 digit", "nomor 12023112316404769782090 salah"),
+        ("angka 20 digit", "nomor 1202311231640476978209 kurang"),
+    ]:
+        cek(label, nku_dari(teks), [])
+
+    print("\n=== B. nku_pattern: kasus yang harus DITERIMA ===")
+    for label, teks, harap in [
+        ("normal berspasi", "NKU : 202311-2316-4047-6978-209 di sistem",
+         ["202311-2316-4047-6978-209"]),
+        ("tanpa strip", "NKU 202311231640476978209 diterbitkan",
+         ["202311-2316-4047-6978-209"]),
+        ("menempel kata (bug OCR lama)",
+         "NomorKodeProyek202604-1613-4114-5048-357dengan50142AngkutanLaut",
+         ["202604-1613-4114-5048-357"]),
+    ]:
+        cek(label, nku_dari(teks), harap)
+
+    print("\n=== C. collect_matches_from_ocr: tabel kolom Notula ===")
+    # Urutan box meniru keluaran RapidOCR pada tabel 2-baris per NKU:
+    # baris NKU (kolom kiri+tengah) lalu baris tanggal batas laporan (kanan).
+    kotak = [
+        bx("2."), bx("PT MULTI"), bx("202412-0523-"),
+        bx("03111"), bx("Penangakapan"), bx("11 Agustus"),
+        bx("Pisces/lkan"), bx("SAMUDERA"), bx("0521-2732-281"),
+        bx("2026"), bx("FISHINDO"),
+    ]
+    nku, st = set(), set()
+    mod.collect_matches_from_ocr(kotak, nku, st)
+    cek("NKU pulih dari tabel kolom", nku, {"202412-0523-0521-2732-281"})
+    cek("tidak ada Nomor ST palsu", st, set())
+
+    print("\n=== D. collect_matches_from_ocr: NKU menempel di tengah kalimat ===")
+    nku, st = set(), set()
+    mod.collect_matches_from_ocr(
+        [bx("denganNomorKodeProyek202604-1613-4114-5048-357dengan50142AngkutanLaut")],
+        nku, st,
+    )
+    cek("NKU pulih", nku, {"202604-1613-4114-5048-357"})
+
+    print("\n=== E. collect_matches_from_ocr: NKU + Nomor ST (Surat Tugas) ===")
+    nku, st = set(), set()
+    mod.collect_matches_from_ocr([
+        bx("B.2127/PSDKPLan.6/KP.440/IX/2026"),
+        bx("202412-1008-5000-9719-782"),
+        bx("202312-2111-1350-3448-025"),
+    ], nku, st)
+    cek("NKU", nku, {"202412-1008-5000-9719-782", "202312-2111-1350-3448-025"})
+    cek("Nomor ST", st, {"B.2127/PSDKPLan.6/KP.440/IX/2026"})
+
+    print("\n=== F. Penyaringan kode KM per jenis dokumen ===")
+    # Sumber kebenaran: KM_PER_JENIS di KorespondensiCRSService.php:41
+    kasus_km = [
+        # (nomor_surat, jenis_dokumen, harus_diterima, keterangan)
+        ("B.2127/PSDKPLan.6/KP.440/IX/2026", "surat_tugas", True,
+         "Surat Tugas memakai KP.440"),
+        ("B.2801/PSDKPLan.3/PW.110/VII/2026", "surat_tugas", False,
+         "PW.110 bukan kode Surat Tugas"),
+        ("B.2801/PSDKPLan.3/PW.110/VII/2026", "laporan", True,
+         "PW.110 sah untuk laporan"),
+        ("B.2801/PSDKPLan.3/PW.110/VII/2026", "surat_pemberitahuan_upt", False,
+         "PW.110 tidak ada di daftar SP UPT"),
+        ("1860/PSDKPLan.5/PW.150/VIII/2026", "surat_pemberitahuan_upt", True,
+         "PW.150 sah untuk SP UPT"),
+        ("1084/PSDKPLan.2/PW.240/VII/2026", "laporan", True,
+         "PW.240 sah untuk laporan (varian tanpa spasi)"),
+        ("1084/PSDKPLan.2/PW.150/VII/2026", "laporan", False,
+         "PW.150 TIDAK ada di daftar laporan (sesuai KM_PER_JENIS)"),
+        ("B.2127/PSDKPLan.6/KP.440/IX/2026", None, True,
+         "tanpa jenis dokumen -> tidak difilter"),
+        ("123/PSDKPLan.1/XX.999/I/2026", None, True,
+         "tanpa jenis dokumen -> kode asing tetap diterima"),
+        ("123/PSDKPLan.1/XX.999/I/2026", "surat_tugas", False,
+         "dengan jenis dokumen -> kode asing ditolak"),
+        # Alias & anti-silent-regression
+        ("B.2801/PSDKPLan.3/PW.150/VII/2026", "sp_upt", True,
+         "alias 'sp_upt' dipetakan ke surat_pemberitahuan_upt"),
+        ("B.2801/PSDKPLan.3/PW.150/VII/2026", "SP UPT", True,
+         "nama jenis tidak peka huruf besar/kecil"),
+        ("B.2127/PSDKPLan.6/KP.440/IX/2026", "SURAT_TUGAS", True,
+         "nama jenis huruf kapital tetap dikenali"),
+        ("123/PSDKPLan.1/XX.999/I/2026", "entah_apa", True,
+         "jenis tak dikenal -> meloloskan (jangan hapus data tanpa peringatan)"),
+        ("B.2801/PSDKPLan.3/PW.150/VII/2026", "lhp", False,
+         "alias 'lhp' -> laporan (PW.150 bukan kode laporan)"),
+    ]
+    for nomor, jenis, harus, keterangan in kasus_km:
+        dapat = mod.km_diterima(mod.format_st(nomor), jenis)
+        cek(f"{keterangan} [{jenis}]", [dapat], [harus])
+
+    print("\n=== F2. Nomor Surat dengan bulan Romawi rusak (bug OCR) harus LOLOS ===")
+    # 'VIl' = V-I-l (huruf L kecil), hasil salah baca OCR atas 'VII'.
+    nku, st = set(), set()
+    mod.collect_matches_from_ocr(
+        [bx(":B.2801/PSDKPLan.3/PW.150/VIl/2026")], nku, st, "surat_pemberitahuan_upt"
+    )
+    cek("SP UPT: bulan rusak dinormalisasi & lolos",
+        st, {"B.2801/PSDKPLan.3/PW.150/VII/2026"})
+
+    # Tanpa normalisasi, nilai 'VIl' akan tersimpan apa adanya.
+    nku, st = set(), set()
+    mod.collect_matches_from_ocr([bx("456/PSDKPLan.2/PW.130/1X/2026")], nku, st, "surat_pemberitahuan_upt")
+    cek("digit '1' pada bulan dinormalisasi", st, {"456/PSDKPLan.2/PW.130/IX/2026"})
+
+    # Kode yang sama tetap ditolak bila konteksnya Surat Tugas.
+    nku, st = set(), set()
+    mod.collect_matches_from_ocr(
+        [bx(":B.2801/PSDKPLan.3/PW.150/VII/2026")], nku, st, "surat_tugas"
+    )
+    cek("PW.150 ditolak pada konteks Surat Tugas", st, set())
+
+    print("\n=== G. Input kosong / None tidak error ===")
+    nku, st = set(), set()
+    mod.collect_matches_from_ocr([], nku, st)
+    mod.collect_matches_from_ocr(None, nku, st)
+    cek("input kosong aman", list(nku) + list(st), [])
+
+    print("\n=== H. Argumen salah posisi harus BERSUARA, bukan diam ===")
+    # Kasus nyata: jenis_dokumen ditaruh di slot max_pages. CLI lama menelan
+    # ValueError dan memakai 0 tanpa pesan -> dokumen diproses penuh TANPA
+    # penyaringan KM, dan tidak ada indikasi apa pun. Itu kelas bug senyap.
+    # Peringatan TIDAK boleh memuat '[' atau '{', karena PHP menggabungkan
+    # stdout+stderr (2>&1) dan heuristik deteksi payload JSON bisa tersandung.
+    hasil = subprocess.run(
+        [sys.executable, os.path.join(_HERE, "extract_dokumen.py"),
+         "berkas_tidak_ada.pdf", "surat_tugas"],
+        capture_output=True, text=True, encoding="utf-8", errors="replace",
+    )
+    gabungan = hasil.stdout + hasil.stderr
+
+    cek("argumen salah posisi memunculkan PERINGATAN",
+        ["ada" if "PERINGATAN" in gabungan else "tidak ada"], ["ada"])
+    cek("peringatan menyebut 'SALAH POSISI'",
+        ["ada" if "SALAH POSISI" in gabungan else "tidak ada"], ["ada"])
+
+    baris_peringatan = [b for b in gabungan.splitlines() if "PERINGATAN" in b]
+    cek("baris PERINGATAN tidak memuat '{' atau '[' (aman untuk 2>&1 PHP)",
+        [b for b in baris_peringatan if "{" in b or "[" in b], [])
+
+    # Regression NYATA: versi pertama peringatan memakai prefiks '[PERINGATAN]'.
+    # Tanda '[' itu membuat decodeJsonPayload() PHP menemukan '[' yang salah,
+    # lalu membuang seluruh output sebagai "bukan JSON yang valid" — ekstraksi
+    # gagal total hanya karena sebuah pesan peringatan. Test ini mengunci agar
+    # tidak terulang: payload HARUS tetap terbaca meski ada peringatan.
+    import json as _json
+    import re as _re
+
+    def _pisahkan_statistik(output):
+        m = _re.search(r"^STATS\s*(\{.*\})\s*$", output, _re.MULTILINE)
+        if not m:
+            return output
+        return output.replace(m.group(0), "").strip()
+
+    def _decode_json_payload(output):
+        """Tiruan decodeJsonPayload() PHP: langsung -> per baris -> scan '[' / '{'."""
+        teks = output.strip()
+        if teks:
+            try:
+                d = _json.loads(teks)
+                if isinstance(d, (list, dict)):
+                    return d
+            except Exception:
+                pass
+        for baris in _re.split(r"\r?\n", teks):
+            baris = baris.strip()
+            if not baris:
+                continue
+            try:
+                d = _json.loads(baris)
+                if isinstance(d, (list, dict)):
+                    return d
+            except Exception:
+                pass
+        for pembuka in ("[", "{"):
+            offset = 0
+            while offset < len(teks):
+                s = teks.find(pembuka, offset)
+                if s == -1:
+                    break
+                try:
+                    d = _json.loads(teks[s:])
+                    if isinstance(d, (list, dict)):
+                        return d
+                except Exception:
+                    pass
+                offset = s + 1
+        raise ValueError("bukan JSON yang valid")
+
+    # Output nyata yang dilihat PHP: stdout + stderr digabung.
+    gabungan_penuh = hasil.stdout + "\n" + hasil.stderr
+    try:
+        _decode_json_payload(_pisahkan_statistik(gabungan_penuh))
+        pesan = "terbaca"
+    except Exception:
+        pesan = "GAGAL DIBACA"
+
+    cek("PHP masih bisa membaca payload meski ada PERINGATAN",
+        [pesan], ["terbaca"])
+
+    print()
+    if _gagal:
+        print(f"### {_gagal} KASUS GAGAL ###")
+        return 1
+    print("### SEMUA KASUS LULUS ###")
+    return 0
+
+
+if __name__ == "__main__":
+    sys.exit(main())
