+<?php
+
+namespace Tests\Unit\PengawasanPerizinanBerusaha;
+
+use App\Services\PengawasanPerizinanBerusaha\EkstrakDokumenService;
+use Tests\TestCase;
+
+/**
+ * Menguji parsing output script Python pada EkstrakDokumenService.
+ *
+ * Konteks: script `scripts/PPBBR/extract_dokumen.py` menulis baris diagnostik
+ * `STATS {...}` ke stderr, sementara payload JSON ditulis ke stdout. Karena
+ * dipanggil dengan `2>&1`, kedua stream tergabung sebelum sampai ke PHP —
+ * sehingga urutan keluaran TIDAK bisa diandalkan.
+ *
+ * Test ini mengunci perilaku `pisahkanStatistik()` + `decodeJsonPayload()`
+ * agar regresi tidak lolos, khususnya kasus baris STATS yang mendahului
+ * payload (yang sebelumnya menyebabkan `Extra data: line N column 1`).
+ *
+ * Tidak menyentuh database — cukup instansiasi service.
+ */
+class EkstrakDokumenParsingTest extends TestCase
+{
+    private EkstrakDokumenService $service;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+        $this->service = new EkstrakDokumenService();
+    }
+
+    /** Membuka protected pisahkanStatistik() untuk pengujian. */
+    private function pisahkan(string $output): string
+    {
+        $ref = new \ReflectionMethod(EkstrakDokumenService::class, 'pisahkanStatistik');
+
+        return $ref->invoke($this->service, $output);
+    }
+
+    /** Membuka protected decodeJsonPayload() untuk pengujian. */
+    private function decode(string $output): array
+    {
+        $ref = new \ReflectionMethod(EkstrakDokumenService::class, 'decodeJsonPayload');
+
+        return $ref->invoke($this->service, $output);
+    }
+
+    /** @test */
+    public function memisahkan_baris_stats_yang_mendahului_payload()
+    {
+        // Bentuk nyata: STATS {...} muncul lebih dulu, payload menyusul.
+        // Parser lama gagal di sini karena '{' pada baris STATS dianggap
+        // awal payload sehingga json_decode error "Extra data".
+        $output = "STATS {\"pages_total\":4,\"pages_ocr\":0,\"total_seconds\":0.022}\n"
+            . "[\n    {\n        \"jenis_item\": \"nku\",\n        \"nilai\": \"202412-0523-0521-2732-281\"\n    }\n]";
+
+        $payload = $this->pisahkan($output);
+        $hasil = $this->decode($payload);
+
+        $this->assertCount(1, $hasil);
+        $this->assertEquals('nku', $hasil[0]['jenis_item']);
+        $this->assertEquals('202412-0523-0521-2732-281', $hasil[0]['nilai']);
+    }
+
+    /** @test */
+    public function mengekstrak_stats_ke_statistik_terakhir()
+    {
+        $output = "STATS {\"pages_total\":6,\"pages_native\":6,\"pages_ocr\":0,"
+            . "\"pages_ocr_skipped\":1,\"ocr_seconds\":0.0,\"native_seconds\":0.009,"
+            . "\"total_seconds\":0.045}\n[]";
+
+        $this->pisahkan($output);
+
+        $stats = $this->service->statistikTerakhir();
+
+        $this->assertEquals(6, $stats['pages_total']);
+        $this->assertEquals(0, $stats['pages_ocr']);
+        $this->assertEquals(1, $stats['pages_ocr_skipped']);
+        $this->assertEquals(0.045, $stats['total_seconds']);
+    }
+
+    /** @test */
+    public function menangani_hasil_ekstraksi_kosong()
+    {
+        $hasil = $this->decode($this->pisahkan("STATS {\"pages_total\":1}\n[]"));
+
+        $this->assertIsArray($hasil);
+        $this->assertCount(0, $hasil);
+    }
+
+    /** @test */
+    public function payload_error_tetap_terbaca_sebagai_array()
+    {
+        // json_decode($x, true) mengembalikan array untuk {} maupun [],
+        // sehingga isset($result['error']) tetap bekerja seperti sebelumnya.
+        $hasil = $this->decode(
+            $this->pisahkan("STATS {\"pages_total\":0}\n{\"error\": \"File not found: x.pdf\"}")
+        );
+
+        $this->assertArrayHasKey('error', $hasil);
+        $this->assertEquals('File not found: x.pdf', $hasil['error']);
+    }
+
+    /** @test */
+    public function kompatibel_dengan_output_lama_tanpa_baris_stats()
+    {
+        // Output versi lama: tanpa STATS. Harus tetap parse seperti semula.
+        $output = "[\n    {\n        \"jenis_item\": \"nomor_st\",\n"
+            . "        \"nilai\": \"B.1/PSDKPLan/KP.440/IX/2026\"\n    }\n]";
+
+        $hasil = $this->decode($this->pisahkan($output));
+
+        $this->assertCount(1, $hasil);
+        $this->assertEquals('B.1/PSDKPLan/KP.440/IX/2026', $hasil[0]['nilai']);
+    }
+
+    /** @test */
+    public function stats_di_posisi_akhir_tetap_terpisah()
+    {
+        $output = "[]\nSTATS {\"total_seconds\":9.9}";
+
+        $hasil = $this->decode($this->pisahkan($output));
+
+        $this->assertCount(0, $hasil);
+        $this->assertEquals(9.9, $this->service->statistikTerakhir()['total_seconds']);
+    }
+
+    /** @test */
+    public function kurung_di_dalam_string_tidak_merusak_parsing()
+    {
+        $payload = "[{\"jenis_item\":\"nku\",\"nilai\":\"a{b}c[1]\"}]";
+
+        $hasil = $this->decode($this->pisahkan("STATS {\"x\":1}\n" . $payload));
+
+        $this->assertCount(1, $hasil);
+        $this->assertEquals('a{b}c[1]', $hasil[0]['nilai']);
+    }
+
+    /** @test */
+    public function output_tanpa_json_melempar_exception()
+    {
+        $this->expectException(\Exception::class);
+
+        $this->decode($this->pisahkan("bukan json sama sekali"));
+    }
+
+    /**
+     * Merakit perintah seperti yang dilakukan ekstrakViaPython().
+     *
+     * Logika ini digandakan di sini dengan sengaja: yang diuji adalah
+     * KONTRAK POSISI ARGUMEN, bukan implementasi. Bila urutan argumen di
+     * service berubah, test ini akan gagal — dan itu memang tujuannya.
+     */
+    private function rakitPerintah(string $pdf, int $maxPages, ?string $jenisDokumen): string
+    {
+        $cmd = 'python extract_dokumen.py ' . escapeshellarg($pdf);
+
+        if ($maxPages > 0 || $jenisDokumen !== null) {
+            $cmd .= ' ' . escapeshellarg((string) $maxPages);
+        }
+        if ($jenisDokumen !== null) {
+            $cmd .= ' ' . escapeshellarg($jenisDokumen);
+        }
+
+        return $cmd;
+    }
+
+    /** @test */
+    public function pemanggil_lama_tanpa_jenis_dokumen_tidak_berubah()
+    {
+        // Kompatibilitas mundur: pemanggil lama hanya kirim <pdf>.
+        $cmd = $this->rakitPerintah('/tmp/a.pdf', 0, null);
+
+        $this->assertEquals("python extract_dokumen.py '/tmp/a.pdf'", $cmd);
+    }
+
+    /** @test */
+    public function pemanggil_lama_dengan_max_pages_tidak_berubah()
+    {
+        // Bentuk lama (laporan): <pdf> <max_pages>, tanpa argumen ketiga.
+        $cmd = $this->rakitPerintah('/tmp/a.pdf', 1, null);
+
+        $this->assertEquals("python extract_dokumen.py '/tmp/a.pdf' '1'", $cmd);
+    }
+
+    /** @test */
+    public function max_pages_tetap_diisi_bila_jenis_dokumen_dikirim()
+    {
+        // Kritis: bila max_pages dilewati, 'surat_tugas' akan bergeser ke slot
+        // max_pages lalu di-parse Python sebagai int -> crash / salah tafsir.
+        $cmd = $this->rakitPerintah('/tmp/a.pdf', 0, 'surat_tugas');
+
+        $this->assertEquals(
+            "python extract_dokumen.py '/tmp/a.pdf' '0' 'surat_tugas'",
+            $cmd
+        );
+    }
+
+    /** @test */
+    public function jenis_dokumen_berada_setelah_max_pages()
+    {
+        // Kontrak posisi: <pdf> [max_pages] [jenis_dokumen]
+        $cmd = $this->rakitPerintah('/tmp/a.pdf', 1, 'laporan');
+        $posisi = explode("'", $cmd);
+
+        // ['python extract_dokumen.py ', '/tmp/a.pdf', ' ', '1', ' ', 'laporan', '']
+        $this->assertEquals('/tmp/a.pdf', $posisi[1]);
+        $this->assertEquals('1', $posisi[3]);
+        $this->assertEquals('laporan', $posisi[5]);
+    }
+
+    /** @test */
+    public function seluruh_jenis_dokumen_yang_valid_dapat_dikirim()
+    {
+        // Keempat nilai ini adalah yang diizinkan EkstrakDokumenRequest.
+        // Bila salah satunya tidak lagi diterima endpoint, test ini menandai.
+        foreach (['notula', 'surat_tugas', 'surat_pemberitahuan_upt', 'laporan'] as $jenis) {
+            $cmd = $this->rakitPerintah('/tmp/a.pdf', 0, $jenis);
+
+            $this->assertStringEndsWith("'{$jenis}'", $cmd);
+        }
+    }
+
+    /** @test */
+    public function path_berisi_spasi_tetap_ter-escape()
+    {
+        // Path dokumen berasal dari storage dan bisa memuat spasi.
+        $cmd = $this->rakitPerintah('/tmp/berkas scan.pdf', 0, 'notula');
+
+        $this->assertStringContainsString("'/tmp/berkas scan.pdf'", $cmd);
+        $this->assertStringEndsWith("'notula'", $cmd);
+    }
+
+    /** @test */
+    public function payload_array_yang_didahului_teks_masih_terbaca()
+    {
+        // stderr dan stdout bisa tercampur dalam urutan apa pun karena `2>&1`.
+        // Peringatan Python mendahului payload -> harus tetap terbaca.
+        $output = "PERINGATAN: sesuatu terjadi\n"
+            . "[\n    {\n        \"jenis_item\": \"nku\",\n        \"nilai\": \"x\"\n    }\n]";
+
+        $hasil = $this->decode($this->pisahkan($output));
+
+        $this->assertCount(1, $hasil);
+        $this->assertEquals('nku', $hasil[0]['jenis_item']);
+    }
+
+    /** @test */
+    public function payload_error_yang_diikuti_teks_masih_terbaca()
+    {
+        // REGRESI PENTING. Payload error berupa OBJEK, bukan array. Fallback
+        // lama hanya mencari '[' sehingga objek yang diikuti teks apa pun
+        // (mis. pesan peringatan Python) gagal dipulihkan -> seluruh ekstraksi
+        // dianggap "bukan JSON yang valid", padahal payloadnya baik-baik saja.
+        $output = "{\"error\": \"File not found: x.pdf\"}\n\n"
+            . "PERINGATAN: argumen max_pages tidak valid -> dipakai 0.";
+
+        $hasil = $this->decode($this->pisahkan($output));
+
+        $this->assertArrayHasKey('error', $hasil);
+        $this->assertEquals('File not found: x.pdf', $hasil['error']);
+    }
+
+    /** @test */
+    public function teks_bukan_json_tetap_melempar_exception()
+    {
+        // Jangan sampai fallback yang lebih longgar menelan teks sampah.
+        $this->expectException(\Exception::class);
+
+        $this->decode($this->pisahkan("PERINGATAN: tidak ada payload JSON di sini"));
+    }
+}

