+     */
+    public function scopePraInspeksi(\Illuminate\Database\Eloquent\Builder $query): \Illuminate\Database\Eloquent\Builder
+    {
+        return $query->whereIn('status', self::STATUS_PRA_INSPEKSI);
+    }
+
+    /**
+     * Objek yang inspeksinya sudah tuntas (laporan diunggah pasca-inspeksi).
+     */
+    public function scopeSelesai(\Illuminate\Database\Eloquent\Builder $query): \Illuminate\Database\Eloquent\Builder
+    {
+        return $query->where('status', self::Selesai);
+    }
