+        ]);
+
+        $isPengelolaPusat = $this->findRoleName('Pengelola Modul Wasrisk') && $this->jenisUnit() !== 'UPT';
+
+        // Operator Pusat, Admin, dan Pengelola Modul Pusat bebas akses semua data.
+        if ($isOperatorPusat || $isAdmin || $isPengelolaPusat) {
+            return $query;
+        }
+
+        // --- DI BAWAH SINI PASTI BUKAN PUSAT ---
+        $user = auth()->user();
