+use Spatie\Permission\Models\Role;
+use Tests\TestCase;
+
+/**
+ * Menguji scope ObjekPengawasan::dalamKewenangan().
+ *
+ * Scope ini adalah SUMBER KEBENARAN TUNGGAL penyaringan peran: dipakai
+ * PenjadwalanService (pencocokan hasil ekstrak) DAN resource hasil inspeksi
+ * lapangan. Sebelum dipindahkan ke model, logika yang sama hidup sebagai
+ * method privat di beberapa service, sehingga pemanggil lain bisa melewatinya
+ * hanya dengan mengirim queryBase = null (objek di luar kewenangan ikut
+ * tercocokkan / terlihat).
+ */
+class ObjekPengawasanKewenanganScopeTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    private UnitKerja $unitA;
+    private UnitKerja $unitB;
+
+    protected function setUp(): void
+    {
+        parent::setUp();
+
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        $this->unitA = $this->buatUnitKerja('UPT A');
+        $this->unitB = $this->buatUnitKerja('UPT B');
+    }
+
+    private function buatUnitKerja(string $akronim): UnitKerja
+    {
+        $kode = 'U-' . rand(100000, 999999);
+
+        return UnitKerja::create([
+            'kode_unit' => $kode,
+            'nama_unit' => 'Test Unit ' . $akronim,
+            'nama_akronim' => $akronim,
+            'kategori_unit' => 'UPT',
+        ]);
+    }
+
+    private function buatObjek(string $kodeUnit): ObjekPengawasan
+    {
+        return ObjekPengawasanFactory::new()->create([
+            'status' => ObjekPengawasan::MenungguInspeksi,
+            'unit_kerja' => $kodeUnit,
+        ]);
+    }
+
+    /**
+     * Membuat user + pegawai + role, lalu login.
+     *
+     * @return array{0: User, 1: PegawaiInternal}
+     */
+    private function loginSebagai(string $roleName, UnitKerja $unit): array
+    {
+        Role::firstOrCreate(['name' => $roleName, 'guard_name' => 'api']);
+
+        $user = User::create([
+            'username' => 'uji_' . uniqid(),
+            'password' => bcrypt('password'),
+        ]);
+        $user->assignRole($roleName);
+
+        $pegawai = PegawaiInternal::create([
+            'nip' => 'NIP' . rand(10000, 99999),
+            'nama_pegawai' => 'Pegawai ' . $roleName,
+            'unit_kerja_id' => $unit->kode_unit,
+            'user_id' => $user->id,
+        ]);
+
+        $user->pegint_id = $pegawai->nip;
+        $user->save();
+
+        Auth::login($user);
+
+        return [$user, $pegawai];
+    }
+
+    /** @test */
+    public function operator_pusat_wasrisk_melihat_semua_objek()
+    {
+        $objekA = $this->buatObjek($this->unitA->kode_unit);
+        $objekB = $this->buatObjek($this->unitB->kode_unit);
+
+        $this->loginSebagai('Operator Pusat WasRisk', $this->unitA);
+
+        $ids = ObjekPengawasan::query()->dalamKewenangan()->pluck('id')->all();
+
+        $this->assertContains($objekA->id, $ids);
+        $this->assertContains($objekB->id, $ids);
+    }
+
+    /** @test */
+    public function superuser_melihat_semua_objek()
+    {
+        $objekB = $this->buatObjek($this->unitB->kode_unit);
+
+        $this->loginSebagai('Superuser', $this->unitA);
+
+        $ids = ObjekPengawasan::query()->dalamKewenangan()->pluck('id')->all();
+
+        $this->assertContains($objekB->id, $ids);
+    }
+
+    /** @test */
+    public function operator_upt_wasrisk_hanya_melihat_objek_unit_kerjanya()
+    {
+        $objekA = $this->buatObjek($this->unitA->kode_unit);
+        $objekB = $this->buatObjek($this->unitB->kode_unit);
+
+        $this->loginSebagai('Operator UPT WasRisk', $this->unitA);
+
+        $ids = ObjekPengawasan::query()->dalamKewenangan()->pluck('id')->all();
+
+        $this->assertContains($objekA->id, $ids, 'objek se-unit harus terlihat');
+        $this->assertNotContains($objekB->id, $ids, 'objek unit lain tidak boleh terlihat');
+    }
+
+    /** @test */
+    public function pengawas_perikanan_hanya_melihat_objek_yang_ditugaskan_atau_tanpa_pengawas()
+    {
+        [, $pegawai] = $this->loginSebagai('Pengawas Perikanan JF', $this->unitA);
+
+        $objekDitugaskan = $this->buatObjek($this->unitA->kode_unit);
+        $objekPengawasLain = $this->buatObjek($this->unitA->kode_unit);
+        $objekTanpaPengawas = $this->buatObjek($this->unitA->kode_unit);
+        $objekUnitLain = $this->buatObjek($this->unitB->kode_unit);
+
+        PengawasInspeksiLapangan::create([
+            'objek_pengawasan_id' => $objekDitugaskan->id,
+            'nip' => $pegawai->nip,
+        ]);
+        PengawasInspeksiLapangan::create([
+            'objek_pengawasan_id' => $objekPengawasLain->id,
+            'nip' => 'NIP-LAIN-99999',
+        ]);
+
+        $ids = ObjekPengawasan::query()->dalamKewenangan()->pluck('id')->all();
+
+        $this->assertContains($objekDitugaskan->id, $ids, 'objek yang ditugaskan ke pengawas ini harus terlihat');
+        $this->assertContains($objekTanpaPengawas->id, $ids, 'objek belum ber-pengawas harus tetap terlihat');
+        $this->assertNotContains($objekPengawasLain->id, $ids, 'objek milik pengawas lain tidak boleh terlihat');
+        $this->assertNotContains($objekUnitLain->id, $ids, 'objek unit lain tidak boleh terlihat');
+    }
+
+    /** @test */
+    public function operator_upt_yang_juga_pengawas_tidak_ikut_disaring_nip()
+    {
+        // Operator UPT boleh merangkap Pengawas Perikanan. Karena dia operator,
+        // penyaringan NIP TIDAK boleh berlaku — kalau berlaku, objek yang
+        // ditugaskan ke pengawas lain di unitnya jadi tidak terlihat.
+        [$user] = $this->loginSebagai('Operator UPT WasRisk', $this->unitA);
+        Role::firstOrCreate(['name' => 'Pengawas Perikanan JF', 'guard_name' => 'api']);
+        $user->assignRole('Pengawas Perikanan JF');
+
+        $objekPengawasLain = $this->buatObjek($this->unitA->kode_unit);
+        PengawasInspeksiLapangan::create([
+            'objek_pengawasan_id' => $objekPengawasLain->id,
+            'nip' => 'NIP-LAIN-99999',
+        ]);
+
+        $ids = ObjekPengawasan::query()->dalamKewenangan()->pluck('id')->all();
+
+        $this->assertContains($objekPengawasLain->id, $ids);
+    }
+
+    /** @test */
+    public function tanpa_login_scope_menutup_akses()
+    {
+        // Fail-closed: tanpa user, penyaringan unit_kerja menjadi `is null`
+        // sehingga objek milik unit mana pun tidak ikut terbawa. Ini yang
+        // membuat pengiriman queryBase = null tidak lagi membuka seluruh data.
+        $this->buatObjek($this->unitA->kode_unit);
+        $this->buatObjek($this->unitB->kode_unit);
+
+        $this->assertNull(auth()->user());
+
+        $this->assertSame(0, ObjekPengawasan::query()->dalamKewenangan()->count());
+    }
+}

