+    /**
+     * Kirim WA dengan fitur Sleep Drip (Delay acak per user) untuk menghindari spam
+     *
+     * @param array $numbers
+     * @param string $message
+     * @param mixed|null $notifiable
+     * @param int $maxDelay
+     * @return array
+     */
+    public static function sendSleepDrip(array $numbers, $message, $notifiable = null, $maxDelay = 240)
+    {
+        $responses = [];
+        foreach ($numbers as $number) {
+            if (!empty($number)) {
+                // Generate random delay antara 2 detik hingga $maxDelay
+                $randomDelay = rand(2, $maxDelay);
+
+                try {
+                    $responses[] = self::send($number, $message, $notifiable, $randomDelay);
+                } catch (\Exception $e) {
+                    Log::error("Gagal kirim WA (Sleep Drip) ke {$number}: " . $e->getMessage());
+                }
+            }
+        }
+        return $responses;
+    }
