+<?php
+
+namespace App\Console\Commands\Master;
+
+use App\Services\Master\HariLiburNasionalService;
+use Illuminate\Console\Command;
+
+class SyncHariLiburCommand extends Command
+{
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'master:sync-hari-libur {tahun? : Tahun SKB yang disinkron (default tahun berjalan)} {--tahun-depan : Sinkron juga tahun depan (untuk SKB yang terbit Sep-Des)}';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Sinkronisasi hari libur nasional dari SKB (kemendesa.link primer, api.co.id fallback) ke tabel lokal.';
+
+    /**
+     * Execute the console command.
+     */
+    public function handle(): int
+    {
+        $service = new HariLiburNasionalService();
+
+        $tahuns = [(int) ($this->argument('tahun') ?? date('Y'))];
+        if ($this->option('tahun-depan')) {
+            $tahuns[] = end($tahuns) + 1;
+        }
+
+        foreach (array_unique($tahuns) as $tahun) {
+            $baru = $service->syncTahun($tahun);
+            $this->info("Tahun {$tahun}: sinkron selesai (+{$baru} baris baru).");
+        }
+
+        return Command::SUCCESS;
+    }
+}
