diff --git a/app/Services/Master/HariLiburNasionalService.php b/app/Services/Master/HariLiburNasionalService.php
new file mode 100644
index 000000000..50cec961f
--- /dev/null
+++ b/app/Services/Master/HariLiburNasionalService.php
@@ -0,0 +1,161 @@
+<?php
+
+namespace App\Services\Master;
+
+use Carbon\Carbon;
+use App\Models\Master\HariLiburNasional;
+use Illuminate\Support\Facades\Cache;
+use Illuminate\Support\Facades\Http;
+use Illuminate\Support\Facades\Log;
+
+/**
+ * Layanan shared Hari Libur Nasional.
+ *
+ * Satu pintu untuk sinkronisasi (SKB) dan pembacaan tanggal libur,
+ * dipakai lintas fitur (LHP, penjadwalan, dsb.) agar tidak ada
+ * query/cache per fitur. Cache key generik milik Master.
+ */
+class HariLiburNasionalService
+{
+    public const CACHE_PREFIX = 'master:libur-nasional';
+
+    /**
+     * Sinkronisasi hari libur suatu tahun: primer kemendesa.link (SKB,
+     * tanpa key), sekunder api.co.id bila primer gagal/kosong.
+     * Gagal diam-diam (log saja) agar tidak mengganggu perhitungan
+     * deadline yang memakai tabel lokal.
+     *
+     * @return int Jumlah baris yang tersimpan
+     */
+    public function syncTahun(int $tahun): int
+    {
+        $sebelum = HariLiburNasional::whereYear('tanggal', $tahun)->count();
+
+        if (!$this->syncFromKemendesa($tahun)) {
+            $this->syncFromApiCoId($tahun);
+        }
+
+        $this->lupakanCache($tahun);
+
+        return HariLiburNasional::whereYear('tanggal', $tahun)->count() - $sebelum;
+    }
+
+    /**
+     * Daftar tanggal libur nasional (Y-m-d) pada rentang.
+     *
+     * Di-cache per tahun kalender (data SKB praktis statis) agar list
+     * dengan banyak baris tidak menimbulkan N+1 query.
+     */
+    public function tanggalPadaRentang(string $dari, string $sampai): array
+    {
+        $semua = [];
+        foreach (range((int) substr($dari, 0, 4), (int) substr($sampai, 0, 4)) as $tahun) {
+            $semua = array_merge($semua, Cache::remember(
+                self::CACHE_PREFIX . ":{$tahun}",
+                now()->addDay(),
+                fn () => HariLiburNasional::whereYear('tanggal', $tahun)
+                    ->pluck('tanggal')
+                    ->map(fn ($t) => Carbon::parse($t)->toDateString())
+                    ->all()
+            ));
+        }
+
+        return array_values(array_filter(
+            $semua,
+            fn ($t) => $t >= $dari && $t <= $sampai
+        ));
+    }
+
+    /**
+     * Hapus cache libur suatu tahun (dipanggil setelah sinkronisasi/seed).
+     */
+    public function lupakanCache(int $tahun): void
+    {
+        Cache::forget(self::CACHE_PREFIX . ":{$tahun}");
+    }
+
+    private function syncFromKemendesa(int $tahun): bool
+    {
+        try {
+            $response = Http::timeout(15)
+                ->get(config('services.kemendesa_holidays.host') . "/api/holidays/{$tahun}.json");
+
+            if (!$response->successful()) {
+                return false;
+            }
+
+            $count = 0;
+            foreach ($response->json('data', []) as $holiday) {
+                if (empty($holiday['date'])) {
+                    continue;
+                }
+                HariLiburNasional::updateOrCreate(
+                    [
+                        'tanggal' => $holiday['date'],
+                        'nama' => $holiday['name'] ?? 'Hari Libur',
+                    ],
+                    [
+                        'nama' => $holiday['name'] ?? 'Hari Libur',
+                    ]
+                );
+                $count++;
+            }
+
+            return $count > 0;
+        } catch (\Throwable $e) {
+            Log::warning('[HariLibur] Sinkronisasi kemendesa gagal: ' . $e->getMessage());
+
+            return false;
+        }
+    }
+
+    /**
+     * Sekunder: api.co.id (Indonesian Holidays).
+     * Docs: https://docs.api.co.id/products/indonesian-holidays/
+     * Header auth: x-api-co-id.
+     */
+    private function syncFromApiCoId(int $tahun): void
+    {
+        $key = config('services.api_co_id.holidays_key');
+        if (empty($key)) {
+            Log::warning('[HariLibur] API_CO_ID_HOLIDAYS_KEY kosong, sinkronisasi dilewati.');
+
+            return;
+        }
+
+        try {
+            $response = Http::timeout(15)->withHeaders([
+                'x-api-co-id' => $key,
+            ])->get(config('services.api_co_id.host') . '/holidays/indonesia/', array_filter([
+                'year' => $tahun,
+            ]));
+
+            if (!$response->successful() || !$response->json('is_success')) {
+                Log::warning('[HariLibur] Sinkronisasi gagal.', ['status' => $response->status()]);
+
+                return;
+            }
+
+            foreach ($response->json('data', []) as $holiday) {
+                if (empty($holiday['date'])) {
+                    continue;
+                }
+                // Hanya hari libur aktual (lewati Observance/peringatan yang bukan hari libur)
+                if (($holiday['type'] ?? null) === 'Observance' && empty($holiday['is_national_holiday'])) {
+                    continue;
+                }
+                HariLiburNasional::updateOrCreate(
+                    [
+                        'tanggal' => $holiday['date'],
+                        'nama' => $holiday['name'] ?? 'Hari Libur',
+                    ],
+                    [
+                        'nama' => $holiday['name'] ?? 'Hari Libur',
+                    ]
+                );
+            }
+        } catch (\Throwable $e) {
+            Log::warning('[HariLibur] Sinkronisasi error: ' . $e->getMessage());
+        }
+    }
+}
