new file mode 100644
index 000000000..7be294e54
--- /dev/null
+++ b/app/Http/Requests/PengawasanPerizinanBerusaha/Penjadwalan/RevisiPenjadwalanRequest.php
@@ -0,0 +1,68 @@
+<?php
+
+namespace App\Http\Requests\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use Closure;
+
+/**
+ * Validasi khusus aksi Penjadwalan Kembali (revisi).
+ *
+ * Sama seperti PersetujuanJadwalRequest, kecuali objek berstatus
+ * PenjadwalanTerlewat DIIZINKAN (justru itu kasus utama penjadwalan
+ * kembali): status direset ke DirevisiOSS + jadwal dikosongkan agar
+ * UPT memilih tanggal baru. Terima/tolak tetap memakai
+ * PersetujuanJadwalRequest yang menolak Terlewat.
+ */
+class RevisiPenjadwalanRequest extends PersetujuanJadwalRequest
+{
+    public function rules()
+    {
+        return [
+            'penjadwalan' => ['required', 'array', 'min:1'],
+            'penjadwalan.*' => ['required', function (string $attributes, string $value, Closure $fail) {
+                $id = $this->dekrip($value);
+                $penjadwalan = ObjekPengawasan::find($id);
+
+                if (!$penjadwalan) {
+                    $fail('Objek Pengawasan tidak ditemukan');
+                }
+
+                if ($penjadwalan?->status == ObjekPengawasan::ObjekPengawasanBaru) {
+                    $fail('Objek Pengawasan belum dikirimkan ke UPT');
+                }
+
+                if ($penjadwalan?->status == ObjekPengawasan::PersetujuanTanggalOperator) {
+                    $fail('Penjadwalan Mandiri belum disetujui Operator UPT WasRisk');
+                }
+
+                if ($penjadwalan?->status == ObjekPengawasan::PersetujuanDitolakOperator) {
+                    $fail('Penjadwalan Mandiri ditolak Operator UPT WasRisk');
+                }
+
+                if ($penjadwalan?->status == ObjekPengawasan::BelumDijadwalkan) {
+                    $fail('Objek Pengawasan belum dijadwakan');
+                }
+
+                if ($penjadwalan?->status == ObjekPengawasan::PersetujuanDirevisiOSS) {
+                    $fail('Objek Pengawasan belum dilakukan revisi jadwal');
+                }
+
+                if ($penjadwalan?->status == ObjekPengawasan::SudahDijadwalkan) {
+                    $fail('Objek Pengawasan belum input persetujuan ke OSS');
+                }
+
+                if (in_array($penjadwalan?->status, [
+                    ObjekPengawasan::PersetujuanDisetujuiOSS,
+                    ObjekPengawasan::BelumUploadST,
+                    ObjekPengawasan::LengkapiDokumen,
+                    ObjekPengawasan::MenungguInspeksi,
+                    ObjekPengawasan::Inspeksi
+                ])) {
+                    $fail("Penjadwalan Objek Pengawasan sudah disetujui (status: {$penjadwalan->status}). Untuk mengubah tanggal, gunakan jadwal ulang langsung, bukan penjadwalan kembali.");
+                }
+            }],
+            'alasan' => ['nullable', 'regex:/^[^*&$()#{}]+$/']
+        ];
+    }
+}
