+use App\Models\PengawasanPerizinanBerusaha\InspeksiLapangan\DokumenHasilPengawasan;
+use App\Models\PengawasanPerizinanBerusaha\InspeksiLapangan\JawabanPBUMKU;
+use App\Models\PengawasanPerizinanBerusaha\InspeksiLapangan\PertanyaanPBUMKU;
+use App\Services\PengawasanPerizinanBerusaha\InspeksiLapanganService;
+use App\Services\PengawasanPerizinanBerusaha\PertanyaanPbUmkuService;
+use App\Http\Requests\PengawasanPerizinanBerusaha\InspeksiLapangan\JawabInspeksiLapanganRequest;
+use Exception;
+
+class RecoverHaccpAnswers extends Command
+{
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'fix:haccp-answers {--id= : Spesifik ID Objek Pengawasan untuk direcover (opsional)} {--execute : Eksekusi recovery (tanpa flag ini hanya dry-run)}';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Recover data jawaban HACCP yang kosong (0 baris) akibat bug OSS timeout, dengan membaca file dokumentasi pendukung yang ada di Storage.';
+
+    /**
+     * Execute the console command.
+     *
+     * @return int
+     */
+    public function handle()
+    {
+        $specificId = $this->option('id');
+        $execute = $this->option('execute');
+
+        $this->info("Memulai pengecekan " . ($execute ? "Eksekusi Recovery" : "Dry-Run") . "...");
+
+        // Ambil semua dokumen HACCP yang sudah ter-generate
+        $query = DokumenHasilPengawasan::where('nama', 'LIKE', '%HACCP%');
+        if ($specificId) {
+            $query->where('objek_pengawasan_id', $specificId);
+        }
+        $dokumens = $query->get();
+
+        $inspeksiLapanganService = new InspeksiLapanganService();
+        $pertanyaanPbUmkuService = new PertanyaanPbUmkuService();
+
+        $recoveredCount = 0;
+
+        foreach ($dokumens as $dok) {
+            $objekId = $dok->objek_pengawasan_id;
+            $this->line("Memeriksa Dokumen ID: $dok->id, Objek ID: $objekId");
+            $objekPengawasan = ObjekPengawasan::find($objekId);
+            
+            if (!$objekPengawasan) {
+                $this->error("Objek Pengawasan tidak ditemukan untuk ID $objekId");
+                continue;
+            }
+
+            $idEnkrip = $inspeksiLapanganService->enkrip($objekId);
+
+            // Cek apakah tabel jawaban PBUMKU untuk HACCP 0 baris
+            $ansCount = JawabanPBUMKU::where('objek_pengawasan_id', $objekId)
+                ->where('jenis', 'haccp')
+                ->count();
+
+            if ($ansCount === 0) {
+                // Cek isi storage folder HACCP untuk ID ini
+                $path = "pengawasan_perizinan_berusaha/inspeksi_lapangan/pertanyaan/haccp/{$idEnkrip}/";
+                $files = Storage::disk('public')->files($path);
+
+                if (count($files) > 0) {
+                    $this->warn("Ditemukan target recovery: ID Objek $objekId. (Terdapat " . count($files) . " file dokumentasi tapi 0 jawaban DB)");
+
+                    // Ekstrak UUID pertanyaan dari nama file
+                    // Contoh nama file: 20260923105429_JA0b7TjtSgg4KwWq.63b426fa-2e39-4ee4-80c8-8b5546efaed2.jpg
+                    $answeredYesIds = [];
+                    foreach ($files as $file) {
+                        if (preg_match('/([a-f0-9\-]{36})\.[a-z0-9]+$/i', $file, $matches)) {
+                            $answeredYesIds[] = $matches[1];
+                        }
+                    }
+
+                    // Ambil list semua pertanyaan dari service
+                    $responsePertanyaan = $pertanyaanPbUmkuService->pertanyaan($idEnkrip, 'haccp', PertanyaanPBUMKU::Judul_HACCP, PertanyaanPBUMKU::Pertanyaan_HACCP);
+                    $pertanyaanData = json_decode($responsePertanyaan->content())->data->pertanyaan ?? [];
+                    
+                    $daftarPertanyaan = $inspeksiLapanganService->getAnswerableQuestion($pertanyaanData);
+
+                    $jawabanPayload = [];
+                    foreach ($daftarPertanyaan as $qId) {
+                        // Jika qId ada di list file, berarti user jawab 1 (Ya), kalau tidak 0 (Tidak)
+                        $isYes = in_array($qId, $answeredYesIds);
+                        $jawabanPayload[] = [
+                            'id' => $qId,
+                            'jawaban' => $isYes ? '1' : '0',
+                            'keterangan' => '-' // Keterangan standar karena hilang
+                        ];
+                    }
+
+                    if ($execute) {
+                        $this->info("  [>] Menyiapkan recovery data untuk ID $objekId...");
+                        try {
+                            DB::beginTransaction();
+                            // Fungsi jawab sudah kita fix sehingga memproses dengan aman
+                            // Khusus simulasi fungsi jawab, kita lewati logic controller (bypass middleware Auth)
+                            // karena kita berada di Console. Kita save manual agar lebih aman dari error validasi NIP auth.
+                            foreach ($jawabanPayload as $ansData) {
+                                $ansObj = (object) $ansData;
+                                $pertanyaan = PertanyaanPBUMKU::find($ansObj->id);
+                                JawabanPBUMKU::updateOrCreate([
+                                    'objek_pengawasan_id' => $objekId,
+                                    'jenis' => 'haccp',
+                                    'pertanyaan_id' => $ansObj->id
+                                ], [
+                                    'jawaban' => $ansObj->jawaban,
+                                    'skor' => $ansObj->jawaban ? ($pertanyaan->skor ?? 0) : 0
+                                ]);
+                            }
+
+                            // Re-calculate Total Nilai
+                            $totalNilai = JawabanPBUMKU::where('objek_pengawasan_id', $objekId)->where('jenis', 'haccp')->sum('skor');
+                            $dok->nilai = $totalNilai;
+                            $dok->save();
+                            DB::commit();
+
+                            $this->info("  [✓] Sukses recover jawaban ID $objekId. (Memicu Generate Dokumen PDF...)");
+                            // Trigger generate ulang dokumen agar PDF tidak blank lagi
+                            $pertanyaanPbUmkuService->generateDokumen($objekPengawasan, 'haccp', 'HACCP');
+                            
+                            $recoveredCount++;
+                        } catch (Exception $e) {
+                            if (DB::transactionLevel() > 0) {
+                                DB::rollBack();
+                            }
+                            $this->error("  [x] Gagal memulihkan ID $objekId: " . $e->getMessage());
+                        }
+                    } else {
+                        $this->line("  [~] Dry-Run: (Simulasi) akan me-recover " . count($jawabanPayload) . " jawaban (File yang ditemukan: " . implode(', ', $answeredYesIds) . ")");
+                    }
+                }
+            }
+        }
+
+        if ($execute) {
+            $this->info("\nRecovery selesai. Total Objek Pengawasan yang berhasil dipulihkan: $recoveredCount.");
+        } else {
+            $this->info("\nMode Dry-Run selesai. Tambahkan flag --execute untuk benar-benar melakukan recovery.");
+        }
+
+        return 0;
+    }
+}
