+<?php
+
+namespace App\Console\Commands\PengawasanPerizinanBerusaha\Penjadwalan;
+
+use App\Models\PegawaiInternal;
+use App\Models\Penjadwalan\DokumenMetadata;
+use App\Models\Penjadwalan\DokumenPenjadwalan;
+use App\Models\PengawasanPerizinanBerusaha\ObjekPengawasan\ObjekPengawasan;
+use Illuminate\Console\Command;
+
+class AuditEkstrakDokumenCommand extends Command
+{
+    /**
+     * The name and signature of the console command.
+     *
+     * @var string
+     */
+    protected $signature = 'ppbbr:audit-ekstrak-dokumen
+        {--perbaiki : Hapus baris tak tervalidasi (soft delete) + turunkan status Menunggu Inspeksi yang tak lengkap}
+        {--jenis=notula,surat_tugas : Jenis yang diaudit (koma-dipisah; SP/STKL bebas ekstrak)}';
+
+    /**
+     * The console command description.
+     *
+     * @var string
+     */
+    protected $description = 'Audit dokumen penjadwalan yang tersimpan tanpa hasil ekstrak (tanpa metadata) + NIP penerbit invalid.';
+
+    public function handle(): int
+    {
+        $jeniss = array_map('trim', explode(',', (string) $this->option('jenis')));
+        $perbaiki = (bool) $this->option('perbaiki');
+
+        $rows = DokumenPenjadwalan::whereIn('jenis_dokumen', $jeniss)
+            ->where(function ($q) {
+                $q->whereNotNull('file_path')->orWhereNotNull('portal_dokumen_id');
+            })
+            ->with('objekPengawasan')
+            ->orderBy('objek_pengawasan_id')
+            ->get();
+
+        $takValid = [];
+        foreach ($rows as $row) {
+            $adaMeta = DokumenMetadata::where('jenis_dokumen', $row->jenis_dokumen)
+                ->where(function ($q) use ($row) {
+                    if ($row->file_path) {
+                        $q->orWhere('file_path', $row->file_path);
+                    }
+                    if ($row->portal_dokumen_id) {
+                        $q->orWhere('portal_dokumen_id', $row->portal_dokumen_id);
+                    }
+                })
+                ->exists();
+
+            if (!$adaMeta) {
+                $takValid[] = $row;
+            }
+        }
+
+        $this->info('Dokumen tanpa metadata ekstrak: ' . count($takValid));
+        foreach ($takValid as $row) {
+            $this->line("- objek {$row->objek_pengawasan_id} [{$row->jenis_dokumen}] file=" . ($row->file_path ?? '-') . ' portal=' . ($row->portal_dokumen_id ?? '-') . ' status=' . ($row->objekPengawasan->status ?? '?'));
+        }
+
+        // NIP penerbit yang tidak terdaftar di pegawai.
+        $nips = DokumenPenjadwalan::whereNotNull('penerbit_nip')
+            ->where('penerbit_nip', '!=', '')
+            ->distinct()
+            ->pluck('penerbit_nip');
+        $nipsInvalid = $nips->reject(fn ($nip) => PegawaiInternal::where('nip', $nip)->exists())->values();
+        $this->info('NIP penerbit invalid: ' . $nipsInvalid->count());
+        foreach ($nipsInvalid as $nip) {
+            $this->line("- {$nip}");
+        }
+
+        if (!$perbaiki) {
+            $this->comment('Mode laporan saja. Tambahkan --perbaiki untuk menghapus + menurunkan status.');
+
+            return Command::SUCCESS;
+        }
+
+        $diturunkan = 0;
+        foreach ($takValid as $row) {
+            $objekId = $row->objek_pengawasan_id;
+            $jenis = $row->jenis_dokumen;
+            $row->delete();
+
+            $objek = ObjekPengawasan::find($objekId);
+            if (!$objek) {
+                continue;
+            }
+
+            // Bersihkan kolom legacy bila tak ada lagi dokumen valid jenis tersebut.
+            $masihAda = DokumenPenjadwalan::where('objek_pengawasan_id', $objekId)
+                ->where('jenis_dokumen', $jenis)
+                ->where(function ($q) {
+                    $q->whereNotNull('file_path')->orWhereNotNull('portal_dokumen_id');
+                })
+                ->exists();
+            if (!$masihAda) {
+                if ($jenis === 'notula') {
+                    // Kolom legacy notula tidak ada; nothing.
+                } elseif ($jenis === 'stkl') {
+                    $objek->stkl = null;
+                } elseif ($jenis === 'surat_tugas') {
+                    $objek->surat_tugas = null;
+                } elseif (str_contains($jenis, 'surat_pemberitahuan')) {
+                    $objek->surat_pemberitahuan = null;
+                }
+            }
+
+            // Hanya turunkan status Menunggu Inspeksi yang jadi tak lengkap.
+            // Objek yang sudah masuk Inspeksi/Selesai dibiarkan (review manual).
+            $dokumens = DokumenPenjadwalan::where('objek_pengawasan_id', $objekId)
+                ->where(function ($q) {
+                    $q->whereNotNull('file_path')->orWhereNotNull('portal_dokumen_id');
+                })
+                ->pluck('jenis_dokumen')->all();
+            $lengkap = in_array('notula', $dokumens)
+                && in_array('stkl', $dokumens)
+                && in_array('surat_pemberitahuan', $dokumens)
+                && in_array('surat_tugas', $dokumens);
+            if (!$lengkap && $objek->status === ObjekPengawasan::MenungguInspeksi) {
+                $objek->status = ObjekPengawasan::LengkapiDokumen;
+                $diturunkan++;
+            }
+            $objek->save();
+        }
+
+        $this->info('Baris dihapus (soft delete): ' . count($takValid) . '. Status diturunkan: ' . $diturunkan . '.');
+        $this->comment('Langkah lanjut: operator ekstrak ulang + simpan ulang via alur normal (aturan wajib-ekstrak kini aktif). File fisik di storage TIDAK dihapus.');
+
+        return Command::SUCCESS;
+    }
+}

