+                        if ($portalDokumen->is_manual && $portalDokumen->storage_path) {
+                            // Skenario dokumen manual upload
+                            $localPath = storage_path('app/public/' . $portalDokumen->storage_path);
+                            if (file_exists($localPath)) {
+                                $fullPath = $localPath;
+                                $savedFilePath = 'storage/' . $portalDokumen->storage_path;
+                            } else {
+                                throw new Exception("File dokumen manual tidak ditemukan di path fisik: " . $localPath);
+                            }
+                        } else {
+                            // Skenario UAT Generator versi baru
+                            $encryptedId = str_replace($apiPrefix, '', $url);
+                            $korespondensiPath = public_path('bucket/s3_default/file/korespondensi/' . $encryptedId);
+
+                            if (is_dir($korespondensiPath)) {
+                                $files = glob($korespondensiPath . '/*.pdf');
+                                if (!empty($files)) {
+                                    $fullPath = $files[0];
+                                    $relativePath = 'bucket/s3_default/file/korespondensi/' . $encryptedId . '/' . basename($fullPath);
+                                    $savedFilePath = $relativePath;
+                                }
+                            }
+
+                            if (!$fullPath) {
+                                // Fallback: generator UAT memakai folder dokumen_id numerik
+                                $numericPath = public_path('bucket/s3_default/file/korespondensi/' . $portalDokumen->dokumen_id);
+
+                                if (is_dir($numericPath)) {
+                                    $files = glob($numericPath . '/*.pdf');
+                                    if (!empty($files)) {
+                                        $fullPath = $files[0];
+                                        $savedFilePath = 'bucket/s3_default/file/korespondensi/' . $portalDokumen->dokumen_id . '/' . basename($fullPath);
+                                    }
+                                }
+                            }
+
+                            if (!$fullPath) {
+                                // Fallback: Fetch URL route secara HTTP (berguna di VPS/Server)
+                                $fullApiUrl = rtrim(env('APP_URL'), '/') . $url;
+
+                                // Bawa header Authorization dari request saat ini agar lolos middleware 'access'
+                                $authHeader = request()->header('Authorization');
+
+                                $context = stream_context_create([
+                                    'ssl' => ['verify_peer' => false, 'verify_peer_name' => false],
+                                    'http' => [
+                                        'header' => "User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64)\r\n" .
+                                            ($authHeader ? "Authorization: $authHeader\r\n" : "")
+                                    ]
+                                ]);
+
+                                $fileContents = @file_get_contents($fullApiUrl, false, $context);
+
+                                if ($fileContents === false) {
+                                    throw new Exception("File fisik tidak ditemukan di lokal dan gagal mengambil dari route API (timeout/401/404): " . $fullApiUrl);
+                                }
+
+                                $tempPath = 'temp_extract/' . uniqid() . '.pdf';
+                                Storage::disk('public')->put($tempPath, $fileContents);
+
+                                $fullPath = storage_path('app/public/' . $tempPath);
+                                $savedFilePath = 'storage/' . $tempPath;
+                            }
+                        }
+                    } else if (str_starts_with($url, $appUrl)) {
+                        // Optimasi untuk local UAT versi lama
+                        $relativePath = str_replace($appUrl . '/storage/', '', $url);
+                        $localPath = storage_path('app/public/' . $relativePath);
+
+                        // Fallback jika file digenerate dengan path UAT generator versi lama (terlanjur ada public/ di awal)
+                        $fallbackLocalPath = storage_path('app/public/public/' . $relativePath);
+
+                        if (file_exists($localPath)) {
+                            $fullPath = $localPath;
+                            $savedFilePath = 'storage/' . $relativePath;
+                        } else if (file_exists($fallbackLocalPath)) {
+                            $fullPath = $fallbackLocalPath;
+                            $savedFilePath = 'storage/public/' . $relativePath;
+                        } else {
+                            throw new Exception("File lokal tidak ditemukan di path fisik: " . $localPath);
+                        }
+                    } else {
+                        // Unduh dari eksternal (Misal: CSRS production)
+                        $context = stream_context_create([
+                            'ssl' => [
+                                'verify_peer' => false,
+                                'verify_peer_name' => false,
+                            ],
+                            'http' => [
+                                'header' => "User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64)\r\n"
+                            ]
+                        ]);
+                        $fileContents = file_get_contents($url, false, $context);
+                        if ($fileContents === false) throw new Exception("HTTP request failed");
+
+                        $tempPath = 'temp_extract/' . uniqid() . '.pdf';
+                        Storage::disk('public')->put($tempPath, $fileContents);
+
+                        $fullPath = storage_path('app/public/' . $tempPath);
+                        $savedFilePath = 'storage/' . $tempPath;
+                    }
+                } catch (\Exception $e) {
+                    return $this->onError('Gagal mendapatkan file fisik dari URL CSRS untuk diekstrak: ' . $e->getMessage());
+                }
+            }
+
+            if (!$fullPath || !file_exists($fullPath)) {
+                return $this->onError('File fisik dokumen tidak ditemukan di server');
+            }
+
+            $ekstrakService = new EkstrakDokumenService();
+            // Laporan: ekstraksi hanya Halaman 1
+            $maxPages = ($request->jenis_dokumen === 'laporan') ? 1 : 0;
+            // jenis_dokumen menentukan kode KM yang sah untuk Nomor Surat
+            // (lihat KM_PER_JENIS di extract_dokumen.py). Tanpa ini, filter
+            // bawaan terlalu sempit dan referensi PW.*/TU.* yang sah terbuang.
+            $hasilEkstrak = $ekstrakService->ekstrakViaPython($fullPath, $maxPages, $request->jenis_dokumen);
+
+            // Dapatkan base query pencocokan (termasuk filter role UPT/Pusat).
+            $queryBase = $this->queryBaseUntukEkstrak();
+
+            // Resolve ID saat ini jika ada
+            $currentObjekId = $id ? $this->dekrip($id) : null;
+
+            // Cocokkan ke database. `jenis_dokumen` dipakai untuk mempersempit
+            // HANYA pencocokan cadangan (objek lain) ke status yang relevan:
+            //   notula / surat_pemberitahuan / surat_tugas / stkl -> pra-inspeksi
+            //   laporan                                                -> Selesai
+            // Objek yang sedang dibuka tetap dicocokkan TANPA filter status.
+            $cocok = $ekstrakService->cocokkanKeObjek(
+                $hasilEkstrak,
+                $queryBase,
+                $currentObjekId,
+                $request->jenis_dokumen
+            );
+
+            // Simpan ke Redis cache (session_id random unik)
+            $sessionId = uniqid('sess_');
+
+            // Tambahkan file_path hanya untuk internal cache agar nanti bisa dipakai di simpanDokumen
+            $cacheData = $cocok;
+            $cacheData['file_path'] = $savedFilePath;
+
+            $ekstrakService->simpanKeCache($sessionId, $cacheData);
+
+            // Auto-reset: manual wajib-ekstrak (notula/ST) yang hasilnya tanpa
+            // NKU current valid dan barisnya belum pernah tervalidasi → hapus
+            // baris + file yatim sekalian agar operator langsung mulai dari nol.
+            // Baris yang pernah valid + jalur CSRS (tanpa dokumen_id) tidak tersentuh.
+            $dokumenDireset = $this->resetOtomatisBilaEkstrakAnomali(
+                $request->jenis_dokumen ?? null,
+                $dokumenIdStr ?? null,
+                $currentObjekId,
+                $cocok
+            );
+
+            return $this->onSuccess(empty($cocok) ? 'Ekstraksi selesai, tetapi tidak ada Nomor ST/NKU yang terbaca dari dokumen' : 'Ekstraksi berhasil', [
+                'session_id' => $sessionId,
+                'hasil_ekstrak' => $cocok,
+                // Sinyal eksplisit agar FE tidak menampilkan "berhasil" yang menyesatkan
+                // saat tidak ada nomor yang terbaca (tetap 200 + session valid agar Simpan bisa jalan).
+                'is_empty' => empty($cocok),
+                'dokumen_direset' => $dokumenDireset,
+            ]);
+        } catch (Exception $e) {
+            return $this->onError($e->getMessage());
+        }
+    }
+    /**
+     * Auto-reset baris manual yang hasil ekstraknya anomali (tanpa NKU
+     * current valid) dan belum pernah tervalidasi. Dipanggil di akhir
+     * extractDokumen agar file yatim langsung bersih tanpa aksi FE.
+     *
+     * @return bool true bila reset dilakukan
+     */
+    private function resetOtomatisBilaEkstrakAnomali(?string $jenisDokumen, ?string $dokumenIdStr, $currentObjekId, array $cocok): bool
+    {
+        if (!in_array($jenisDokumen, ['notula', 'surat_tugas'], true)) {
+            return false;
+        }
+        if (empty($dokumenIdStr) || empty($currentObjekId)) {
+            return false;
+        }
+
+        $dokumenId = $this->dekrip($dokumenIdStr);
+        if (!is_numeric($dokumenId)) {
+            return false;
+        }
+        $docRow = DokumenPenjadwalan::find((int) $dokumenId);
+        if (!$docRow
+            || (int) $docRow->objek_pengawasan_id !== (int) $currentObjekId
+            || !empty($docRow->portal_dokumen_id)
+        ) {
+            return false;
+        }
+        if ($this->recordTervalidasiEkstrak((int) $docRow->objek_pengawasan_id, $docRow->jenis_dokumen)) {
+            return false;
+        }
+
+        foreach ($cocok as $item) {
+            if (!is_array($item)) {
+                continue;
+            }
+            $oid = $item['objek_pengawasan_id'] ?? null;
+            $oidInt = is_numeric($oid) ? (int) $oid : ($oid ? (int) $this->dekrip($oid) : 0);
+            if ($oidInt === (int) $currentObjekId) {
+                return false;
+            }
+        }
+
+        try {
+            $this->resetDokumenObjek((int) $docRow->objek_pengawasan_id, $docRow->jenis_dokumen);
+        } catch (\Throwable $e) {
+            Log::warning('[PenjadwalanService::extractDokumen] Auto-reset gagal: ' . $e->getMessage());
+
+            return false;
+        }
+
+        return true;
+    }
+    /**
+     * Base query untuk pencocokan hasil ekstraksi ke Objek Pengawasan.
+     */
+    private function queryBaseUntukEkstrak(): Builder
+    {
+        // Extract hanya butuh pencocokan NKU/Nomor ST ke objek. Filter STATUS
+        // sengaja TIDAK dipasang di sini, karena queryBase juga berlaku untuk
+        // objek yang sedang dibuka — objek Selesai (pasca-inspeksi, mis. akan
+        // melengkapi ulang dokumen) tetap harus bisa match.
+        //
+        // Penyempitan status per jenis dokumen dilakukan di
+        // EkstrakDokumenService::cocokkanKeObjek() dan HANYA untuk pencocokan
+        // cadangan (objek lain), bukan untuk objek saat ini.
+        return $this->applyRoleAuthorization($this->objekPengawasan->query());
+    }
+    /**
+     * Evaluasi kelengkapan dokumen dan ubah status
+     *
+     * Aturan lengkap: Notula & ST dihitung lengkap bila ada dokumen/surat
+     * (file/portal) + min. 1 NKU current valid (metadata ekstrak tertaut).
+     * SP & STKL cukup ada dokumen/surat. Legacy kolom tetap dihitung.
+     */
+    private function evaluasiStatusPenjadwalan($objek)
+    {
+        // Hanya dokumen yang punya file fisik (atau dari portal) yang dihitung.
+        // Phantom record (file_path null + portal null) tidak boleh mengubah status.
+        $docMap = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+            ->where(function ($q) {
+                $q->whereNotNull('file_path')->orWhereNotNull('portal_dokumen_id');
+            })
+            ->get(['jenis_dokumen', 'file_path', 'portal_dokumen_id'])
+            ->keyBy('jenis_dokumen');
+        $dokumens = $docMap->keys()->all();
+
+        $hasNotula = $this->dokumenAdaDenganNkuValid($docMap->get('notula'), 'notula', $objek->id);
+        $hasStkl = in_array('stkl', $dokumens) || !empty($objek->stkl);
+        $hasSp = in_array('surat_pemberitahuan', $dokumens) || !empty($objek->surat_pemberitahuan);
+        $hasSt = $this->dokumenAdaDenganNkuValid($docMap->get('surat_tugas'), 'surat_tugas', $objek->id)
+            || !empty($objek->surat_tugas);
+
+        // Fallback untuk legacy data yang belum punya notula tapi sudah punya ST lengkap
+        if (empty($dokumens) && $hasSt && $hasSp && $hasStkl) {
+            $hasNotula = true;
+        }
+
+        $oldStatus = $objek->status;
+
+        if ($hasNotula && $hasStkl && $hasSp && $hasSt) {
+            // Jika dokumen lengkap dan saat ini adalah Hari H, otomatis langsung Inspeksi Lapangan.
+            // Jika belum Hari H (masa depan), statusnya Menunggu Inspeksi.
+            $isHariH = $objek->jadwal && Carbon::parse($objek->jadwal)->isToday();
+            $objek->status = $isHariH ? ObjekPengawasan::Inspeksi : ObjekPengawasan::MenungguInspeksi;
+        } else {
+            $objek->status = ObjekPengawasan::LengkapiDokumen;
+        }
+        $objek->save();
+
+        // Trigger Notifikasi jika status baru saja berubah menjadi Menunggu Inspeksi
+        if ($oldStatus !== ObjekPengawasan::MenungguInspeksi && $objek->status === ObjekPengawasan::MenungguInspeksi) {
+            $serverCodeNotif = $this->generateServerCode();
+            try {
+                dispatch(new ProcessSendWaKirimPenjadwalanInspeksi($objek, $serverCodeNotif))->onQueue('high');
+                dispatch(new ProcessSendEmailKirimPenjadwalanInspeksi($objek, $serverCodeNotif))->onQueue('high');
+            } catch (\Exception $notifE) {
+                Log::warning('[PenjadwalanService::evaluasiStatusPenjadwalan] Notifikasi gagal: ' . $notifE->getMessage());
+            }
+        }
+    }
+    /**
+     * Dokumen Notula/ST dihitung lengkap bila ada baris ber-file/portal DAN
+     * punya min. 1 metadata NKU valid milik objek ini yang tertaut
+     * (file_path/portal sama). Mencegah status flip walau simpan NKU gagal.
+     * Public static agar dipakai juga oleh PenjadwalanResource
+     * (kelengkapan_dokumen) dengan aturan yang sama persis.
+     *
+     * @param \App\Models\Penjadwalan\DokumenPenjadwalan|array|null $doc
+     */
+    public static function dokumenAdaDenganNkuValid($doc, string $jenisDokumen, int $objekId): bool
+    {
+        if (!$doc) {
+            return false;
+        }
+
+        $filePath = $doc['file_path'] ?? null;
+        $portalId = $doc['portal_dokumen_id'] ?? null;
+        if (!$filePath && !$portalId) {
+            return false;
+        }
+
+        return DokumenMetadata::where('jenis_dokumen', $jenisDokumen)
+            ->where('jenis_item', 'nku')
+            ->where('objek_pengawasan_id', $objekId)
+            ->where(function ($q) use ($filePath, $portalId) {
+                if ($filePath) {
+                    $q->orWhere('file_path', $filePath);
+                }
+                if ($portalId) {
+                    $q->orWhere('portal_dokumen_id', $portalId);
+                }
+            })
+            ->exists();
+    }
+    /**
+     * Helper otorisasi aksi berdasarkan permission (route name).
+     *
+     * Permission didaftarkan via AkunPenjadwalanLhpSeeder dan diberikan ke
+     * role Operator WasRisk (UPT/Pusat); Superuser/Superadmin mendapat
+     * seluruh permission via syncToSuperRoles().
+     */
+    protected function authorizeAksi(string $permission): void
+    {
+        $user = Auth::user();
+
+        if (!$user || !$user->can($permission)) {
+            throw new Exception("Anda tidak memiliki akses untuk aksi ini (membutuhkan permission {$permission}). Hubungi admin untuk pemberian akses.");
+        }
+    }
+    /**
+     * Helper validasi urutan upload
+     */
+    private function validasiUrutanUpload($objek, $jenisDokumen)
+    {
+        // Memakai konstanta STATUS_PRA_INSPEKSI, bukan hardcode lokal — supaya
+        // perubahan kelak di konstanta otomatis menyebar ke sini. Sebelumnya
+        // di-hardcode (4 status), persis seperti konstanta, tapi itu berisiko
+        // drift: kalau konstanta diubah, array lokal ini diam-diam menyimpang.
+        $allowedStatuses = ObjekPengawasan::STATUS_PRA_INSPEKSI;
+
+        if (!in_array($objek->status, $allowedStatuses)) {
+            throw new Exception("Tidak dapat menyimpan dokumen penjadwalan. Status saat ini adalah '{$objek->status}'. Proses input dokumen hanya dapat dilakukan pada status '" . ObjekPengawasan::PersetujuanDisetujuiOSS . "'.");
+        }
+
+        $dokumenAda = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+            ->where('jenis_dokumen', $jenisDokumen)
+            ->where(function ($q) {
+                $q->whereNotNull('file_path')->orWhereNotNull('portal_dokumen_id');
+            })
+            ->exists();
+
+        if (!$dokumenAda) {
+            $dokumenLain = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+                ->where(function ($q) {
+                    $q->whereNotNull('file_path')->orWhereNotNull('portal_dokumen_id');
+                })
+                ->pluck('jenis_dokumen')->toArray();
+
+            if ($jenisDokumen === 'stkl') {
+                if (!in_array('notula', $dokumenLain)) {
+                    throw new Exception("Tidak dapat menyimpan STKL. Silakan unggah Notula terlebih dahulu untuk proyek {$objek->no_kode_proyek}.");
+                }
+            } else if ($jenisDokumen === 'surat_pemberitahuan') {
+                if (!in_array('notula', $dokumenLain)) {
+                    throw new Exception("Tidak dapat menyimpan SP. Silakan unggah Notula terlebih dahulu untuk proyek {$objek->no_kode_proyek}.");
+                }
+                if (!in_array('stkl', $dokumenLain)) {
+                    throw new Exception("Tidak dapat menyimpan SP. Silakan unggah STKL terlebih dahulu untuk proyek {$objek->no_kode_proyek}.");
+                }
+            } else if ($jenisDokumen === 'surat_tugas') {
+                if (!in_array('notula', $dokumenLain)) {
+                    throw new Exception("Tidak dapat menyimpan Surat Tugas. Silakan unggah Notula terlebih dahulu untuk proyek {$objek->no_kode_proyek}.");
+                }
+                if (!in_array('stkl', $dokumenLain)) {
+                    throw new Exception("Tidak dapat menyimpan Surat Tugas. Silakan unggah STKL terlebih dahulu untuk proyek {$objek->no_kode_proyek}.");
+                }
+                if (!in_array('surat_pemberitahuan', $dokumenLain)) {
+                    throw new Exception("Tidak dapat menyimpan Surat Tugas. Silakan unggah Surat Pemberitahuan terlebih dahulu untuk proyek {$objek->no_kode_proyek}.");
+                }
+            }
+        }
+    }
+    /**
+     * Helper validasi wajib-ekstrak saat simpan.
+     *
+     * Notula & ST wajib membawa sesi /extract yang memuat NKU current
+     * bila ada objek target yang belum punya record tervalidasi (pembuatan
+     * baru, atau record dari /unggah yang belum pernah diekstrak).
+     * Bila sesi dikirim (ekstrak ulang), isinya selalu divalidasi —
+     * termasuk pada record yang sudah ada. SP & STKL dikecualikan;
+     * update metadata murni (record + metadata ekstrak sudah ada) tanpa
+     * sesi juga dikecualikan.
+     */
+    private function validasiWajibEkstrak(string $jenisDokumen, $request, array $objekIds): void
+    {
+        if (!in_array($jenisDokumen, ['notula', 'surat_tugas'], true)) {
+            return;
+        }
+
+        $existingIds = [];
+        $adaBaru = false;
+        foreach ($objekIds as $idStr) {
+            $objekId = is_numeric($idStr) ? (int) $idStr : (int) $this->dekrip($idStr);
+            if (!$objekId) {
+                continue;
+            }
+            if ($this->objekPengawasan->find($objekId)) {
+                $existingIds[] = $objekId;
+            }
+            if (!$this->recordTervalidasiEkstrak($objekId, $jenisDokumen)) {
+                $adaBaru = true;
+            }
+        }
+
+        $primaryId = $request->route('id') ? (int) $this->dekrip($request->route('id')) : null;
+
+        // Tanpa sesi: hanya boleh bila semua target sudah punya record
+        // yang pernah diekstrak (ada metadata-nya).
+        if (empty($request->session_id)) {
+            if ($adaBaru) {
+                throw new Exception("Dokumen {$jenisDokumen} wajib diekstrak terlebih dahulu agar minimal ada NKU proyek saat ini. Silakan ekstrak lalu simpan ulang.");
+            }
+
+            return;
+        }
+
+        // Ada sesi (baru maupun ekstrak ulang): isinya wajib memuat current.
+        // Tanpa primary: semua target yang objeknya ada wajib termuat
+        // (ID objek yang tidak ditemukan dilewati seperti di loop simpan).
+        (new EkstrakDokumenService())->pastikanSesiMemuatCurrent(
+            $request->session_id,
+            $primaryId,
+            $primaryId ? [$primaryId] : $existingIds,
+            $jenisDokumen
+        );
+    }
+    /**
+     * Record dianggap tervalidasi bila ber-file/portal DAN punya baris
+     * metadata ekstrak yang tertaut (file_path/portal sama, jenis sama).
+     * Mencegah /unggah tanpa ekstrak lolos sebagai "update".
+     */
+    private function recordTervalidasiEkstrak(int $objekId, string $jenisDokumen): bool
+    {
+        $rec = DokumenPenjadwalan::where('objek_pengawasan_id', $objekId)
+            ->where('jenis_dokumen', $jenisDokumen)
+            ->where(function ($q) {
+                $q->whereNotNull('file_path')->orWhereNotNull('portal_dokumen_id');
+            })
+            ->first();
+
+        if (!$rec) {
+            return false;
+        }
+
+        return DokumenMetadata::where('jenis_dokumen', $jenisDokumen)
+            ->where(function ($q) use ($rec) {
+                if ($rec->file_path) {
+                    $q->orWhere('file_path', $rec->file_path);
+                }
+                if ($rec->portal_dokumen_id) {
+                    $q->orWhere('portal_dokumen_id', $rec->portal_dokumen_id);
+                }
+            })
+            ->exists();
+    }
+    /**
+     * Reset Dokumen (file/surat): hapus file fisik + baris relasi +
+     * metadata ekstrak milik objek ini, bersihkan kolom legacy bila kosong,
+     * lalu evaluasi ulang status (hanya fase penjadwalan).
+     *
+     * Dipakai saat hasil ekstrak invalid/kosong agar operator bisa mulai
+     * dari nol tanpa sisa file yatim. Data portal CSRS tidak dihapus
+     * (milik bersama), hanya relasinya.
+     *
+     * TANPA endpoint HTTP (tidak perlu integrasi FE): dipakai via artisan
+     * `ppbbr:audit-ekstrak-dokumen --reset-objek={id} --reset-jenis={jenis}`
+     * dan unit test. Otorisasi mengikuti permission dokumen.store.
+     */
+    public function resetDokumen($request, string $id): JsonResponse
+    {
+        DB::beginTransaction();
+        try {
+            $this->authorizeAksi('ppbbr.penjadwalan.dokumen.store');
+
+            $hasil = $this->resetDokumenObjek(
+                (int) $this->dekrip($id),
+                (string) $request->jenis_dokumen
+            );
+
+            DB::commit();
+
+            return $this->onSuccess($hasil['message'], ['file_dihapus' => $hasil['file_dihapus']]);
+        } catch (Exception $e) {
+            DB::rollBack();
+
+            return $this->onError($e->getMessage());
+        }
+    }
+    /**
+     * Inti reset dokumen per objek (tanpa otorisasi & transaksi sendiri),
+     * agar bisa dipakai ulang oleh artisan command.
+     *
+     * @return array{message: string, file_dihapus: bool, direset: bool}
+     * @throws Exception
+     */
+    public function resetDokumenObjek(int $objekId, string $jenisDokumen): array
+    {
+        $objek = $this->objekPengawasan->find($objekId);
+        if (!$objek) {
+            throw new Exception('Objek Pengawasan tidak ditemukan');
+        }
+
+        // Batas maksimal ubah dokumen: Hari H (selaras unggah/simpan).
+        if ($objek->jadwal) {
+            if (now()->startOfDay()->gt(Carbon::parse($objek->jadwal)->startOfDay())) {
+                throw new Exception('Batas waktu ubah dokumen sudah berakhir. Dokumen hanya dapat diubah maksimal pada Hari H (Jadwal Inspeksi).');
+            }
+        }
+
+        $dokumen = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+            ->where('jenis_dokumen', $jenisDokumen)
+            ->first();
+
+        if (!$dokumen || (!$dokumen->file_path && !$dokumen->portal_dokumen_id)) {
+            return ['message' => "Dokumen {$jenisDokumen} sudah kosong, tidak ada yang direset.", 'file_dihapus' => false, 'direset' => false];
+        }
+
+        // Hapus file fisik (bila manual). Data portal CSRS dipertahankan.
+        $fileDihapus = false;
+        if ($dokumen->file_path) {
+            $fileDihapus = FileService::deleteOnStorage($dokumen->file_path);
+        }
+
+        // Hapus metadata ekstrak milik objek ini yang tertaut
+        // (file/portal sama). Metadata objek lain tidak tersentuh.
+        DokumenMetadata::where('jenis_dokumen', $jenisDokumen)
+            ->where('objek_pengawasan_id', $objek->id)
+            ->where(function ($q) use ($dokumen) {
+                if ($dokumen->file_path) {
+                    $q->orWhere('file_path', $dokumen->file_path);
+                }
+                if ($dokumen->portal_dokumen_id) {
+                    $q->orWhere('portal_dokumen_id', $dokumen->portal_dokumen_id);
+                }
+            })
+            ->delete();
+
+        $dokumen->delete();
+
+        // Bersihkan kolom legacy bila tak ada lagi dokumen valid jenis ini.
+        $masihAda = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+            ->where('jenis_dokumen', $jenisDokumen)
+            ->where(function ($q) {
+                $q->whereNotNull('file_path')->orWhereNotNull('portal_dokumen_id');
+            })
+            ->exists();
+        if (!$masihAda) {
+            if ($jenisDokumen === 'stkl') {
+                $objek->stkl = null;
+            } elseif ($jenisDokumen === 'surat_tugas') {
+                $objek->surat_tugas = null;
+            } elseif (str_contains($jenisDokumen, 'surat_pemberitahuan')) {
+                $objek->surat_pemberitahuan = null;
+            }
+            $objek->save();
+        }
+
+        // Evaluasi ulang hanya di fase penjadwalan agar status
+        // Inspeksi/Selesai tidak terseret mundur.
+        if (in_array($objek->status, ObjekPengawasan::STATUS_PRA_INSPEKSI, true)) {
+            $this->evaluasiStatusPenjadwalan($objek->fresh());
+        }
+
+        return ['message' => "Dokumen {$jenisDokumen} berhasil direset.", 'file_dihapus' => $fileDihapus, 'direset' => true];
+    }
+    /**
+     * Snapshot versi dokumen ke riwayat (jaring pengaman bila file/surat
+     * yang sudah benar tertimpa yang salah). Dipanggil setiap simpan/unggah
+     * berhasil. Riwayat tahan hapus (tanpa FK cascade).
+     *
+     * @param string $status berhasil|gagal
+     * @param string|null $catatan Pesan error bila gagal
+     */
+    private function snapshotRiwayatDokumen(DokumenPenjadwalan $dokumen, string $status = 'berhasil', ?string $catatan = null): void
+    {
+        $version = (DokumenPenjadwalanRiwayat::where('dokumen_id', $dokumen->id)->max('version') ?? 0) + 1;
+
+        DokumenPenjadwalanRiwayat::create([
+            'dokumen_id' => $dokumen->id,
+            'objek_pengawasan_id' => $dokumen->objek_pengawasan_id,
+            'jenis_dokumen' => $dokumen->jenis_dokumen,
+            'portal_dokumen_id' => $dokumen->portal_dokumen_id,
+            'file_path' => $dokumen->file_path,
+            'manual_nomor_surat' => $dokumen->manual_nomor_surat,
+            'manual_perihal' => $dokumen->manual_perihal,
+            'manual_tanggal_surat' => $dokumen->manual_tanggal_surat,
+            'penerbit_nip' => $dokumen->penerbit_nip,
+            'version' => $version,
+            'aktor_nip' => Auth::user()?->pegawaiInternal?->nip,
+            'status' => $status,
+            'catatan' => $catatan,
+        ]);
+    }
+    /**
+     * Catat percobaan simpan yang gagal ke riwayat (satu baris per objek
+     * target) agar ada jejak audit walau transaksi di-rollback.
+     */
+    private function snapshotGagalSimpan(string $jenisDokumen, array $objekIds, ?string $portalDokumenId, ?string $filePath, $request, string $pesan): void
+    {
+        try {
+            foreach ($objekIds as $idStr) {
+                $objekId = is_numeric($idStr) ? (int) $idStr : (int) $this->dekrip($idStr);
+                if (!$objekId) {
+                    continue;
+                }
+                $dokumenId = DokumenPenjadwalan::where('objek_pengawasan_id', $objekId)
+                    ->where('jenis_dokumen', $jenisDokumen)
+                    ->value('id');
+                $version = (DokumenPenjadwalanRiwayat::where('objek_pengawasan_id', $objekId)
+                    ->where('jenis_dokumen', $jenisDokumen)
+                    ->max('version') ?? 0) + 1;
+
+                DokumenPenjadwalanRiwayat::create([
+                    'dokumen_id' => $dokumenId,
+                    'objek_pengawasan_id' => $objekId,
+                    'jenis_dokumen' => $jenisDokumen,
+                    'portal_dokumen_id' => $portalDokumenId,
+                    'file_path' => $filePath,
+                    'manual_nomor_surat' => $request->input('manual_nomor_surat'),
+                    'manual_perihal' => $request->input('manual_perihal'),
+                    'manual_tanggal_surat' => $request->input('manual_tanggal_surat'),
+                    'penerbit_nip' => $request->input('penerbit_nip'),
+                    'version' => $version,
+                    'aktor_nip' => Auth::user()?->pegawaiInternal?->nip,
+                    'status' => 'gagal',
+                    'catatan' => mb_substr($pesan, 0, 1000),
+                ]);
+            }
+        } catch (\Throwable $auditE) {
+            Log::warning('[PenjadwalanService::simpanDokumen] Gagal catat riwayat gagal: ' . $auditE->getMessage());
+        }
+    }
+    /**
+     * Kembalikan dokumen ke versi riwayat tertentu (restore).
+     * Dipakai via artisan (tanpa perlu integrasi FE).
+     *
+     * @return array{message: string, version: int}
+     * @throws Exception
+     */
+    public function restoreDokumenObjek(int $objekId, string $jenisDokumen, int $version): array
+    {
+        $objek = $this->objekPengawasan->find($objekId);
+        if (!$objek) {
+            throw new Exception('Objek Pengawasan tidak ditemukan');
+        }
+
+        // Batas maksimal ubah dokumen: Hari H (selaras unggah/simpan/reset).
+        if ($objek->jadwal) {
+            if (now()->startOfDay()->gt(Carbon::parse($objek->jadwal)->startOfDay())) {
+                throw new Exception('Batas waktu ubah dokumen sudah berakhir. Dokumen hanya dapat diubah maksimal pada Hari H (Jadwal Inspeksi).');
+            }
+        }
+
+        $snap = DokumenPenjadwalanRiwayat::where('objek_pengawasan_id', $objekId)
+            ->where('jenis_dokumen', $jenisDokumen)
+            ->where('version', $version)
+            ->first();
+        if (!$snap) {
+            throw new Exception("Riwayat versi {$version} untuk {$jenisDokumen} tidak ditemukan.");
+        }
+
+        $dokumen = DokumenPenjadwalan::updateOrCreate(
+            ['objek_pengawasan_id' => $objekId, 'jenis_dokumen' => $jenisDokumen],
+            [
+                'portal_dokumen_id' => $snap->portal_dokumen_id,
+                'file_path' => $snap->file_path,
+                'manual_nomor_surat' => $snap->manual_nomor_surat,
+                'manual_perihal' => $snap->manual_perihal,
+                'manual_tanggal_surat' => $snap->manual_tanggal_surat,
+                'penerbit_nip' => $snap->penerbit_nip,
+                'tanggal_dokumen' => now(),
+            ]
+        );
+        $this->snapshotRiwayatDokumen($dokumen);
+
+        // Sinkronkan kolom legacy + evaluasi ulang (fase penjadwalan saja).
+        // Nilai legacy mengikuti pola dual-write simpanDokumen.
+        $legacyRestore = $dokumen->file_path ?: ($dokumen->portal_dokumen_id ? 'csrs:' . $dokumen->portal_dokumen_id : null);
+        if ($jenisDokumen === 'stkl') {
+            $objek->stkl = $legacyRestore;
+        } elseif ($jenisDokumen === 'surat_tugas') {
+            $objek->surat_tugas = $dokumen->portal_dokumen_id ? 'korespondensi' : 'manual';
+        } elseif (str_contains($jenisDokumen, 'surat_pemberitahuan')) {
+            $objek->surat_pemberitahuan = $legacyRestore;
+        }
+        $objek->save();
+
+        if (in_array($objek->status, ObjekPengawasan::STATUS_PRA_INSPEKSI, true)) {
+            $this->evaluasiStatusPenjadwalan($objek->fresh());
+        }
+
+        return ['message' => "Dokumen {$jenisDokumen} dikembalikan ke versi {$version}.", 'version' => $version];
+    }
+    /**
+     * Unggah Dokumen Manual (Single File Upload)
+     */
+    public function unggahDokumen($request): JsonResponse
+    {
+        DB::beginTransaction();
+        try {
+            $this->authorizeAksi('ppbbr.penjadwalan.dokumen.unggah.store');
+
+            $jenisDokumen = $request->jenis_dokumen;
+            $objekId = $this->dekrip($request->objek_pengawasan_id);
+            $objek = $this->objekPengawasan->find($objekId);
+
+            if (!$objek) {
+                return $this->onError('Objek Pengawasan tidak ditemukan');
+            }
+
+            // Batas maksimal upload/ubah dokumen: Hari H
+            if ($objek->jadwal) {
+                if (now()->startOfDay()->gt(Carbon::parse($objek->jadwal)->startOfDay())) {
+                    return $this->onError('Batas waktu unggah/ubah dokumen sudah berakhir. Dokumen hanya dapat diunggah maksimal pada Hari H (Jadwal Inspeksi).');
+                }
+            }
+
+            // Implementasi Rate Limiter untuk Upload Manual (Max 5x, cooldown sama seperti Cari Surat)
+            $userId = Auth::id() ?? 0;
+            $limitKey = "ppbbr:upload_manual:{$userId}:{$jenisDokumen}:{$objekId}";
+
+            if (RateLimiter::tooManyAttempts($limitKey, 5)) {
+                $cooldownSeconds = RateLimiter::availableIn($limitKey);
+                $cooldownTimestamp = now()->addSeconds($cooldownSeconds)->toIso8601String();
+                return $this->onSuccess("Limit unggah manual tercapai, silahkan coba lagi dalam {$cooldownSeconds} detik", [
+                    'cooldown_until' => $cooldownTimestamp,
+                    'sisa_kesempatan' => 0,
+                ]);
+            }
+
+            RateLimiter::hit($limitKey, 120);
+            $sisaKesempatan = RateLimiter::remaining($limitKey, 5);
+
+            // Validasi urutan upload perdana
+            $this->validasiUrutanUpload($objek, $jenisDokumen);
+
+            // Upload manual fallback ke path lama agar backward compatible
+            $pathTarget = self::PATH_SURAT_TUGAS;
+            if ($jenisDokumen === 'stkl') $pathTarget = self::PATH_STKL;
+            else if ($jenisDokumen === 'notula') $pathTarget = self::PATH_NOTULA;
+            else if (str_contains($jenisDokumen, 'surat_pemberitahuan')) $pathTarget = self::PATH_SURAT_PEMBERITAHUAN;
+
+            $filePath = $this->fileService->storeOnStorage($request->file('file'), $pathTarget);
+
+            // 1. Simpan ke tabel relasi baru (ppbbr_dokumen_penjadwalan)
+            $dokumenUnggah = DokumenPenjadwalan::updateOrCreate(
+                [
+                    'objek_pengawasan_id' => $objek->id,
+                    'jenis_dokumen' => $jenisDokumen
+                ],
+                [
+                    'portal_dokumen_id' => null,
+                    'file_path' => $filePath,
+                    'tanggal_dokumen' => now(),
+                ]
+            );
+            $this->snapshotRiwayatDokumen($dokumenUnggah);
+
+            // 2. DUAL WRITE ke tabel legacy
+            $legacyValue = $filePath;
+
+            if ($jenisDokumen === 'stkl') {
+                $objek->stkl = $legacyValue;
+            } else if ($jenisDokumen === 'surat_tugas') {
+                $objek->surat_tugas = 'manual';
+            } else if (str_contains($jenisDokumen, 'surat_pemberitahuan')) {
+                $objek->surat_pemberitahuan = $legacyValue;
+            }
+
+            $objek->save();
+            $this->evaluasiStatusPenjadwalan($objek);
+
+            $dokumenPenjadwalan = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+                ->where('jenis_dokumen', $jenisDokumen)
+                ->first();
+
+            $dokumenResponse = [
+                'sisa_kesempatan' => $sisaKesempatan,
+            ];
+            if ($dokumenPenjadwalan) {
+                $dokumenResponse = array_merge($dokumenResponse, [
+                    'id' => $this->enkrip($dokumenPenjadwalan->id),
+                    'portal_dokumen_id' => null,
+                    'file_path' => $dokumenPenjadwalan->file_path,
+                    'file_url' => FileService::getUrl($dokumenPenjadwalan->file_path),
+                    'nomor_surat' => null,
+                    'tanggal_surat' => null,
+                    'is_manual' => true,
+                ]);
+            }
+
+            DB::commit();
+            return $this->onSuccess('Dokumen manual berhasil diunggah', $dokumenResponse);
+        } catch (Exception $e) {
+            DB::rollBack();
+            return $this->onError($e->getMessage());
+        }
+    }
+    /**
+     * Simpan Dokumen Penjadwalan (Mendukung Bulk Save dari CSRS/Ekstraksi)
+     */
+    public function simpanDokumen($request): JsonResponse
+    {
+        // Delegasi ke service LHP untuk jenis dokumen laporan
+        if ($request->jenis_dokumen === 'laporan') {
+            return (new LaporanHasilPengawasanService())->simpanLaporan($request);
+        }
+
+        DB::beginTransaction();
+        try {
+            $this->authorizeAksi('ppbbr.penjadwalan.dokumen.store');
+
+            $jenisDokumen = $request->jenis_dokumen;
+            $objekIds = $request->objek_pengawasan_ids;
+
+            $portalDokumenId = null;
+            if ($request->portal_dokumen_id) {
+                $decryptedId = $this->dekrip($request->portal_dokumen_id);
+                $portalDokumen = \Modules\Gateway\Entities\PortalDokumen::where('id', $decryptedId)
+                    ->orWhere('dokumen_id', $decryptedId)
+                    ->first();
+                if ($portalDokumen) {
+                    $portalDokumenId = $portalDokumen->id;
+                }
+            }
+            $filePath = null;
+
+            // Wajib ekstrak (minimal NKU current): Notula & ST. SP & STKL
+            // dikecualikan. Update metadata murni (record sudah ber-file/portal
+            // di semua objek target) bebas tanpa sesi.
+            $this->validasiWajibEkstrak($jenisDokumen, $request, $objekIds);
+
+            // Resolve file_path original dari objek utama (jika ini dokumen unggah manual)
+            // Tujuannya agar file fisik bisa di-share (bulk save) ke semua objek pengawasan yang dicentang
+            if (!$portalDokumenId && $request->route('id')) {
+                $primaryObjekId = $this->dekrip($request->route('id'));
+                if ($primaryObjekId) {
+                    $originalDoc = DokumenPenjadwalan::where('objek_pengawasan_id', $primaryObjekId)
+                        ->where('jenis_dokumen', $jenisDokumen)
+                        ->first();
+                    if ($originalDoc && $originalDoc->file_path) {
+                        $filePath = $originalDoc->file_path;
+                    }
+                }
+            }
+
+            // Upsert metadata ekstraksi jika dikirim (mengubah session_id menjadi filePath permanent)
+            if ($request->session_id) {
+                $ekstrakService = new EkstrakDokumenService();
+                $cacheData = $ekstrakService->ambilDariCache($request->session_id);
+                if ($cacheData && is_array($cacheData)) {
+                    // Cache data is now a flat array containing details, except for the file_path key which was injected
+                    $allEkstrak = array_filter($cacheData, function ($key) {
+                        return $key !== 'file_path';
+                    }, ARRAY_FILTER_USE_KEY);
+
+                    // Ambil temporary file path yang di-save saat ekstrak
+                    $tempPath = $cacheData['file_path'] ?? null;
+
+                    // Pindahkan ke storage permanen jika ada file_path di cache
+                    // (Diasumsikan di sini Anda memindahkan file dari temp_extract ke path_target)
+                    // KARENA KITA MENGGUNAKAN file yang sudah permanen dari /unggah, kita cukup pakai filePath yang ada di cache.
+                    if (!$filePath) {
+                        $filePath = $tempPath;
+                    }
+
+                    $ekstrakService->simpanPermanen($allEkstrak, $portalDokumenId, $filePath, $jenisDokumen);
+
+                    // Selalu bersihkan cache setelah selesai
+                    $ekstrakService->hapusCache($request->session_id);
+                }
+            }
+
+            // Jenis yang wajib ber-file fisik atau ber-portal CSRS: file wajib sudah
+            // ada via /unggah atau sesi ekstrak (SP/STKL gabungan: CSRS lolos via
+            // portal_dokumen_id, manual lolos via file). Mencegah phantom record
+            // (metadata tanpa file maupun portal). CSRS tidak terhalang karena
+            // portal ikut dihitung sebagai file efektif di bawah.
+            // Pengecekan per-objek di dalam loop agar update metadata (file sudah ada di DB)
+            // tetap lolos, dan bulk-save mewarisi file dari objek utama.
+            $jenisManualSaja = ['notula', 'surat_pemberitahuan', 'stkl'];
+
+            // Tandai otomatis kategori korespondensi untuk dokumen dari CSRS:
+            // ST/STKL -> STWAP, SP -> HUWAP. Jika belum ada di master data, buat otomatis.
+            $kategoriOtomatis = [
+                'surat_tugas' => ['kode' => 'STWAP', 'keterangan' => 'Surat Tugas pengawasan sektor sumber daya perikanan'],
+                'stkl' => ['kode' => 'STWAP', 'keterangan' => 'Surat Tugas pengawasan sektor sumber daya perikanan'],
+                'surat_pemberitahuan' => ['kode' => 'HUWAP', 'keterangan' => 'Himbauan Umum Wilayah Pengawasan'],
+            ];
+            
+            if (isset($kategoriOtomatis[$jenisDokumen]) && $portalDokumenId) {
+                $katData = $kategoriOtomatis[$jenisDokumen];
+                
+                // Ciptakan otomatis master datanya jika di DB (baik local/dev/prod) masih kosong
+                $kategori = Category::firstOrCreate(
+                    ['kode' => $katData['kode']],
+                    ['keterangan' => $katData['keterangan']]
+                );
+
+                DokumenCategory::updateOrCreate(
+                    ['dokumen_id' => $portalDokumenId],
+                    ['category_id' => $kategori->id]
+                );
+            }
+
+            $oldPortalDokumenIds = [];
+
+            foreach ($objekIds as $idStr) {
+                $objekId = is_numeric($idStr) ? $idStr : $this->dekrip($idStr);
+                $objek = $this->objekPengawasan->find($objekId);
+
+                if (!$objek) continue;
+
+                // Batas maksimal upload/ubah dokumen: Hari H
+                if ($objek->jadwal) {
+                    if (now()->startOfDay()->gt(Carbon::parse($objek->jadwal)->startOfDay())) {
+                        throw new Exception("Batas waktu unggah/ubah dokumen sudah berakhir untuk proyek {$objek->no_kode_proyek}. Dokumen hanya dapat diunggah maksimal pada Hari H (Jadwal Inspeksi).");
+                    }
+                }
+
+                // Validasi urutan upload perdana
+                $this->validasiUrutanUpload($objek, $jenisDokumen);
+
+                // 1. Simpan ke tabel relasi baru (ppbbr_dokumen_penjadwalan)
+                $dokumenPenjadwalan = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+                    ->where('jenis_dokumen', $jenisDokumen)
+                    ->first();
+
+                // Guard: dokumen manual-only wajib punya file (dari /unggah, sesi ekstrak,
+                // atau file yang sudah tersimpan di record ini). Mencegah phantom record
+                // (metadata tersimpan tapi file_path null) seperti kasus STKL & SP manual dulu.
+                $fileEfektif = $filePath ?: $portalDokumenId ?: $dokumenPenjadwalan?->file_path ?: $dokumenPenjadwalan?->portal_dokumen_id;
+                if (in_array($jenisDokumen, $jenisManualSaja) && !$fileEfektif) {
+                    throw new Exception("Unggah file {$jenisDokumen} terlebih dahulu sebelum menyimpan untuk proyek {$objek->no_kode_proyek}.");
+                }
+
+                if ($dokumenPenjadwalan) {
+                    if (isset($kategoriOtomatis[$jenisDokumen]) && $dokumenPenjadwalan->portal_dokumen_id && $dokumenPenjadwalan->portal_dokumen_id != $portalDokumenId) {
+                        $kodeKatLama = $kategoriOtomatis[$jenisDokumen]['kode'];
+                        $oldPortalDokumenIds[$kodeKatLama][] = $dokumenPenjadwalan->portal_dokumen_id;
+                    }
+
+                    // UPDATE: hanya timpa identitas bila ada nilai non-kosong.
+                    // Field yang dikosongkan/dihilangkan dari request dilewati agar
+                    // data existing tidak terhapus diam-diam ("" -> null merusak tanggal).
+                    foreach (['manual_nomor_surat', 'manual_tanggal_surat', 'manual_perihal', 'penerbit_nip'] as $field) {
+                        $nilai = $request->input($field);
+                        if ($nilai !== null && $nilai !== '') {
+                            $dokumenPenjadwalan->$field = $nilai;
+                        }
+                    }
+                    if ($request->has('is_dokumen_pendukung')) {
+                        $dokumenPenjadwalan->is_dokumen_pendukung = filter_var($request->is_dokumen_pendukung, FILTER_VALIDATE_BOOLEAN);
+                    }
+
+                    // Update portal_dokumen_id. Hanya notula yang selalu manual
+                    // (clear portal); SP/STKL/ST bisa via CSRS sehingga portal
+                    // dipertahankan bila ada.
+                    if (in_array($jenisDokumen, ['notula'], true)) {
+                        // Jenis manual-only: selalu clear portal_dokumen_id
+                        $dokumenPenjadwalan->portal_dokumen_id = null;
+                    } elseif ($portalDokumenId) {
+                        $dokumenPenjadwalan->portal_dokumen_id = $portalDokumenId;
+                    }
+
+                    if ($filePath) $dokumenPenjadwalan->file_path = $filePath;
+                    $dokumenPenjadwalan->save();
+                    $this->snapshotRiwayatDokumen($dokumenPenjadwalan);
+                } else {
+                    // CREATE: normalisasi string kosong menjadi null agar konsisten.
+                    $identitasBaru = [];
+                    foreach (['manual_nomor_surat', 'manual_tanggal_surat', 'manual_perihal', 'penerbit_nip'] as $field) {
+                        $nilai = $request->input($field);
+                        $identitasBaru[$field] = ($nilai !== null && $nilai !== '') ? $nilai : null;
+                    }
+
+                    $baru = DokumenPenjadwalan::create([
+                        'objek_pengawasan_id' => $objek->id,
+                        'jenis_dokumen' => $jenisDokumen,
+                        'portal_dokumen_id' => $portalDokumenId,
+                        'file_path' => $filePath,
+                        'tanggal_dokumen' => now(),
+                        'manual_nomor_surat' => $identitasBaru['manual_nomor_surat'],
+                        'manual_tanggal_surat' => $identitasBaru['manual_tanggal_surat'],
+                        'manual_perihal' => $identitasBaru['manual_perihal'],
+                        'penerbit_nip' => $identitasBaru['penerbit_nip'],
+                        'is_dokumen_pendukung' => $request->has('is_dokumen_pendukung') ? filter_var($request->is_dokumen_pendukung, FILTER_VALIDATE_BOOLEAN) : false,
+                    ]);
+                    $this->snapshotRiwayatDokumen($baru);
+                }
+
+                // 2. DUAL WRITE ke tabel legacy
+                // Gunakan filePath (sudah di-resolve global) atau fallback ke portal_dokumen_id
+                $legacyValue = $filePath ?: ($portalDokumenId ? "csrs:" . $portalDokumenId : null);
+
+                if ($jenisDokumen === 'stkl') {
+                    $objek->stkl = $legacyValue;
+                } else if ($jenisDokumen === 'surat_tugas') {
+                    $objek->surat_tugas = $portalDokumenId ? 'korespondensi' : 'manual';
+                } else if (str_contains($jenisDokumen, 'surat_pemberitahuan')) {
+                    $objek->surat_pemberitahuan = $legacyValue;
+                }
+
+                $objek->save();
+                $this->evaluasiStatusPenjadwalan($objek);
+            }
+
+            // Hapus flag kategori (STWAP/HUWAP) dari dokumen lama yang tergantikan
+            // (jika tidak lagi dipakai di tempat lain)
+            $kodeKategori = isset($kategoriOtomatis[$jenisDokumen]) ? $kategoriOtomatis[$jenisDokumen]['kode'] : null;
+            if ($kodeKategori && !empty($oldPortalDokumenIds[$kodeKategori] ?? [])) {
+                $kategoriLama = Category::where('kode', $kodeKategori)->first();
+                if ($kategoriLama) {
+                    foreach (array_unique($oldPortalDokumenIds[$kodeKategori]) as $oldId) {
+                        $masihDipakai = DokumenPenjadwalan::where('jenis_dokumen', $jenisDokumen)
+                            ->where('portal_dokumen_id', $oldId)
+                            ->exists();
+
+                        if (!$masihDipakai) {
+                            DokumenCategory::where('dokumen_id', $oldId)
+                                ->where('category_id', $kategoriLama->id)
+                                ->delete();
+                        }
+                    }
+                }
+            }
+
+            DB::commit();
+            return $this->onSuccess('Dokumen berhasil disimpan ke objek pengawasan');
+        } catch (Exception $e) {
+            DB::rollBack();
+
+            // Jejak audit percobaan gagal (di luar transaksi yang di-rollback).
+            $this->snapshotGagalSimpan(
+                $request->jenis_dokumen ?? 'tak-dikenal',
+                is_array($request->objek_pengawasan_ids ?? null) ? $request->objek_pengawasan_ids : [],
+                $portalDokumenId ?? null,
+                $filePath ?? null,
+                $request,
+                $e->getMessage()
+            );
+
+            return $this->onError($e->getMessage());
+        }
+    }
+    public function dokumenExisting(string $id): JsonResponse
+    {
+        try {
+            $objekPengawasanId = $this->dekrip($id);
+            $objekPengawasan = $this->objekPengawasan->find($objekPengawasanId);
+            if (!$objekPengawasan) {
+                return $this->onError('Objek Pengawasan tidak ditemukan');
+            }
+
+            $dokumen = DokumenPenjadwalan::with('portalDokumen')
+                ->where('objek_pengawasan_id', $objekPengawasanId)
+                ->get();
+
+            $nkuString = $objekPengawasan->no_kode_proyek;
+            $nkuList = [];
+            if (is_array($nkuString)) {
+                $nkuList = $nkuString;
+            } elseif (is_string($nkuString) && !empty($nkuString)) {
+                $decoded = json_decode($nkuString, true);
