+                    'surat_pemberitahuan' => null,
+                    'stkl' => null,
+                    'surat_tugas' => null
+                ],
+                // 'rekomendasi_dokumen' => []
+            ];
+
+            // if (!empty($nkuList)) {
+            //     $relevanMetadata = DokumenMetadata::whereIn('nilai', $nkuList)
+            //         ->whereNull('objek_pengawasan_id')
+            //         ->get();
+
+            //     foreach ($relevanMetadata as $meta) {
+            //         $result['rekomendasi_dokumen'][] = [
