+            //         ];
+            //     }
+            // }
+
+            foreach ($dokumen as $doc) {
+                $docUrl = null;
+                if ($doc->portal_dokumen_id && $doc->portalDokumen) {
+                    $portalDok = $doc->portalDokumen;
+                    $docUrl = $portalDok->dokumen ? url(str_replace($portalDok->dokumen_id, $this->enkrip($portalDok->dokumen_id), $portalDok->dokumen)) : null;
+                } else {
+                    $docUrl = FileService::getUrl($doc->file_path);
+                }
+
+                $details = [];
+                $metadataQuery = DokumenMetadata::query()->with(['objekPengawasan.unitKerja', 'objekPengawasan.satwasData']);
+                if ($doc->portal_dokumen_id) {
+                    $metadataQuery->where('portal_dokumen_id', $doc->portal_dokumen_id);
+                } else {
+                    $metadataQuery->where('file_path', $doc->file_path);
+                }
+                $metadatas = $metadataQuery->get();
+
+                $savedPenjadwalans = DokumenPenjadwalan::where('jenis_dokumen', $doc->jenis_dokumen)
+                    ->where(function ($q) use ($doc) {
+                        if ($doc->portal_dokumen_id) {
+                            $q->where('portal_dokumen_id', $doc->portal_dokumen_id);
+                        } else {
+                            $q->where('file_path', $doc->file_path);
+                        }
+                    })
+                    ->pluck('objek_pengawasan_id')
+                    ->toArray();
+
+                foreach ($metadatas as $meta) {
+                    $objekMatch = $meta->objekPengawasan;
+
+                    if ($objekMatch) {
+                        $isChecked = in_array($objekMatch->id, $savedPenjadwalans);
+
+                        // Sembunyikan yang tidak diceklis (tidak ada di DokumenPenjadwalan)
+                        if (!$isChecked) {
