+                        continue;
+                    }
+                }
+
+                $rawTanggal = !empty($doc->manual_tanggal_surat) ? $doc->manual_tanggal_surat : ($doc->portalDokumen->letter_date ?? $doc->portalDokumen->date ?? null);
