+                    'is_manual' => $doc->portal_dokumen_id ? false : true,
+                    'is_selected' => true,
+                    'is_dokumen_pendukung' => (bool) $doc->is_dokumen_pendukung,
+                    'details' => $details,
+                ];
+            }
+
+            return $this->onSuccess('Berhasil memuat dokumen existing', $result);
+        } catch (Exception $e) {
+            return $this->onError($e->getMessage());
+        }
+    }
