-    /**
-     * Unggah Dokumen Manual (Single File Upload)
-     */
-    public function unggahDokumen($request): JsonResponse
-    {
-        DB::beginTransaction();
-        try {
-            $this->authorizeAksi('ppbbr.penjadwalan.dokumen.unggah.store');
-
-            $jenisDokumen = $request->jenis_dokumen;
-            $objekId = $this->dekrip($request->objek_pengawasan_id);
-            $objek = $this->objekPengawasan->find($objekId);
-
-            if (!$objek) {
-                return $this->onError('Objek Pengawasan tidak ditemukan');
-            }
-
-            // Batas maksimal upload/ubah dokumen: Hari H
-            if ($objek->jadwal) {
-                if (now()->startOfDay()->gt(Carbon::parse($objek->jadwal)->startOfDay())) {
-                    return $this->onError('Batas waktu unggah/ubah dokumen sudah berakhir. Dokumen hanya dapat diunggah maksimal pada Hari H (Jadwal Inspeksi).');
-                }
-            }
-
-            // Implementasi Rate Limiter untuk Upload Manual (Max 5x, cooldown sama seperti Cari Surat)
-            $userId = Auth::id() ?? 0;
-            $limitKey = "ppbbr:upload_manual:{$userId}:{$jenisDokumen}:{$objekId}";
-
-            if (RateLimiter::tooManyAttempts($limitKey, 5)) {
-                $cooldownSeconds = RateLimiter::availableIn($limitKey);
-                $cooldownTimestamp = now()->addSeconds($cooldownSeconds)->toIso8601String();
-                return $this->onSuccess("Limit unggah manual tercapai, silahkan coba lagi dalam {$cooldownSeconds} detik", [
-                    'cooldown_until' => $cooldownTimestamp,
-                    'sisa_kesempatan' => 0,
-                ]);
-            }
-
-            RateLimiter::hit($limitKey, 120);
-            $sisaKesempatan = RateLimiter::remaining($limitKey, 5);
-
-            // Validasi urutan upload perdana
-            $this->validasiUrutanUpload($objek, $jenisDokumen);
-
-            // Upload manual fallback ke path lama agar backward compatible
-            $pathTarget = self::PATH_SURAT_TUGAS;
-            if ($jenisDokumen === 'stkl') $pathTarget = self::PATH_STKL;
