+            }
+
+            $idxPertamaKosong = array_search($kosong[0], $urutanJenis, true);
+            $turunanAda = array_values(array_filter(
+                $ada,
+                fn ($j) => array_search($j, $urutanJenis, true) > $idxPertamaKosong
+            ));
+            if (empty($turunanAda)) {
+                continue;
+            }
+
+            $objek = ObjekPengawasan::find((int) $objekId);
+            if (!$objek) {
+                continue;
+            }
+
+            $hasil[] = ['objek' => $objek, 'hilang' => $kosong[0], 'ada' => $turunanAda];
+        }
+
+        return $hasil;
