+     * Turunkan Menunggu Inspeksi -> Lengkapi Dokumen bila keempat dokumen
+     * (kehadiran file/portal) jadi tak lengkap. Objek lain tidak disentuh.
+     * Selalu save agar perubahan kolom legacy ikut tersimpan.
+     */
+    private function turunkanStatusJikaTakLengkap(ObjekPengawasan $objek): bool
+    {
+        $dokumens = DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+            ->where(function ($q) {
+                $q->whereNotNull('file_path')->orWhereNotNull('portal_dokumen_id');
+            })
+            ->pluck('jenis_dokumen')->all();
+        $lengkap = in_array('notula', $dokumens)
+            && in_array('stkl', $dokumens)
+            && in_array('surat_pemberitahuan', $dokumens)
+            && in_array('surat_tugas', $dokumens);
+
+        $turun = false;
+        if (!$lengkap && $objek->status === ObjekPengawasan::MenungguInspeksi) {
+            $objek->status = ObjekPengawasan::LengkapiDokumen;
+            $turun = true;
+        }
+        $objek->save();
+
+        return $turun;
+    }
