+/**
+ * Menguji ppbbr:audit-ekstrak-dokumen: deteksi jomplang (turunan ada
+ * tanpa prasyarat) pada mode laporan dan perapian saat --perbaiki.
+ */
+class AuditEkstrakDokumenCommandTest extends TestCase
+{
+    use DatabaseTransactions;
+
+    private function buatUnit(): UnitKerja
+    {
+        return UnitKerja::create([
+            'kode_unit' => 'U-' . rand(100000, 999999),
+            'nama_unit' => 'Unit Audit ' . uniqid(),
+            'nama_akronim' => 'TU' . rand(10, 99),
+            'kategori_unit' => 'UPT',
+        ]);
+    }
+
+    private function buatObjek(string $status): ObjekPengawasan
+    {
+        \App\Models\Master\KBLI::firstOrCreate(
+            ['kbli' => '03111'],
+            ['uraian_kbli' => 'Penangkapan Ikan di Laut']
+        );
+
+        return ObjekPengawasanFactory::new()->create([
+            'status' => $status,
+            'unit_kerja' => $this->buatUnit()->kode_unit,
+            'jadwal' => now()->addMonth()->toDateString(),
+        ]);
+    }
+
+    private function tambahDokumen(ObjekPengawasan $objek, string $jenis): DokumenPenjadwalan
+    {
+        return DokumenPenjadwalan::create([
+            'objek_pengawasan_id' => $objek->id,
+            'jenis_dokumen' => $jenis,
+            'file_path' => "storage/uat/{$jenis}.pdf",
+        ]);
+    }
+
+    private function jumlahDokumen(ObjekPengawasan $objek, string $jenis): int
+    {
+        return DokumenPenjadwalan::where('objek_pengawasan_id', $objek->id)
+            ->where('jenis_dokumen', $jenis)
+            ->count();
+    }
+
+    /** @test */
+    public function laporan_mendeteksi_objek_jomplang()
+    {
+        // Notula tidak pernah ada, STKL & SP tersisa → jomplang.
+        $objek = $this->buatObjek(ObjekPengawasan::MenungguInspeksi);
+        $this->tambahDokumen($objek, 'stkl');
+        $this->tambahDokumen($objek, 'surat_pemberitahuan');
+
+        $exit = Artisan::call('ppbbr:audit-ekstrak-dokumen');
+        $keluaran = Artisan::output();
+
+        $this->assertSame(0, $exit);
+        $this->assertStringContainsString('Objek jomplang (turunan ada tanpa prasyarat): 1', $keluaran);
+        $this->assertStringContainsString("objek {$objek->id} hilang=[notula]", $keluaran);
+        // Mode laporan tidak mengubah apa pun.
+        $this->assertEquals(1, $this->jumlahDokumen($objek, 'stkl'));
+    }
+
+    /** @test */
+    public function perbaiki_merapikan_jomplang_fase_penjadwalan()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::MenungguInspeksi);
+        // Notula tanpa metadata → tak valid, ikut terhapus oleh loop utama.
+        $this->tambahDokumen($objek, 'notula');
+        $this->tambahDokumen($objek, 'stkl');
+        $this->tambahDokumen($objek, 'surat_pemberitahuan');
+
+        $exit = Artisan::call('ppbbr:audit-ekstrak-dokumen', ['--perbaiki' => true]);
+        $keluaran = Artisan::output();
+
+        $this->assertSame(0, $exit);
+        $this->assertStringContainsString('Baris jomplang dihapus: 2', $keluaran);
+        foreach (['notula', 'stkl', 'surat_pemberitahuan'] as $jenis) {
+            $this->assertEquals(0, $this->jumlahDokumen($objek, $jenis), "jenis {$jenis} harus ikut terhapus");
+        }
+        $this->assertEquals(ObjekPengawasan::LengkapiDokumen, $objek->fresh()->status);
+    }
+
+    /** @test */
+    public function perbaiki_tidak_menyentuh_jomplang_status_inspeksi()
+    {
+        $objek = $this->buatObjek(ObjekPengawasan::Inspeksi);
+        $this->tambahDokumen($objek, 'stkl');
+        $this->tambahDokumen($objek, 'surat_pemberitahuan');
+
+        $exit = Artisan::call('ppbbr:audit-ekstrak-dokumen', ['--perbaiki' => true]);
+        $keluaran = Artisan::output();
+
+        $this->assertSame(0, $exit);
+        $this->assertStringContainsString("objek {$objek->id} jomplang dilewati", $keluaran);
+        $this->assertEquals(1, $this->jumlahDokumen($objek, 'stkl'), 'objek Inspeksi: review manual, baris tidak dihapus');
+        $this->assertEquals(1, $this->jumlahDokumen($objek, 'surat_pemberitahuan'));
+        $this->assertEquals(ObjekPengawasan::Inspeksi, $objek->fresh()->status);
+    }
+}
